import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-b1-001","clusterId":"B","werkstueckRef":"B.1","stufe":1,"question":"Eine Kollegin ist überzeugt, ihr neuer Kollege sei unzuverlässig. Seit Wochen sammelt sie jede seiner Verspätungen und erzählt davon. Dass er gestern ein Projekt pünktlich und sauber abgeliefert hat, nennt sie „reinen Zufall“. Was ist an ihrem Vorgehen am ehesten fehlerhaft?","options":["Sie hält an einem Urteil fest, weil sie schon viel Mühe in ihre Sammlung von Belegen investiert hat.","Sie übernimmt das Urteil, weil es im Team von den meisten anderen ebenfalls geteilt wird.","Sie sucht, deutet und behält Informationen so, dass sie ihr bestehendes Urteil stützen, und wertet Gegenteiliges ab.","Sie führt sein Verhalten auf seinen Charakter zurück und übersieht die Umstände, in denen er handelt."],"correctIndex":2,"explanation":"Die Kollegin prüft ihr Urteil nicht, sie dekoriert es. Sie sammelt gezielt, was passt (einseitige Suche), und erklärt den Gegenbeleg zum „Zufall“ (einseitige Deutung). Auch die Erinnerung läuft bei diesem Muster typischerweise einseitig: Gründe für die eigene Seite werden eher gefunden und behalten. Das ist der Bestätigungsfehler: keine bloße Sturheit, sondern ein Verarbeitungsmuster auf diesen drei Ebenen. Die übrigen Optionen beschreiben andere Gründe fürs Festhalten oder Urteilen (Mühe, Gruppenmeinung, Charakterzuschreibung). Hier entscheidet die dreifach einseitige Verarbeitung von Informationen. Es fehlt vor allem eines: der ernsthafte Versuch, das eigene Urteil zu widerlegen.","coreRule":"⚡ Suche zuerst nach dem stärksten Beleg gegen deine Position, nicht nach dem nächsten dafür.","quote":"Er hat nicht ermittelt. Er hat nur seine anfängliche Vermutung dekoriert.","quoteLabel":"Merksatz:","beleg":"Werkstück B.1 (Der Detektiv und der Gärtner; Kernidee; Kontext & Tiefe, drei Ebenen)","status":"entwurf","scenario":"","kurz":"Sie prüft ihr Urteil nicht, sondern stützt es: Verspätungen sammelt sie, den pünktlichen Erfolg erklärt sie zum „Zufall“. Das ist der Bestätigungsfehler. Es fehlt der ernsthafte Versuch, das eigene Urteil zu widerlegen.","prueffrage":"Was müsste der Kollege tun, damit sie ihr Urteil über ihn ändern würde?","rueckmeldung":[{"option":0,"text":"Wer viel Mühe in eine Sammlung gesteckt hat, kann leichter an seinem Urteil festhalten. Hier geht es aber um den Umgang mit Belegen: Sie sammelt gezielt, was passt, und erklärt den Gegenbeleg zum „Zufall“."},{"option":1,"text":"Dass Urteile oft aus der Gruppe übernommen werden, stimmt. Hier ist es aber anders: Sie ist selbst überzeugt und erzählt anderen davon; von einer Teammeinung, der sie sich anschließt, ist keine Rede."},{"option":3,"text":"Verhalten vorschnell dem Charakter statt den Umständen zuzuschreiben, ist ein verbreiteter Fehler und könnte hier mitspielen. Auffällig ist aber, wie sie mit Belegen umgeht: Sie sucht, deutet und behält einseitig. Das erklärt ihr Vorgehen genauer."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175, 178","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson (1998), Verlagsfassung APA","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Zusammenleben"},{"id":"qx-b1-002","clusterId":"B","werkstueckRef":"B.1","stufe":2,"question":"Was ist an diesem Vorgehen das Hauptproblem?","scenario":"Du willst einen Staubsaugerroboter kaufen und hast dich schon in ein Modell verliebt. Abends gibst du in die Suchmaschine „Modell X Vorteile“ und „Modell X begeisterte Erfahrungsberichte“ ein.","options":["Die Suchbegriffe fragen nur nach Zustimmung, sodass das Ergebnis schon vorgegeben ist, bevor etwas gelesen wird.","Die gefundenen Berichte sind mehrdeutig, und das lässt sich nur durch eine größere Zahl gelesener Treffer beheben.","Du wirst die kritischen Stimmen später vergessen, deshalb ist die Suche selbst für sich genommen unproblematisch.","Die Suchbegriffe benennen deine Vorliebe ehrlich, deshalb ist das Vorgehen unproblematisch und es fehlt höchstens ein Preisvergleich."],"correctIndex":0,"explanation":"Wer „Modell X Vorteile“ und „Modell X begeisterte Erfahrungsberichte“ eingibt, fragt nicht nach Belegen gegen das Modell, sondern nach Argumenten dafür. Das ist die tendenziöse Suche: Wir googeln nicht „Beweise gegen meine Position“, sondern „Argumente für meine Position“. Das Problem liegt hier auf der Ebene der Suche, noch bevor Deutung oder Erinnerung ins Spiel kommen. Eine Suche, die die Entscheidung wirklich prüft, würde gezielt auch nach „Kritik“, „Probleme mit“ oder „Gegenargumenten“ fragen.","coreRule":"⚡ Schon die Wahl der Suchbegriffe kann das Ergebnis vorwegnehmen: Wer nur nach Bestätigung fragt, findet nur Bestätigung.","beleg":"Werkstück B.1 (Kontext & Tiefe, Ebene „Suche“; Werkbank-Frage)","status":"entwurf","kurz":"Wer „Vorteile“ und „begeisterte Erfahrungsberichte“ eingibt, bekommt vor allem Lob zu sehen. Gesucht wird dann nach Argumenten für die eigene Vorliebe statt danach, was gegen sie sprechen könnte.","prueffrage":"Welche Wörter stehen in den beiden Suchanfragen, und nach welchen Wörtern wird dort gar nicht gesucht?","rueckmeldung":[{"option":1,"text":"Mehr Treffer zu lesen klingt gründlich. Alle stammen aber aus einer Suche, die nur nach Lob fragt, sodass auch viele gelesene Berichte kaum Kritik enthalten. Das Problem liegt schon bei den Suchbegriffen, nicht bei der Menge."},{"option":2,"text":"Selektives Erinnern ist ein echter Effekt, setzt aber voraus, dass kritische Stimmen überhaupt gefunden wurden. Hier bleiben sie durch die Suchbegriffe schon vorher draußen, die Suche ist also keineswegs unproblematisch."},{"option":3,"text":"Die Suchbegriffe zeigen deine Vorliebe tatsächlich offen, und ein Preisvergleich kann nützlich sein. Ehrlichkeit macht die Suche aber nicht prüfend: Sie fragt weiterhin nur nach Zustimmung und lässt Gegenargumente außen vor."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-b1-003","clusterId":"B","werkstueckRef":"B.1","stufe":3,"question":"Ein Freund investiert seit Jahren in ein Finanzsystem, das hohe Renditen garantiert. Mehrere Bekannte haben ihr Geld verloren, eine Verbraucherzentrale warnt, und die Auszahlungen stocken. Er sagt trotzdem: „Das sind alles Neider, mein System funktioniert.“ Warum ist sein Festhalten hier ein ernstes Problem und nicht nur eine harmlose Eigenart?","options":["Weil er überhaupt eine feste Überzeugung hat und schon jede feste Überzeugung neue Informationen filtert und so sein Urteil verzerrt.","Weil er vermutlich vor allem Medien liest, die zu seiner Haltung passen, und so schon jede Echokammer gefährlich wird.","Weil es hier um ein wichtiges Thema geht und er trotz deutlicher Gegenbeweise nicht umdenkt, weil ihm sein Weltbild wichtiger ist.","Weil er sich bei einer Sache täuscht, deren Faktenlage unklar ist, und weil schon jede Täuschung allein schädlich ist."],"correctIndex":2,"explanation":"Einseitige Informationsverarbeitung ist an sich oft harmlos: Wer glaubt, die eigene Fußballmannschaft sei die beste, richtet damit kaum Schaden an. Gefährlich wird es, wenn zwei Dinge zusammenkommen: Es geht um ein wichtiges Thema, und überwältigende Gegenbeweise ändern nichts mehr an der Meinung. Dann wird der Schutz des eigenen Weltbildes wichtiger als die Anerkennung der Realität, und Menschen bleiben in betrügerischen Finanzsystemen, folgen gefährlichen Kulten oder lehnen medizinisch notwendige Behandlungen ab. Eine feste Überzeugung oder einseitige Lektüre allein genügt dafür nicht, und eine Täuschung ist nicht automatisch schädlich. Entscheidend sind das wichtige Thema und die Unbeweglichkeit gegenüber überwältigenden Gegenbeweisen.","coreRule":"⚡ Kritisch wird es bei wichtigen Themen, wenn Gegenbeweise nichts mehr bewegen.","beleg":"Werkstück B.1 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Harmlos wäre das Festhalten bei einer Nebensache. Hier geht es aber um sein Geld, und trotz überwältigender Gegenbeweise ändert er nichts an seiner Meinung, weil ihm sein Weltbild wichtiger ist als die Realität.","prueffrage":"Welche Warnzeichen liegen ihm schon vor, und wie erklärt er sie sich?","rueckmeldung":[{"option":0,"text":"Feste Überzeugungen können Informationen tatsächlich filtern, doch das bleibt oft harmlos, etwa bei der Lieblingsmannschaft. Ernst wird es erst, wenn ein wichtiges Thema und Unbeweglichkeit gegenüber überwältigenden Gegenbeweisen zusammenkommen."},{"option":1,"text":"Einseitige Medien können das Urteil verzerren. Über seinen Medienkonsum ist hier aber nichts bekannt, und einseitige Lektüre allein macht noch nichts gefährlich; entscheidend ist, dass er trotz klarer Gegenbeweise nicht umdenkt."},{"option":3,"text":"Dass er sich täuscht, ist sehr wahrscheinlich, doch die Faktenlage ist nicht unklar: Verluste, Warnung und stockende Auszahlungen sprechen deutlich. Ernst wird es, weil er trotz dieser Gegenbeweise bei einem wichtigen Thema nicht umdenkt."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b1-004","clusterId":"B","werkstueckRef":"B.1","stufe":4,"question":"Welche Einschätzung dieser Reaktion trifft zu?","scenario":"Du erzählst einem Bekannten, dass eine Behörde seine Behauptung über eine geheime Absprache geprüft und widerlegt hat. Er antwortet: „Genau das würden sie ja sagen – das beweist es erst recht!“","options":["Er prüft die Behauptung damit besonders gründlich, weil gesundes Misstrauen gegenüber Behörden dafür sorgt, dass er keine Aussage ungeprüft hinnimmt.","Er deutet auch die Widerlegung als weiteren Beleg um, sodass nichts mehr gegen seine Überzeugung sprechen kann.","Er hat die Aussage der Behörde schlicht nicht richtig verstanden, weil ihm das nötige Hintergrundwissen zu dem Thema fehlt.","Er verteidigt seine Überzeugung zu Recht, weil eine offizielle Widerlegung durch eine Behörde grundsätzlich als unglaubwürdig gelten muss."],"correctIndex":1,"explanation":"Wenn auch die Widerlegung als Beweis gilt, wird der Glaube zur „sich selbst versiegelnden Schleife“: Jedes Ereignis, egal wie unzusammenhängend, wird als weiterer Beweis gedeutet. Das ist der Bestätigungsfehler, die Neigung, Informationen so zu deuten, dass sie die eigene Überzeugung stützen. Die anderen Antworten passen nicht: Hier wird nicht gründlicher geprüft, sondern einseitig gedeutet, und es zeigt sich keine bloße Wissenslücke. Dass eine offizielle Widerlegung grundsätzlich unglaubwürdig sei, ist genau die Umdeutung, mit der sich die Überzeugung gegen jeden Einwand abschirmt. Eine hilfreiche Gegenfrage lautet: Welches Ergebnis würde er überhaupt als Widerlegung gelten lassen?","coreRule":"⚡ Wenn selbst die Widerlegung als Bestätigung zählt, kann nichts mehr gegen die Überzeugung sprechen.","beleg":"Werkstück B.1 (Anwendung & Relevanz: Bei Verschwörungsmythen)","status":"entwurf","kurz":"Wenn auch die Widerlegung als Beweis gilt, kann nichts mehr gegen die Überzeugung sprechen: Sie wird zur sich selbst versiegelnden Schleife. Der Denkfehler ist der Bestätigungsfehler, alles so zu deuten, dass es die eigene Überzeugung stützt.","prueffrage":"Welche neue Information über die Absprache bringt der Bekannte vor, nachdem er von der Prüfung gehört hat?","rueckmeldung":[{"option":0,"text":"Misstrauen gegenüber Behörden kann durchaus zum Nachprüfen anregen, hier führt es aber zu keiner Prüfung. Die Widerlegung wird nicht untersucht, sondern einseitig umgedeutet; das ist das Gegenteil von Gründlichkeit."},{"option":2,"text":"Eine solche Reaktion lässt leicht an eine Wissenslücke denken. Für fehlendes Hintergrundwissen spricht hier aber nichts: Er nimmt die Widerlegung auf und deutet sie zugunsten seiner Überzeugung um."},{"option":3,"text":"Behörden können irren oder Interessen haben, und ihre Aussagen darf man prüfen. Sie aber grundsätzlich für unglaubwürdig zu erklären, schirmt die Überzeugung gegen jeden Einwand ab und ersetzt die Prüfung durch eine Pauschalregel."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"178","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-b1-005","clusterId":"B","werkstueckRef":"B.2","stufe":1,"question":"Eine Kollegin stellt nach drei Wochen Einarbeitung fest: „Ich habe die Fehler in meinem Bericht gar nicht bemerkt. Ich hielt ihn für einwandfrei, dabei war er voller Mängel.“ Welche Erklärung für diese Lage ist am sparsamsten?","options":["Sie hat schwach gearbeitet und besitzt zugleich noch nicht die Fähigkeiten, die nötig sind, um die eigenen Fehler zu bemerken.","Sie hat schwach gearbeitet und wird deshalb von ihrem Umfeld gemieden, sodass sie keine ehrliche Rückmeldung zu ihrem Bericht bekommt.","Sie hat sich überschätzt, so wie sich jeder überschätzt, nur dass Anfänger es etwas stärker tun als erfahrene Kollegen.","Sie scheut Verantwortung und hat den Bericht deshalb nicht gründlich geprüft, obwohl sie die Fehler hätte erkennen können."],"correctIndex":0,"explanation":"Hier greifen zwei Probleme ineinander: Die Leistung ist schlecht, und zugleich fehlt der Maßstab, um das zu merken. Die Fähigkeiten, die man für einen guten Bericht braucht, sind dieselben, die man braucht, um die Qualität eines Berichts zu beurteilen. Wer sie noch nicht hat, kann seine Fehler also nicht erkennen, und die Selbstsicherheit bleibt hoch. So beschreiben es Dunning und Kruger; wie viel davon echte metakognitive Blindheit und wie viel ein statistischer Effekt ist, ist in der Fachliteratur umstritten. Die Erklärung mit dem gemiedenen Umfeld ist unnötig kompliziert: Sie setzt eine zusätzliche Entwicklung voraus, die im Fall gar nicht vorkommt. Die Erklärung mit der Verantwortungsscheu unterstellt, dass die Fehler erkennbar gewesen wären, und genau das ist hier unplausibel. Auch das „Alle überschätzen sich“ passt nicht: In der Studie von Kruger und Dunning (1999) lag das schwächste Viertel beim 12. Perzentil und hielt sich für das 68., während das beste Viertel beim 86. lag und sich für das 74. hielt. Das Problem betrifft also nicht alle gleich, es trifft die Schwächsten am härtesten.","coreRule":"⚡ Wem das Können fehlt, dem fehlt oft auch der Maßstab, um das zu bemerken.","beleg":"Werkstück B.2 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Zwei Probleme greifen ineinander: Der Bericht ist schwach, und zugleich fehlt der Maßstab, das zu bemerken, weil beides dieselben Fähigkeiten verlangt. Zusatzannahmen wie Meidung durch das Umfeld oder Verantwortungsscheu braucht diese Erklärung nicht.","prueffrage":"Welche Annahmen musst du über die Kollegin treffen, die der Fall selbst gar nicht erwähnt?","rueckmeldung":[{"option":1,"text":"Fehlende ehrliche Rückmeldung kann Selbsttäuschung zwar begünstigen. Von einer Meidung durch das Umfeld weiß man hier aber nichts; die Erklärung braucht also eine zusätzliche Entwicklung und ist deshalb nicht die sparsamste."},{"option":2,"text":"Dass Anfänger sich stärker überschätzen, stimmt. Aber nicht alle überschätzen sich: Bei Kruger und Dunning (1999) lag das schwächste Viertel beim 12. Perzentil und sah sich beim 68., das beste lag beim 86. und sah sich beim 74."},{"option":3,"text":"Hier steckt die Annahme, die Fehler wären für sie erkennbar gewesen und sie habe nur nicht genau genug geprüft. Wem der Maßstab fehlt, dem fallen die Mängel auch bei sorgfältiger Prüfung kaum auf, und für Verantwortungsscheu gibt es keinen Hinweis."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121"},{"typ":"doi","kurz":"Magnus, J. R.; Peresetsky, A. A. (2022): A Statistical Explanation of the Dunning–Kruger Effect. Frontiers in Psychology 13","oeffentlich":true,"doi":"10.3389/fpsyg.2022.840180","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nuhfer, E. u. a. (2016): Random Number Simulations Reveal How Random Noise Affects the Measurements and Graphical Portrayals of Self-Assessed Competency. Numeracy 9(1), Art. 4","oeffentlich":true,"doi":"10.5038/1936-4660.9.1.4","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b1-007","clusterId":"B","werkstueckRef":"B.2","stufe":2,"question":"Was verrät diese Szene über die Verlässlichkeit der Einschätzung deines Nachbarn?","scenario":"Dein Nachbar hat sich zwei Wochen lang Videos zur Gebäudestatik angesehen. Beim Hausbau erklärt er dem Bauingenieur, dessen Berechnungen seien „unnötig kompliziert“, und Experten seien ohnehin „alle gekauft“. Auf die Nachfrage, wie die Lasten im Dachstuhl verteilt werden, weicht er aus und wiederholt nur, er sehe das „ganz klar“.","options":["Seine große Gewissheit nach kurzer Beschäftigung und die pauschale Abwertung der Fachleute sprechen eher für Selbstüberschätzung als für echte Sachkenntnis.","Gerade weil er sich so sicher ist, hat er vermutlich viel mehr verstanden als das, was er in zwei Wochen Videos hätte lernen können.","Dass er die Berechnungen hinterfragt, zeigt, dass er seine eigenen Argumente kritisch prüft und deshalb gut begründet an seiner Position festhält.","Wer Fachleute grundsätzlich anzweifelt, handelt als Skeptiker, und solche Skepsis ist ein verlässliches Zeichen für ein gründliches Verständnis des Themas."],"correctIndex":0,"explanation":"Wer nur kurz in ein komplexes Feld hineingeschaut hat, dem fehlen oft genau die Fähigkeiten, um die Lücken im eigenen Wissen zu erkennen; dann fühlt sich das wenige Gelernte wie ein vollständiges Bild an. Typische Anzeichen sind große Gewissheit nach kurzer Beschäftigung und das pauschale Abwerten von Fachleuten („alle gekauft“). Dazu passt, dass er der konkreten Sachfrage ausweicht: Echte Prüfung würde die Gegenargumente verstehen wollen, statt die Berechnungen als „unnötig kompliziert“ abzutun. Sicherheit allein sagt wenig darüber aus, ob jemand recht hat, und hier spricht die Konstellation eher für Selbstüberschätzung. Ob er im Einzelfall trotzdem etwas Richtiges sagt, bleibt offen und ließe sich nur an der Sache selbst prüfen.","coreRule":"⚡ Große Sicherheit nach kurzer Beschäftigung ist ein Warnzeichen, kein Qualitätsmerkmal.","beleg":"Werkstück B.2 (Red Flags; Anwendung & Relevanz: Das Betriebssystem der „Selber-Denker“)","status":"entwurf","kurz":"Große Gewissheit nach nur zwei Wochen und die pauschale Abwertung der Fachleute passen eher zu Selbstüberschätzung als zu Sachkenntnis, denn oft fehlen gerade die Fähigkeiten, die eigenen Lücken zu bemerken. Dass er ausweicht, passt dazu.","prueffrage":"Was antwortet dein Nachbar, wenn man ihn bittet, seine Einschätzung an einem konkreten Bauteil zu erklären?","rueckmeldung":[{"option":1,"text":"Große Sicherheit wirkt überzeugend, sagt aber wenig darüber aus, ob jemand recht hat. Mehr Wissen, als zwei Wochen Videos hergeben, zeigt er nirgends: Bei der konkreten Frage zur Lastverteilung bleibt er die Antwort schuldig."},{"option":2,"text":"Kritische Fragen an die Berechnungen sind grundsätzlich legitim. Wer seine Argumente wirklich prüft, nimmt aber auch Gegenargumente ernst; er dagegen weicht der Sachfrage aus und tut die Berechnungen als „unnötig kompliziert“ ab."},{"option":3,"text":"Gesunde Skepsis fragt nach Belegen und prüft sie. Ein Pauschalurteil wie „alle gekauft“ tut das nicht, es schiebt Gegenargumente nur beiseite. Daraus lässt sich nicht auf gründliches Verständnis schließen."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Light, N. u. a. (2022): Knowledge overconfidence is associated with anti-consensus views on controversial scientific issues. Science Advances 8(29), eabo0038 (frei über PMC9299547)","oeffentlich":true,"doi":"10.1126/sciadv.abo0038","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121"}],"thema":"Zusammenleben"},{"id":"qx-b1-008","clusterId":"B","werkstueckRef":"B.2","stufe":4,"question":"Wie weit trägt der Befund tatsächlich, und was ist an der Folgerung der Kommentatorin zu beanstanden?","scenario":"In einer Pressemitteilung heißt es: „Neue US-Befragung belegt: Wer dem wissenschaftlichen Konsens zu Impfungen, Gentechnik und Evolution am stärksten widerspricht, schätzt sein eigenes Wissen am höchsten ein, weiß im Mittel aber am wenigsten.“ Eine Kommentatorin schreibt dazu: „Damit ist bewiesen, dass Selbstüberschätzung die Ablehnung des Konsenses verursacht.“","options":["Der Befund zeigt nur, dass Merkmale gemeinsam auftreten, und sagt nichts darüber, was Ursache und was Wirkung ist.","Der Befund zeigt, dass Selbstüberschätzung die Ablehnung des Konsenses verursacht, und gilt für alle Themen gleich stark.","Der Befund gilt nur für Menschen ohne Studium und verschwindet bei Befragten mit höherem Abschluss vollständig.","Der Befund zeigt, dass Wissen und Zustimmung zum Konsens nichts miteinander zu tun haben, weil beide unabhängig sind."],"correctIndex":0,"explanation":"Die Kommentatorin springt von einem Zusammenhang auf eine Ursache. Eine Befragung misst, welche Merkmale gemeinsam auftreten, nicht was woraus folgt: Denkbar ist, dass Selbstüberschätzung zur Ablehnung führt, dass die Ablehnung das Gefühl von Besserwissen verstärkt oder dass ein dritter Faktor beides erzeugt. Dazu kommt die Reichweite: Der beschriebene Befund stammt aus fünf Studien in den USA (Light u. a. 2022, Science Advances) zu sieben Themen mit wissenschaftlichem Konsens, und bei stark politisierten Themen, vor allem beim Klimawandel, war der Zusammenhang schwächer. Ein „bewiesen“ und ein „gilt überall gleich“ gehen also weiter, als die Daten tragen. Ebenso wenig folgt ein Bildungsgefälle oder gar Unabhängigkeit: Der Befund beschreibt gerade einen Zusammenhang zwischen Selbsteinschätzung, tatsächlichem Wissen und Haltung zum Konsens. Als Waffe gegen Andersdenkende taugt er nicht.","coreRule":"⚡ Ein Zusammenhang aus Befragungen zeigt, was zusammen auftritt, nicht was woraus folgt.","beleg":"Werkstück B.2 (Anwendung & Relevanz); Fn. gl-b-light (Light u. a. 2022, Science Advances 8(29), eabo0038)","status":"entwurf","kurz":"Eine Befragung zeigt, was gemeinsam auftritt, nicht was woraus folgt. Selbstüberschätzung könnte die Ablehnung fördern, die Ablehnung das Besserwisser-Gefühl, oder ein dritter Faktor beides. „Bewiesen“ ist deshalb zu viel.","prueffrage":"Wurde bei den Befragten etwas gezielt verändert und die Folge beobachtet, oder wurde erfragt, was sie wissen und meinen?","rueckmeldung":[{"option":1,"text":"Die Befragung beschreibt, welche Merkmale zusammen auftreten, nicht, was welches verursacht. Der Zusammenhang war zudem nicht überall gleich stark: Bei stark politisierten Themen wie dem Klimawandel fiel er schwächer aus."},{"option":2,"text":"Von einer Beschränkung auf Menschen ohne Studium ist nirgends die Rede, und ein vollständiges Verschwinden bei höherem Abschluss ist nicht belegt. Ein Bildungsgefälle lässt sich aus dem Befund nicht ablesen."},{"option":3,"text":"Dass ein Zusammenhang keine Ursache beweist, heißt nicht, dass es keinen gibt. Der Befund beschreibt gerade einen Zusammenhang zwischen Selbsteinschätzung, Wissen und Haltung zum Konsens; Wissen und Zustimmung sind also nicht unabhängig."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Light, N.; Fernbach, P. M.; Rabb, N.; Geana, M. V.; Sloman, S. A. (2022): Knowledge overconfidence is associated with anti-consensus views on controversial scientific issues. Science Advances 8(29), eabo0038 (frei über PMC9299547)","oeffentlich":true,"doi":"10.1126/sciadv.abo0038","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-009","clusterId":"B","werkstueckRef":"B.3","stufe":1,"question":"Welche Einschätzung ist hier am ehesten ein Fehlschluss und warum?","options":["Sie schätzt das Hai-Risiko nach der Lebhaftigkeit der Bilder ein, die ihr leicht in den Sinn kommen, nicht nach der tatsächlichen Häufigkeit der Ereignisse.","Sie schätzt das Hai-Risiko nach der Meinung der Menschen in ihrem Umfeld ein, die alle ebenfalls vor dem Baden zurückschrecken.","Sie schätzt das Hai-Risiko nach der Höhe des möglichen Schadens ein, weil ein Angriff schwerer wiegt als ein Unfall.","Sie schätzt das Hai-Risiko nach der ersten Zahl ein, die ihr in den Nachrichten genannt wurde, und bleibt an dieser Zahl hängen."],"correctIndex":0,"explanation":"Mara beurteilt die Wahrscheinlichkeit danach, wie leicht ihr Beispiele einfallen. Ein dramatischer, frisch gesehener Fall mit starken Bildern ist mental sehr präsent, die Gefahr der Autofahrt dagegen nur eine blasse, abstrakte Statistik. Das Risiko, auf der Fahrt tödlich zu verunglücken, ist statistisch um ein Vielfaches höher als das, von einem Hai getötet zu werden. Leichtigkeit des Abrufs hängt von Emotionalität, Lebhaftigkeit, zeitlicher Nähe und medialer Wiederholung ab, nicht nur von der tatsächlichen Häufigkeit (Tversky und Kahneman, 1974). Die anderen Aussagen beschreiben andere Mechanismen (soziale Orientierung, Schadenshöhe, Ankereffekt), die im Szenario nicht vorkommen; hier liegt die Verfügbarkeitsheuristik vor.","coreRule":"⚡ Was mir leicht einfällt, erscheint mir wahrscheinlicher und wichtiger, auch wenn die Statistik etwas anderes sagt.","beleg":"Werkstück B.3 (Kernidee; Kontext & Tiefe); Fn. gl-b-verfuegbarkeit (Tversky/Kahneman 1974, Science 185(4157), S. 1127); Fn. gl-b-hai-auto (International Shark Attack File; NHTSA 2024, Overview of Motor Vehicle Traffic Crashes in 2022)","status":"entwurf","scenario":"Nach einer Woche voller Nachrichten über einen Hai-Angriff an einem Küstenort sagt Mara: „Ich gehe dort nicht mehr ins Wasser, das ist mir zu gefährlich.“ Am selben Tag fährt sie ohne zu zögern mit dem Auto zum Supermarkt. Ein Freund hält ihr vor, ihre Risikoeinschätzung sei verzerrt.","kurz":"Mara beurteilt die Gefahr danach, wie leicht ihr Beispiele einfallen, und nicht nach der tatsächlichen Häufigkeit. Der frische Hai-Fall ist bildstark und präsent, die Gefahr der Autofahrt bleibt eine blasse Statistik, obwohl sie deutlich höher ist.","prueffrage":"Was genau hat Mara in dieser Woche erfahren: eine Zahl, die Meinung von Bekannten oder Berichte über einen Fall?","rueckmeldung":[{"option":1,"text":"Dass sich Menschen am Umfeld orientieren, kommt vor und kann Urteile färben. Von der Meinung ihrer Bekannten ist hier aber keine Rede: Maras Angst folgt auf eine Woche voller Nachrichten über einen Angriff."},{"option":2,"text":"Ein Angriff wiegt schwer, und Schaden gehört in jede Risikoabwägung. Doch auch die Autofahrt kann tödlich enden, und zwar statistisch um ein Vielfaches häufiger; mit der Schwere allein lässt sich ihre Gelassenheit im Auto nicht erklären."},{"option":3,"text":"Ein Ankereffekt hieße, dass eine zuerst genannte Zahl das Urteil festhält. Hier ist aber von keiner Zahl die Rede, nur von Nachrichten über einen Angriff; es wirkt das Bild des Falls, nicht eine Ausgangszahl."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Florida Museum of Natural History, International Shark Attack File: Beach Injuries & Fatalities (Daten USLA, Stand Februar 2001)","oeffentlich":true,"url":"https://www.floridamuseum.ufl.edu/shark-attacks/odds/compare-risk/beach-injuries-fatalities/","abruf":"2026-10-12"},{"typ":"url","kurz":"NHTSA (2024): Overview of Motor Vehicle Traffic Crashes in 2022. DOT HS 813 560","oeffentlich":true,"url":"https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813560","seite":"1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Psychologie"},{"id":"qx-b1-010","clusterId":"B","werkstueckRef":"B.3","stufe":2,"question":"Was ist an der Schlussfolgerung deiner Kollegin fehlerhaft, und wie schätzt du dein Risiko stattdessen sinnvoll ein?","scenario":"Seit drei Tagen berichtet die Lokalpresse täglich über Wohnungseinbrüche in deiner Stadt, mit Fotos aufgebrochener Türen. Du merkst, dass du dich abends plötzlich unsicher fühlst. Eine Kollegin sagt: „Wenn ständig darüber berichtet wird, muss es ja wirklich häufiger geworden sein.“","options":["Sie schließt aus der Menge der Berichte auf die Häufigkeit der Fälle, obwohl Berichte nur zeigen, was die Redaktion aufgreift; du prüfst deshalb die langfristigen Zahlen für deinen Wohnort.","Sie schließt aus einzelnen Fällen auf die Wirklichkeit, obwohl Medien immer korrekt berichten; du prüfst deshalb vor allem, ob die Fotos in den Berichten echt sind.","Sie verlässt sich auf ihr Gefühl, obwohl Gefühle nie etwas über Gefahren aussagen; du verzichtest deshalb auf jede Einschätzung, bis du selbst betroffen bist.","Sie schließt aus der Häufung der Berichte auf ein reales Risiko, und das ist zulässig, weil Medien vor allem über Häufiges berichten; du bleibst deshalb bei deinem Eindruck."],"correctIndex":0,"explanation":"Wie viel über ein Thema berichtet wird, sagt zunächst etwas über die Berichterstattung, nicht über die Häufigkeit des Ereignisses selbst. Wiederholung und eindrückliche Bilder machen Fälle im Kopf leicht abrufbar, und was uns leicht einfällt, halten wir gern für häufig oder wahrscheinlich: die Verfügbarkeitsheuristik. Diese Faustregel ist im Alltag oft brauchbar, führt bei statistischen Risiken aber leicht in die Irre; ständige Berichte über Kriminalität können das Gefühl einer gefährlichen Welt erzeugen, selbst wenn die Kriminalitätsstatistiken sinken. Die passende Gegenfrage lautet: Was sagen die langfristigen, nüchternen Zahlen zur tatsächlichen Häufigkeit? Das Unsicherheitsgefühl ist dabei real, ersetzt aber keine Messung.","coreRule":"⚡ Wenn die Nachrichten laut sind, frag die langweilige Statistik.","quote":"Was sagen die langfristigen, langweiligen Statistiken über die tatsächliche Häufigkeit dieses Ereignisses?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.3 (Kontext & Tiefe: Mediale Wiederholung; Das Adaptive Talent; Das Anti-Denkmuster)","status":"entwurf","kurz":"Die Menge der Berichte zeigt zunächst, was die Redaktion aufgreift, nicht, wie oft Einbrüche tatsächlich passieren. Eindrückliche Bilder machen Fälle leicht abrufbar, und was leicht einfällt, wirkt häufig. Verlässlicher sind die langfristigen Zahlen.","prueffrage":"Über wie viele Einbrüche wurde in den drei Tagen berichtet, und woran erkennst du, ob das mehr sind als sonst?","rueckmeldung":[{"option":1,"text":"Fotos aufgebrochener Türen lassen die Berichte sehr konkret wirken, daher liegt die Prüfung ihrer Echtheit nahe. Echte Fotos sagen aber nichts darüber, wie oft Einbrüche vorkommen. Dafür brauchst du die langfristigen Zahlen."},{"option":2,"text":"Dass ein Gefühl keine Messung ersetzt, stimmt, wertlos ist es aber nicht. Auf jede Einschätzung zu verzichten ist unnötig, denn Zahlen lassen sich beschaffen; zudem schließt die Kollegin aus der Zahl der Berichte, nicht aus einem Gefühl."},{"option":3,"text":"Berichte können eine reale Häufung spiegeln, doch Medien greifen vor allem Auffälliges und Anschauliches auf, nicht einfach Häufiges. Dein Eindruck kann so entstehen, selbst wenn die Statistik sinkt, und braucht deshalb den Abgleich mit den Zahlen."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Pew Research Center (2016): Voters' perceptions of crime continue to conflict with reality","oeffentlich":true,"url":"https://www.pewresearch.org/short-reads/2016/11/16/voters-perceptions-of-crime-continue-to-conflict-with-reality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Availability Heuristic“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Netz und Medien"},{"id":"qx-b1-011","clusterId":"B","werkstueckRef":"B.3","stufe":3,"question":"Welche Schlussfolgerung zieht diese Auswertung am besten, ohne mehr in sie hineinzulesen, als sie hergibt?","options":["Das Risiko, im Meer zu ertrinken, und das Risiko im Straßenverkehr sind beide höher als das Risiko, von einem Hai getötet zu werden.","Das Meer ist ungefährlich, nur die Autofahrt birgt ein reales Risiko, deshalb ist die Angst vor dem Hai völlig unbegründet.","Haie töten pro Strandbesuch mehr Menschen als das Ertrinken, es fehlt in den Medien nur an passenden Bildern.","Die Daten zeigen lediglich, dass Hai-Angriffe selten sind, über das Ertrinken im Meer sagen sie nichts aus."],"correctIndex":0,"explanation":"Bei rund 264 Millionen Strandbesuchen starb niemand durch einen Hai, ertrunken ist dagegen etwa einer von 3,5 Millionen Besuchern. Die Bezugsgrößen passen nicht genau zusammen: Die meisten Ertrunkenen starben außerhalb der bewachten Abschnitte, und die Verkehrszahl bezieht sich auf gefahrene Meilen statt auf Strandbesuche. Genau verrechnen lassen sich die Zahlen deshalb nicht; die Rangfolge trägt trotzdem, weil in den Daten kein einziger Hai-Todesfall vorkommt, während Ertrinken und Straßenverkehr messbar Todesopfer fordern. Wer daraus „das Meer ist ungefährlich“ macht, übersieht das Ertrinken; das Risiko mit dem lebhaftesten Bild ist also nicht das größte. Eine Gefahr zu relativieren heißt aber nicht, sie zu leugnen.","coreRule":"⚡ Das Risiko mit dem dramatischsten Bild ist selten das mit den meisten Opfern.","beleg":"Werkstück B.3 (Die Angst vor dem Hai); Fn. gl-b-hai-auto (USLA-Daten, Stand Februar 2001; NHTSA 2024, S. 1)","status":"entwurf","scenario":"Nach einem Hai-Angriff in den Nachrichten meiden viele Urlauber das tiefe Wasser. Eine Auswertung von Strandbesuchen in den USA zeigt: Bei rund 264 Millionen Besuchen an bewachten Ozeanstränden starb kein einziger Mensch durch einen Hai. Ertrunken ist dagegen etwa einer von 3,5 Millionen Besuchern, die meisten außerhalb der bewachten Abschnitte. Im US-Straßenverkehr starben 2022 rund 1,33 Menschen je 100 Millionen gefahrene Meilen.","kurz":"Nach diesen Daten ist der Hai das seltenste der drei Risiken: Ertrinken und Straßenverkehr sind beide wahrscheinlicher. Das lebhafteste Bild zeigt also nicht die größte Gefahr, und harmlos ist das Meer wegen des Ertrinkens trotzdem nicht.","prueffrage":"Wie viele Todesfälle durch Haie nennt die Auswertung, und welche anderen Todesursachen beziffert sie?","rueckmeldung":[{"option":1,"text":"Nach diesen Zahlen ist der Hai tatsächlich das kleinste der drei Risiken. Ungefährlich ist das Meer deshalb nicht: Dieselben Daten nennen das Ertrinken als reales Risiko, und „völlig unbegründet“ ist mehr, als sie hergeben."},{"option":2,"text":"Hier ist der Vergleich umgedreht: Bei rund 264 Millionen Besuchen starb niemand durch einen Hai, ertrunken ist dagegen etwa einer von 3,5 Millionen. Über fehlende Medienbilder sagen die Zahlen zudem nichts."},{"option":3,"text":"Dass Hai-Angriffe selten sind, ist richtig. Die Auswertung nennt aber ausdrücklich auch das Ertrinken (etwa einer von 3,5 Millionen Besuchern); gerade der Vergleich beider Risiken ist ihr Kern."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Florida Museum of Natural History, International Shark Attack File: Beach Injuries & Fatalities (Daten USLA, Stand Februar 2001)","oeffentlich":true,"url":"https://www.floridamuseum.ufl.edu/shark-attacks/odds/compare-risk/beach-injuries-fatalities/","abruf":"2026-10-12"},{"typ":"url","kurz":"NHTSA (2024): Overview of Motor Vehicle Traffic Crashes in 2022. DOT HS 813 560","oeffentlich":true,"url":"https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813560","seite":"1","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b1-012","clusterId":"B","werkstueckRef":"B.3","stufe":4,"question":"Warum ist dein Eindruck, dass das Ritual funktioniert, so überzeugend, und was folgt daraus für die Bewertung?","scenario":"Du hast einmal im Stillen „um einen Parkplatz gebeten“ und sofort einen gefunden. Seitdem bist du überzeugt, dass das Ritual funktioniert. Auf Nachfrage räumst du ein, dass es in den allermeisten anderen Fällen nicht geklappt hat, du dich daran aber kaum erinnerst.","options":["Der Treffer ist lebhaft und leicht abrufbar, die Fehlschläge nicht; das Gefühl der Wirksamkeit sagt nichts über die Trefferquote aus.","Der Eindruck ist so stark, weil das Ritual bei innerer Überzeugung besonders gut wirkt; daher sollten die Fehlschläge nicht mitgezählt werden.","Erfolge prägen sich generell besser ein als Misserfolge; daher ist der Eindruck zwar verzerrt, die tatsächliche Trefferquote aber trotzdem hoch.","Fehlschläge sind keine Gegenbeispiele, weil man ein Ritual nur gelegentlich anwenden kann; daher zählt für die Bewertung allein der Treffer."],"correctIndex":0,"explanation":"Ein einzelner Zufallstreffer ist emotional und bildhaft, er fällt dir leicht wieder ein. Die vielen Fehlschläge sind unauffällig und verblassen. Weil uns leicht Abrufbares wichtig und häufig erscheint, entsteht der Eindruck von Wirksamkeit, ohne dass sich an der tatsächlichen Trefferquote etwas ändert. Man erinnert sich lebhaft an den einen Treffer und vergisst die hundert Male, bei denen es nicht funktioniert hat. Beurteilen lässt sich das Ritual deshalb nur an allen Versuchen, nicht an dem Treffer, der dir am lebhaftesten einfällt.","coreRule":"⚡ Bewerte ein Ritual nach allen Versuchen, nicht nach dem Treffer, der dir am lebhaftesten einfällt.","beleg":"Werkstück B.3 (Anwendung & Relevanz: Bei Esoterik & Aberglaube)","status":"entwurf","kurz":"Der Treffer ist bildhaft und fällt leicht ein, die vielen Fehlschläge verblassen. Dass etwas leicht abrufbar ist, lässt es häufig erscheinen, sagt aber nichts über die Trefferquote. Bewerten lässt sich das Ritual nur an allen Versuchen.","prueffrage":"Wie viele Versuche gab es insgesamt, und bei wie vielen davon klappte es?","rueckmeldung":[{"option":1,"text":"Eine Wirkung durch innere Überzeugung würde jeden Fehlschlag entschuldigen. Sie ist aber nur unterstellt, der starke Eindruck stammt vom einprägsamen Treffer, und gestrichen würden gerade die Gegenbeispiele, die über das Ritual am meisten verraten."},{"option":2,"text":"Hier blieb der Treffer haften, weil er auffällig war, nicht weil sich Erfolge generell besser einprägen. Vor allem folgt aus der verzerrten Erinnerung keine hohe Trefferquote: Die meisten Versuche schlugen fehl, daran ändert das Gedächtnis nichts."},{"option":3,"text":"Wer ein Ritual nur selten anwendet, hat wenige Versuche, und dennoch zählt jeder einzelne. Fehlschläge sind genau die Fälle, in denen das Ritual hätte wirken sollen. Streicht man sie, bleibt ein Treffer, der auch Zufall sein kann."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Availability Heuristic“, „Misleading Vividness“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Psychologie"},{"id":"qx-b1-013","clusterId":"B","werkstueckRef":"B.4","stufe":2,"question":"Was ist an deiner Argumentation fehlerhaft?","scenario":"Nach einem Derby sagst du: „Die Fans des anderen Vereins sind doch alle gleich – grölen, pöbeln, werfen mit Bechern.“ Auf den Einwand, dass auch in deiner eigenen Fankurve ein paar Leute Becher werfen, antwortest du: „Ja, aber unsere Leute sind ganz verschieden: Familien, Rentner, Studenten, Ultras. Da kann man nicht pauschal urteilen.“","options":["Du misst mit zweierlei Maß: Die fremde Gruppe siehst du als gleichförmige Masse, die eigene als Vielfalt einzelner Menschen.","Du verallgemeinerst aus einem einzelnen Vorfall: Von ein paar Bechern schließt du auf alle gegnerischen Fans.","Du folgst der Mehrheit in deiner Fankurve: Das Urteil über die anderen übernimmst du, ohne selbst zu prüfen.","Du erklärst das Verhalten der gegnerischen Fans mit ihrem Charakter: Die besonderen Umstände im Stadion blendest du aus."],"correctIndex":0,"explanation":"Dieses Muster heißt Outgroup-Homogenität: Wir sehen die Mitglieder einer fremden Gruppe als stereotype, homogene Masse („Die sind doch alle gleich“), die Mitglieder der eigenen Gruppe dagegen als vielfältige, einzigartige Individuen. Genau das passiert in deiner Argumentation: Die gegnerischen Fans fasst du zu einem einheitlichen Typus zusammen, bei deiner eigenen Kurve differenzierst du sofort. Ob dein Urteil trägt, prüfst du mit der Frage: Wie würde ich diese Aussage bewerten, wenn sie von einem Mitglied meiner eigenen Gruppe käme? Die anderen Antworten beschreiben echte, aber andere Denkfehler (Verallgemeinerung aus Einzelfällen, Anpassung an die Mehrheit, Attributionsfehler). Das Gespräch zeigt sie nicht: Von einem Einzelfall ist keine Rede, die Mehrheit gibt keine Meinung vor, und hier geht es nicht um die Ursache einzelner Handlungen, sondern um die Wahrnehmung der Gruppe als Ganzes.","coreRule":"⚡ Frag dich bei jeder Gruppe: Würde ich sie auch als „alle gleich“ beschreiben, wenn es meine eigene wäre? Wenn nicht, sprichst du über ein Klischee, nicht über Menschen.","quote":"„Die sind doch alle gleich.“","quoteLabel":"Typische Aussage:","beleg":"Werkstück B.4 (Kontext & Tiefe: Outgroup-Homogenität)","status":"entwurf","kurz":"Die gegnerischen Fans fasst du zu einer gleichförmigen Masse zusammen, bei der eigenen Kurve siehst du sofort Familien, Rentner, Studenten und Ultras. Die Gleichförmigkeit der anderen liegt dann im Blick auf sie, nicht in der Gruppe selbst.","prueffrage":"Wer steht an einem Spieltag alles in der gegnerischen Kurve?","rueckmeldung":[{"option":1,"text":"Pauschale Urteile über „alle“ beruhen oft auf wenigen Eindrücken. Hier ist aber von keinem einzelnen Vorfall die Rede, entscheidend ist der Unterschied zwischen fremder und eigener Gruppe: Die einen sind „alle gleich“, die anderen sofort verschieden."},{"option":2,"text":"Dass man Urteile von der eigenen Gruppe übernimmt, kommt vor. Im Gespräch gibt aber niemand eine Mehrheitsmeinung vor, und es geht nicht um Anpassung, sondern darum, wie die beiden Gruppen unterschiedlich wahrgenommen werden."},{"option":3,"text":"Verhalten mit Charakter statt Umständen zu erklären, ist ein bekannter Denkfehler, aber nicht dieser: Strittig ist nicht die Ursache einzelner Handlungen, sondern dass die Gegner als einheitliche Masse gelten, die eigene Kurve nicht."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Castano, E.; Yzerbyt, V. Y. (1998): The highs and lows of group homogeneity. Behavioural Processes 42 (Kopie auf der Seite von V. Yzerbyt, UCLouvain)","oeffentlich":true,"url":"https://perso.uclouvain.be/vincent.yzerbyt/Castano%20&%20Yzerbyt%20BP%201998.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Quattrone, G. A.; Jones, E. E. (1980): The perception of variability within in-groups and out-groups. JPSP 38(1)","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-b1-014","clusterId":"B","werkstueckRef":"B.4","stufe":1,"question":"Eine Schlagzeile erklärt das so: „Offenbar waren die Jungen schon vorher voller Vorurteile.“ Was spricht am stärksten gegen diese Erklärung?","options":["Die Jungen waren zuvor ganz normale Kinder, und die Feindseligkeit entstand erst im Lager, mit Gruppenbildung und Wettstreit.","Die Jungen stammten aus sehr unterschiedlichen sozialen Schichten, und die Feindseligkeit zeigte sich schon am ersten Tag.","Kinder in diesem Alter sind grundsätzlich zu jung, um Vorurteile zu entwickeln oder Feindseligkeit zu zeigen.","Die Jungen hatten sich zuvor nie gesehen, daher kann zwischen ihnen unmöglich Feindseligkeit entstanden sein."],"correctIndex":0,"explanation":"Die Erklärung „Vorurteile waren schon vorher da“ lässt sich an der zeitlichen Abfolge prüfen: Die Jungen waren vor dem Lager unauffällige Kinder und kannten einander nicht. Erst mit der Gruppenbildung und dem eigens inszenierten Wettkampf entstanden Abwertung, Flaggenverbrennung und Handgreiflichkeiten. Wenn sich ein Verhalten erst einstellt, nachdem die Umstände verändert wurden, liegt die Veränderung der Umstände als Ursache näher als eine verborgene Vorbelastung. Zugleich gilt: Der Wettstreit wurde von den Versuchsleitern gezielt konstruiert, und ein früherer Versuch (1953) scheiterte und wurde abgebrochen; nach Perrys Archivrecherche weigerten sich die Jungen dort, Feindseligkeit gegeneinander zu entwickeln. Das bekannte Lager war der dritte von drei Versuchen.","coreRule":"⚡ Passt eine Erklärung nicht zum zeitlichen Ablauf, prüfe zuerst, was sich unmittelbar vor der Wirkung verändert hat – und ob die Situation inszeniert wurde.","beleg":"Werkstück B.4 (Das Ferienlager-Experiment); Fn. gl-b-sherif (Sherif u. a. 1961, S. 18 und 96; Perry 2018)","status":"entwurf","scenario":"Zwei Gruppen unauffälliger elfjähriger Jungen, die sich vorher nie begegnet waren, verbringen Zeit in einem Ferienlager. Zuerst leben sie getrennt voneinander und geben sich eigene Namen und Flaggen. Dann lassen die Versuchsleiter sie in einem eigens entworfenen Wettkampf gegeneinander antreten. Im Verlauf dieses Wettkampfs beleidigen sich die Gruppen, verbrennen gegenseitig ihre Flaggen und werden handgreiflich.","kurz":"Feindseligkeit, die erst mit Gruppenbildung und inszeniertem Wettkampf auftritt, spricht eher für veränderte Umstände als Ursache als für verborgene Vorurteile. Die Schlagzeile schließt vom späteren Verhalten auf eine Vorbelastung und übersieht, was sich dazwischen änderte.","prueffrage":"Was taten die Jungen in der Zeit, als die beiden Gruppen noch getrennt lebten?","rueckmeldung":[{"option":1,"text":"Unterschiedliche Herkunft wirkt wie ein möglicher Nährboden für Vorurteile. Davon ist aber nirgends die Rede, und die Feindseligkeit zeigte sich erst mit Gruppenbildung und Wettkampf, nicht schon am ersten Tag."},{"option":2,"text":"Das Alter wirkt wie ein einfaches Argument, ist aber zu pauschal: Dass Kinder Feindseligkeit zeigen können, belegt schon das Ferienlager selbst. Gegen die Schlagzeile spricht die zeitliche Abfolge, nicht ein angeblich zu junges Alter."},{"option":3,"text":"Dass sich die Jungen nie gesehen hatten, stimmt, und es spricht gegen eine alte Vorgeschichte. Daraus folgt aber nicht, dass Feindseligkeit unmöglich wäre: Sie kann durchaus erst durch Umstände wie Wettkampf entstehen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Sherif, M. u. a. (1954/1961): Intergroup Conflict and Cooperation: The Robbers Cave Experiment, Vorwort 1954 (Classics in the History of Psychology, York University)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Sherif/preface1954.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Sherif, M. u. a. (1954/1961): The Robbers Cave Experiment, Kap. 3: Role of Staff, Subject Selection, Experimental Site (Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Sherif/chap3.htm","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Perry, G. (2018): The Lost Boys: Inside Muzafer Sherif's Robbers Cave Experiment. Melbourne: Scribe","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-015","clusterId":"B","werkstueckRef":"B.4","stufe":3,"question":"Welche Schlussfolgerung ist hier am besten begründet?","options":["Das stimmt nicht zwingend: Vorliebe für die eigene Gruppe kann ohne Abwertung anderer bestehen; Feindschaft braucht meist weitere Auslöser.","Die Behauptung stimmt: Wer die eigene Gruppe bevorzugt, wertet die anderen automatisch ab, denn mehr Wert für die einen bedeutet weniger Wert für die anderen.","Die Behauptung stimmt nur, wenn sich die Gruppen deutlich in Sprache, Kultur oder Aussehen unterscheiden und die Beteiligten diese Unterschiede bemerken.","Die Behauptung stimmt nur, wenn eine Gruppe deutlich größer und mächtiger ist als die andere, weil erst dieses Gefälle Ressentiments gegen die Stärkeren erzeugt."],"correctIndex":0,"explanation":"Die Behauptung setzt zwei Dinge gleich, die sich trennen lassen: Bevorzugung der eigenen Gruppe und Abwertung der fremden. Die Forschung (Brewer 1999) zeigt, dass Benachteiligung anderer allein aus der Vorliebe für die eigene Gruppe entstehen kann, ohne negative Gefühle oder feindselige Absicht gegenüber den anderen. Wer seinen Verein liebt, muss den Rivalen nicht verachten. Aus „A bevorzugt X“ folgt nicht „A wertet Y ab“. In Feindschaft kippt die Bindung erst unter zusätzlichen Bedingungen: wahrgenommene Bedrohung, Konkurrenz oder gezielte Aufhetzung durch Anführer. Wer „automatisch“ sagt, behauptet eine Notwendigkeit, wo es nur eine Möglichkeit gibt. Dagegen genügt ein einziges Gegenbeispiel, und genau das liefern die Befunde. Die übrigen Antworten nennen Voraussetzungen (auffällige Unterschiede, Machtgefälle), die in der Forschung nicht als nötig für Feindschaft belegt sind; belegt sind stattdessen Bedrohung, Konkurrenz und Aufhetzung.","coreRule":"⚡ Gruppenliebe ist nicht dasselbe wie Fremdenhass; sie kippt unter Bedrohung, Konkurrenz und Aufhetzung. Wer „zwangsläufig“ behauptet, muss zeigen, dass es keine Ausnahme gibt.","beleg":"Werkstück B.4 (Das Adaptive Talent); Fn. gl-b-brewer-kipp (Brewer 1999, Journal of Social Issues 55(3), S. 431, 434–438)","status":"entwurf","scenario":"In einer Diskussion über Fan-Rivalitäten sagt jemand: „Wer seinen Verein mehr liebt als andere Vereine, hasst die anderen automatisch. Liebe zur eigenen Gruppe und Hass auf die fremde sind dasselbe, nur von zwei Seiten betrachtet.“ Du sollst beurteilen, ob das stimmt.","kurz":"Vorliebe für die eigene Gruppe und Abwertung der anderen lassen sich trennen: Wer seinen Verein liebt, muss den Rivalen nicht verachten. Feindschaft entsteht meist erst durch Bedrohung, Konkurrenz oder Aufhetzung. „Automatisch“ macht aus einer Möglichkeit eine Notwendigkeit.","prueffrage":"Wann schlägt die Stimmung zwischen zwei Fanlagern tatsächlich in Feindseligkeit um, und wann bleibt es beim Necken?","rueckmeldung":[{"option":1,"text":"Dass Bevorzugung der eigenen Gruppe andere benachteiligen kann, stimmt. Abwertung oder Hass folgt daraus aber nicht: Wer den eigenen Verein höher stellt, muss den Rivalen nicht geringschätzen, und „automatisch“ behauptet eine Notwendigkeit."},{"option":2,"text":"Auffällige Unterschiede können Gruppengrenzen betonen. Als Voraussetzung für Feindschaft sind sie aber nicht belegt; belegt sind Bedrohung, Konkurrenz und Aufhetzung. Und Liebe und Hass blieben auch dann zwei verschiedene Dinge."},{"option":3,"text":"Ein Machtgefälle kann Groll erzeugen, aber als nötige Bedingung ist es nicht belegt; Konkurrenz, Bedrohung oder Aufhetzung wirken auch ohne Gefälle. Außerdem hielte auch diese Einschränkung an der Gleichsetzung von Liebe und Hass fest."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3) (inoffizielle Kopie auf Server des Bard College)","oeffentlich":true,"url":"https://bcsh.bard.edu/files/2019/06/Brewer-ingroup-love-or-outgroup-hate.pdf","seite":"431, 434–437","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3), Verlagsfassung","oeffentlich":false,"doi":"10.1111/0022-4537.00126"}],"thema":"Zusammenleben"},{"id":"qx-b1-016","clusterId":"B","werkstueckRef":"B.4","stufe":4,"question":"Welche Prüffrage setzt am Kern dieses Musters an?","scenario":"Ein Skandal in der Partei, die du wählst, ist für dich eine „Kampagne der Gegner“. Derselbe Skandal bei der anderen Partei ist für dich ein Beweis ihrer moralischen Verkommenheit.","options":["Welche der beiden Parteien hat in den vergangenen Jahren mehr Skandale gehabt, und wie schwer wogen sie jeweils?","Wie verlässlich sind die Medien, die über beide Parteien berichten, und welche Seite behandeln sie jeweils schonender?","Wie stark ist mein Gefühl der Entrüstung, wenn ich von dem Vorwurf gegen die andere Partei lese oder höre?","Würde ich dieselbe Handlung genauso bewerten, wenn die Rollen vertauscht wären und sie von der anderen Seite käme?"],"correctIndex":3,"explanation":"Das Muster ist ein doppelter Maßstab: Derselbe Vorgang gilt als „Kampagne“, wenn er die eigene Seite trifft, und als Beweis für „moralische Verkommenheit“, wenn er die andere trifft. Dahinter steckt die Gruppenzugehörigkeits-Verzerrung: Statt zu fragen, ob etwas wahr ist, fragt man, ob es der eigenen Seite nützt. Am Kern setzt an, wer seinen Maßstab auf die Probe stellt, indem er sich vorstellt, dieselbe Handlung käme von der anderen Seite, und prüft, ob das Urteil gleich bliebe. Fällt es anders aus, liegt die Asymmetrie in der Bewertung und nicht im Vorgang. Die anderen Fragen können sinnvoll sein, lösen aber das Problem nicht: Ein Vergleich der Skandalbilanz oder der Medienlage klärt Fakten, ändert aber nichts daran, dass derselbe Vorgang je nach Lager unterschiedlich gewogen wird. Und die Stärke der eigenen Entrüstung zu messen, wäre nur eine Beschreibung des Gefühls, kein Test des Maßstabs.","coreRule":"⚡ Vertausche die Rollen: Gilt mein Maßstab auch, wenn es um meine eigene Seite geht?","quote":"Ist das gut für uns oder für die?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.4 (Anwendung & Relevanz: Bei politischer Polarisierung; Red Flags; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wer den eigenen Maßstab prüfen will, stellt sich dieselbe Handlung von der anderen Seite vor und fragt, ob das Urteil gleich bliebe. Fällt es anders aus, liegt die Asymmetrie in der Bewertung, nicht im Vorgang.","prueffrage":"Worin unterscheiden sich die beiden Skandale in der Sache, abgesehen davon, welche Partei betroffen ist?","rueckmeldung":[{"option":0,"text":"Ein Blick auf die Skandalbilanz klärt Fakten und kann sinnvoll sein. Das Muster bleibt davon unberührt: Derselbe Vorgang wird je nach Lager unterschiedlich gewogen, und eine Bilanz prüft nicht diesen Maßstab."},{"option":1,"text":"Wie verlässlich die Berichterstattung ist, ist eine berechtigte Sachfrage und klärt Fakten. Sie lenkt den Blick aber nach außen, während das Muster in der eigenen Bewertung liegt: Man misst denselben Vorgang mit zweierlei Maß."},{"option":2,"text":"Auf die eigene Entrüstung zu achten wirkt nah am Problem, da Gefühle die Bewertung färben. Das Messen eines Gefühls beschreibt aber nur, was man empfindet, und prüft nicht, ob der Maßstab für beide Seiten derselbe ist."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ditto, P. H. u. a. (2019): At Least Bias Is Bipartisan. Perspectives on Psychological Science 14(2) (Kopie auf der Seite des Ditto-Labors, UC Irvine)","oeffentlich":true,"url":"https://sites.uci.edu/peterdittolab/files/2018/06/Ditto-et-al.-2018-At-Least-Bias-is-Bipartisan-A-Meta-Analytic-Comparison-of-Partisan-Bias-in-Liberals-Conservatives.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b1-017","clusterId":"B","werkstueckRef":"B.5","stufe":1,"question":"Eine Wirtschaftsjournalistin sagt: „Dass die Firma so erfolgreich wurde, ist doch klar: Der Gründer war ein Visionär, jede seiner Entscheidungen führte zwangsläufig zum Erfolg. Man sieht es an seiner Biografie.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Die Erzählung, die im Rückblick alles stimmig verbindet, wird mit einer Erklärung verwechselt, die den Erfolg schon vorher verlässlich vorhergesagt hätte.","Die Biografie stützt sich auf einen einzelnen Gründer und liefert daher keine repräsentative Stichprobe für den Erfolg von Unternehmen insgesamt.","Die Journalistin stellt nur zwei Möglichkeiten zur Wahl, Visionär oder Versager, und blendet damit alle Abstufungen zwischen diesen beiden Polen aus.","Die Journalistin beruft sich auf die Autorität einer Biografie, statt die zugrunde liegenden Daten zum Unternehmen selbst zu prüfen."],"correctIndex":0,"explanation":"Im Rückblick lassen sich unzusammenhängende Ereignisse leicht zu einer stimmigen Ursache-Wirkungs-Geschichte verbinden, die zwingend wirkt, weil man das Ergebnis schon kennt. Vorher hätte sie aber niemand verlässlich erzählen können: Zufall, Glück, Timing und Konkurrenten mit ähnlichen Ideen, die nur Pech hatten, fehlen in der glatten Erzählung. Eine gute Erklärung im Nachhinein ist deshalb noch keine gute Vorhersage. Die Journalistin stellt weder eine Regel für alle Firmen noch ein Entweder-oder auf, und auch eine Prüfung der Unternehmensdaten würde die rückblickende Glättung nicht beheben. Der Test: Welche unzusammenhängenden Fakten bleiben übrig, wenn du die erzählerischen Verbindungslinien weglässt?","coreRule":"⚡ Eine glatte Geschichte im Rückblick ist noch keine Vorhersage.","beleg":"Werkstück B.5 (Kernidee; Kontext & Tiefe; Die Legende des Star-CEOs; Anti-Denkmuster)","status":"entwurf","scenario":"Ein Zeitschriftenporträt über den Gründer eines Tech-Konzerns erzählt eine runde Geschichte: der rebellische College-Abbrecher, die Garage, der Kampf gegen die trägen Riesen. Jede Entscheidung erscheint im Rückblick wie ein kluger, folgerichtiger Schritt zum Gipfel.","kurz":"Im Rückblick wirkt jeder Schritt folgerichtig, weil das Ergebnis schon feststeht. Wer das für eine Erklärung hält, übersieht Zufall, Timing und gescheiterte Konkurrenten. Vorhersagen hätte man den Erfolg so nicht können.","prueffrage":"Welche Entscheidungen des Gründers hätten genauso gut schiefgehen können?","rueckmeldung":[{"option":1,"text":"Ein einzelner Fall ist tatsächlich eine schmale Grundlage, und gescheiterte Firmen tauchen gar nicht auf. Die Journalistin stellt aber keine Regel für alle Unternehmen auf; es geht um die rückblickend geglättete Erzählung dieses einen Falls."},{"option":2,"text":"Ein Entweder-oder zwischen Visionär und Versager stellt die Journalistin gar nicht auf, sie lobt nur diesen einen Fall. Ihr Fehler: Weil der Erfolg feststeht, ordnet sie die Entscheidungen im Rückblick so, dass sie zwangsläufig dorthin führen."},{"option":3,"text":"Wer prüft, statt einer Erzählung zu glauben, handelt meist richtig. Doch selbst saubere Daten lassen sich im Rückblick zu einer glatten Geschichte verknüpfen, in der Glück und Zufall unsichtbar bleiben. Daran ändert eine Datenprüfung wenig."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Roese, N. J.; Vohs, K. D. (2012): Hindsight Bias. Perspectives on Psychological Science 7(5)","oeffentlich":false,"doi":"10.1177/1745691612454303"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Geld und Zahlen"},{"id":"qx-b1-018","clusterId":"B","werkstueckRef":"B.5","stufe":2,"question":"Welche Prüfung hilft am besten, um zu klären, ob die Reportage mehr ist als eine gute Geschichte?","scenario":"Du liest eine Reportage über den Aufstieg einer Firma: klar, spannend, jede Wendung begründet. Du willst prüfen, ob die Erzählung die Fakten trägt oder nur gut klingt.","options":["Die Verbindungen zwischen den Ereignissen gedanklich löschen und fragen, welche Einzelfakten bleiben und welche Rolle Zufall und Glück spielten.","Prüfen, ob die Erzählung emotional stimmig ist und sich rund anfühlt, denn eine echte Ursache hinterlässt ein schlüssiges Bild im Kopf.","Auf die Bekanntheit der Autorin achten und ihrem Ruf vertrauen, denn je bekannter sie ist, desto verlässlicher ist ihre Kausalkette.","Die Erzählung mit einer ähnlich schlüssigen Darstellung vergleichen und die überzeugendere übernehmen, denn so setzt sich die bessere Erklärung durch."],"correctIndex":0,"explanation":"Eine kohärente Erzählung entsteht oft erst im Rückblick: Das Gehirn verbindet Einzelereignisse zu einer Ursache-Wirkungs-Kette und blendet Zufall, Glück und gescheiterte Konkurrenz aus. Wer die Verbindungslinien gedanklich entfernt, sieht, welche belegbaren Fakten übrig bleiben und wo die Geschichte nur Lücken füllt. Emotionale Stimmigkeit, Bekanntheit und Überzeugungskraft einer Darstellung sind dagegen genau das, was Geschichten glaubwürdig wirken lässt, ohne etwas über ihre Wahrheit zu sagen.","coreRule":"⚡ Streich die Verbindungslinien und sieh nach, welche Fakten übrig bleiben.","beleg":"Werkstück B.5 (Das Anti-Denkmuster; Werkbank-Frage)","status":"entwurf","kurz":"Nimmt man die Verbindungslinien weg, sieht man, welche belegbaren Fakten übrig bleiben und wo Zufall oder Glück mitspielten. Im Rückblick verknüpft das Gehirn Einzelereignisse gern zu einer lückenlosen Ursachenkette.","prueffrage":"Woher stammen die einzelnen Angaben der Reportage, und wo ließen sie sich unabhängig von ihr nachprüfen?","rueckmeldung":[{"option":1,"text":"Ein rundes Gefühl ist ein verständlicher Anlass, der Geschichte zu trauen. Genau dieses Gefühl entsteht aber auch bei Erzählungen, die erst im Rückblick geglättet wurden, und es sagt nichts darüber, ob die Fakten die Kette tragen."},{"option":2,"text":"Der Ruf einer Autorin ist ein nachvollziehbares Vertrauenssignal. Er prüft aber nicht, ob die Kausalkette dieser Reportage durch Belege gedeckt ist: Bekanntheit sagt nichts über die Wahrheit einer einzelnen Darstellung."},{"option":3,"text":"Einen Vergleich anzustellen kann sinnvoll sein, wenn man an den Fakten vergleicht. Wer aber die überzeugendere Version übernimmt, wählt nach Überzeugungskraft, und die sagt nichts über die Wahrheit."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Netz und Medien"},{"id":"qx-b1-019","clusterId":"B","werkstueckRef":"B.5","stufe":4,"question":"Nach einem Börsencrash behauptet ein Bekannter: „Das war von langer Hand geplant. Eine kleine Gruppe von Großinvestoren hat gezielt auf den Absturz gewettet und alle anderen ins Verderben geschickt.“ Er hat viele Details parat, die zusammen eine stimmige Geschichte ergeben. Was ist an seiner Argumentation das Kernproblem?","options":["Sie macht aus Zufall, Fehlern und vielen Einzelentscheidungen eine runde Geschichte mit Bösewicht und Plan; dass sie stimmig klingt, zeigt nicht, dass sie wahr ist.","Sie enthält mit Sicherheit eine erfundene Tatsache, und schon dieser eine Fehler entwertet die gesamte Behauptung mitsamt allen übrigen Details.","Sie verzichtet auf Zahlen und Statistiken, weil diese für ein breites Publikum zu kompliziert wären; dadurch fehlt der Behauptung jede belastbare Grundlage.","Sie erklärt das Ereignis nur aus Strukturen und Systemen und blendet aus, welche Rolle einzelne Personen und ihre Absichten spielten; dadurch bleibt sie unvollständig."],"correctIndex":0,"explanation":"Große, chaotische Ereignisse wie Wirtschaftskrisen, Pandemien oder Kriege entstehen meist aus einer Mischung von Inkompetenz, Zufall und systemischen Kräften. Die Behauptung macht daraus eine runde Geschichte mit einem allmächtigen Bösewicht, einem geheimen Plan und einem klaren Gut-Böse-Schema. Solche Geschichten sind psychologisch befriedigender als die komplizierte Realität, und genau deshalb wirken sie überzeugend. Dass die Erzählung stimmig klingt, sagt aber nichts darüber, ob sie wahr ist: Der Erzählfehler macht die Qualität der Geschichte zum Maßstab ihrer Glaubwürdigkeit statt die Qualität der Fakten. Prüfen lässt sich die Behauptung nur anhand der harten Einzelfakten, die übrig bleiben, wenn man die Verbindungslinien der Erzählung wegdenkt.","coreRule":"⚡ Je runder die Geschichte, desto genauer solltest du nach Zufall und banaler Erklärung fragen.","beleg":"Werkstück B.5 (Anwendung & Relevanz: Bei Verschwörungsmythen; Anti-Denkmuster: Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Eine stimmige Geschichte mit Plan und Bösewicht ist noch kein Beleg. Chaotische Ereignisse wie ein Crash entstehen meist aus Zufall, Fehlern und vielen Einzelentscheidungen; wer die Güte der Erzählung mit der Güte der Fakten verwechselt, erliegt dem Reiz der runden Story.","prueffrage":"Welche der vielen Details lassen sich einzeln belegen, wenn du die Verbindungen dazwischen weglässt?","rueckmeldung":[{"option":1,"text":"Ein erfundenes Detail würde eine Behauptung belasten, aber davon ist nirgends die Rede, und ein einzelner Fehler entwertet nicht automatisch das Ganze. Das Problem liegt in der Form: Die Geschichte wird zum Maßstab der Wahrheit."},{"option":2,"text":"Ob Zahlen fehlen, ist gar nicht bekannt, und der Grund „zu kompliziert fürs Publikum“ ist bloß unterstellt. Auch mit Statistiken bliebe das Kernproblem: Dass die Geschichte stimmig klingt, zeigt noch nicht, dass sie wahr ist."},{"option":3,"text":"Dass solche Ereignisse oft aus Systemen und Zufall entstehen, stimmt. Der Bekannte tut aber das Gegenteil: Er blendet Zufall und Systemkräfte aus und setzt Personen mit einem Plan an ihre Stelle."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6) (PMC, CC BY 4.0)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5724570/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Geld und Zahlen"},{"id":"qx-b1-020","clusterId":"B","werkstueckRef":"B.6","stufe":1,"question":"Was ist an Jonas' Überlegung fehlerhaft?","options":["Er rechnet Geld, das bereits ausgegeben und nicht mehr zurückzuholen ist, in eine Entscheidung ein, die nur von künftigen Kosten und Nutzen abhängen sollte.","Er unterschätzt, dass Reparaturen immer teurer werden, wenn man sie länger aufschiebt, und sollte deshalb möglichst schnell handeln.","Er überschätzt den Wert des Motorrads, weil er die Anschaffungskosten nicht gegen den aktuellen Marktpreis abgleicht.","Er lässt sich von der Erfahrung des Mechanikers leiten, obwohl diese Einschätzung ebenfalls ein Interesse am Geschäft haben könnte."],"correctIndex":0,"explanation":"Die 3.000 Euro sind weg, egal ob Jonas weiterrepariert oder aufgibt; sie verändern keine der beiden Möglichkeiten. Vernünftig ist ein Vergleich dessen, was noch kommt: weitere 1.800 Euro für ein Motorrad mit unsicherem Zustand gegen 2.500 Euro für ein zuverlässiges, abzüglich dessen, was das alte beim Verkauf noch einbringt. Dieser Vergleich kann durchaus für die Reparatur ausgehen; fehlerhaft ist die Begründung, denn wer die Vergangenheit mitrechnet, weil sonst alles „umsonst“ gewesen wäre, hält leicht an einer schlechten Investition fest. Diese Falle heißt Versunkene-Kosten-Falle (Sunk Cost Fallacy). Eine hilfreiche Prüffrage: Würdest du das Motorrad in diesem Zustand heute zu diesem Preis neu kaufen?","coreRule":"⚡ Entscheide nach dem, was kommt, nicht nach dem, was schon weg ist.","beleg":"Werkstück B.6 (Kernidee; Kontext & Tiefe); Fn. gl-b-sunk-cost (Arkes/Blumer 1985, OBHDP 35(1), S. 124)","status":"entwurf","scenario":"Jonas hat vor einem Jahr 3.000 Euro in ein gebrauchtes Motorrad gesteckt. Seitdem war er viermal in der Werkstatt, der Motor macht weiter Probleme, und der Mechaniker schätzt die nächste Reparatur auf weitere 1.800 Euro. Ein vergleichbares, zuverlässiges Motorrad gäbe es für 2.500 Euro. Jonas sagt: „Ich habe schon 3.000 Euro hineingesteckt. Wenn ich jetzt aufgebe, war das alles umsonst. Ich repariere weiter.“","quote":"","quoteLabel":"","kurz":"Die 3.000 Euro sind weg, egal wie Jonas sich entscheidet, und dürfen die Wahl nicht lenken. Zählen darf nur, was noch kommt: weitere 1.800 Euro für ein unsicheres Motorrad oder 2.500 Euro für ein zuverlässiges, abzüglich des Erlöses für das alte.","prueffrage":"Was spricht nach vier Werkstattbesuchen dafür, dass die nächste Reparatur die letzte ist?","rueckmeldung":[{"option":1,"text":"Dass Aufschieben Reparaturen verteuern kann, kennt man aus dem Alltag. Jonas schiebt aber gar nichts auf, er will ja weiter reparieren; sein Fehler ist, dass er bereits ausgegebenes Geld in die Entscheidung einrechnet."},{"option":2,"text":"Ein Blick auf den Marktpreis ist bei einer solchen Entscheidung durchaus nützlich. Jonas begründet das Weitermachen aber nicht mit dem Wert des Motorrads, sondern mit Geld, das schon ausgegeben ist und keine der beiden Möglichkeiten mehr verändert."},{"option":3,"text":"Eine Werkstattschätzung kann tatsächlich von eigenen Interessen gefärbt sein, und etwas Skepsis schadet nie. Jonas begründet seine Entscheidung aber gar nicht mit dem Mechaniker, sondern mit den schon investierten 3.000 Euro."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b1-021","clusterId":"B","werkstueckRef":"B.6","stufe":2,"question":"Welche Prüffrage setzt genau am Fehler in der Begründung der Leitung an?","scenario":"In deiner Firma läuft seit vier Jahren ein Softwareprojekt, das nach Einschätzung des Teams nie fertig wird. In der Sitzung sagt die Leitung: „Wir haben schon so viel investiert – jetzt aufzugeben wäre Verschwendung.“ Du darfst eine einzige Prüffrage stellen.","options":["„Welchen Betrag müssen wir bei einem Abbruch abschreiben, und können wir diesen Verlust verkraften?“","„Würden wir dieses Projekt heute, in genau diesem Zustand und mit dem heutigen Wissen, neu beginnen?“","„Wie viel haben wir bisher insgesamt investiert, und ist der erwartete Gewinn größer als diese Summe?“","„Wer im Team glaubt weiterhin an das Projekt, und hat diese Gruppe die Mehrheit?“"],"correctIndex":1,"explanation":"Der Fehler liegt darin, dass bereits ausgegebenes Geld und vergangene Mühe zum Grund für die Fortsetzung gemacht werden. Diese Kosten sind unwiederbringlich weg, egal ob das Projekt weiterläuft oder nicht; für die Entscheidung zählen nur künftige Kosten und künftiger Nutzen. Die Frage, ob man das Vorhaben heute im jetzigen Zustand neu beginnen würde, blendet die Vergangenheit aus und zwingt dazu, nur die Zukunft zu bewerten. Wer die bisherigen Ausgaben in den Vergleich einrechnet (Abschreibung, Gesamtkosten gegen Gewinn), bleibt in der Falle, weil das Vergangene weiter mitentscheidet. Die Zahl der Befürworter sagt nichts über den künftigen Nutzen des Projekts.","coreRule":"⚡ Frag nicht, wie viel du schon investiert hast, sondern ob du heute noch einsteigen würdest.","quote":"Würde ich einsteigen?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.6 (Das Anti-Denkmuster; Verbindungen: Null-Basis-Check A.14)","status":"entwurf","kurz":"Der Fehler liegt darin, dass bereits Ausgegebenes zum Grund fürs Weitermachen wird, obwohl es so oder so verloren ist. Zählen darf nur, was künftig noch kostet und nützt; genau darauf lenkt die Frage, ob man das Projekt heute neu beginnen würde.","prueffrage":"Welchen Grund nennt die Leitung in der Sitzung dafür, das Projekt weiterzuführen?","rueckmeldung":[{"option":0,"text":"Eine Abschreibung wirkt wie die ehrliche Rechnung eines Abbruchs. Sie betrifft aber nur Geld, das schon ausgegeben ist; damit entscheidet das Vergangene weiter mit, statt dass allein die Zukunft bewertet wird."},{"option":2,"text":"Ein erwarteter Gewinn gehört in die Entscheidung. Wird er aber gegen die gesamte bisherige Summe gestellt, zählt Geld mit, das so oder so weg ist. Verglichen werden dürfen nur künftige Kosten und künftiger Nutzen."},{"option":3,"text":"Wenn viele ans Projekt glauben, scheint das für seine Zukunft zu sprechen. Die Zahl der Befürworter sagt aber nichts darüber, was das Projekt künftig noch kostet und einbringt, und trifft auch den Fehler der Leitung nicht."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b1-022","clusterId":"B","werkstueckRef":"B.6","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass aus gesunder Ausdauer irrationale Sturheit geworden ist?","options":["Die Gründerin macht weiter, obwohl der Markttest eindeutig negativ ausfiel, und verweist auf ihre zwei bisherigen Jahre.","Der Doktorand wiederholt sein Experiment, obwohl der erste Versuch scheiterte, und verweist auf seine Vermutung zur Fehlerursache.","Der Mann hält an der Fernbeziehung fest, obwohl der Alltag anstrengend ist, und verweist auf die gemeinsame Arbeit an einer Lösung.","Die Frau behält ihre Aktien, obwohl der Kurs im letzten Monat fiel, und verweist auf ihre langfristige Einschätzung des Unternehmens."],"correctIndex":0,"explanation":"Ausdauer ist oft nötig und nützlich: Wer nach dem ersten Rückschlag aufgibt, erreicht langfristige Ziele nie. Der Kipppunkt zur Sturheit liegt dort, wo neue, negative Informationen ignoriert werden, um die ursprüngliche Entscheidung zu schützen. Entscheidend ist also, wie jemand mit neuer Information umgeht und wonach er seine Entscheidung begründet. Im Szenario zeigen drei Personen einen Grund, der nach vorn zeigt: der Doktorand eine Vermutung zur Ursache, der Mann die Arbeit an einer Lösung, die Frau eine eigene Einschätzung des Unternehmens. Nur die Gründerin stützt sich auf bereits Investiertes und übergeht die eindeutig negative Information. Die zwei Jahre sind unwiederbringlich verloren, gleich wie sie sich entscheidet, und dürfen deshalb die Entscheidung über die Zukunft nicht lenken. Prüffrage: Würde ich heute, mit dem aktuellen Wissen, noch einmal einsteigen?","coreRule":"⚡ Ausdauer hält durch, trotz Schwierigkeiten – Sturheit hält fest, trotz Gegenbeweisen.","beleg":"Werkstück B.6 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","scenario":"Vier Menschen halten an einem Vorhaben fest, das nicht richtig läuft: eine Gründerin mit ihrem Start-up, ein Doktorand mit seinem Experiment, ein Mann mit seiner Fernbeziehung und eine Frau mit ihrer Aktienposition.","kurz":"Entscheidend ist, wie jemand mit neuer Information umgeht: Die Gründerin übergeht einen eindeutig negativen Markttest und begründet das Weitermachen mit den zwei investierten Jahren. Die sind aber verloren, gleich wie sie sich entscheidet, und dürfen die Zukunft nicht lenken.","prueffrage":"Worauf stützt sich jede der vier Personen, wenn sie begründet, warum sie weitermacht?","rueckmeldung":[{"option":1,"text":"Ein gescheiterter erster Versuch wirkt wie ein Warnzeichen, ist in der Forschung aber normal. Der Doktorand hat zudem eine Vermutung zur Ursache, also einen Grund, der nach vorn zeigt; wer hier aufgäbe, würde zu früh aufgeben."},{"option":2,"text":"Ein anstrengender Alltag klingt nach einem Signal zum Aufhören. Er ist aber noch keine eindeutig negative Information über die Beziehung, und der Mann begründet sein Festhalten mit der Arbeit an einer Lösung, nicht mit dem bisher Aufgewendeten."},{"option":3,"text":"Ein fallender Kurs lässt Festhalten schnell wie Sturheit aussehen. Ein Monat Verlust sagt aber wenig über das Unternehmen, und die Frau stützt sich auf ihre Einschätzung der Zukunft, nicht auf bereits Verlorenes."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-b1-023","clusterId":"B","werkstueckRef":"B.6","stufe":4,"question":"Welche Rückfrage der Freundin würde ihr am besten helfen, ihre Entscheidung neu zu prüfen?","scenario":"Eine Frau engagiert sich seit zehn Jahren in einer Gemeinschaft, die eine bestimmte Lehre vertritt. Inzwischen hat sie ernste Zweifel an deren Aussagen. Eine Freundin fragt sie, warum sie trotzdem bleibt. Sie antwortet: „Ich habe zehn Jahre, meine Freundschaften und mein Geld hineingesteckt. Wenn ich jetzt gehe, war das alles umsonst.“","options":["„Würdest du heute, so wie du die Lehre jetzt einschätzt, neu einsteigen?“","„Wie viel Geld und Zeit hast du investiert, damit wir deinen Verlust ausrechnen?“","„Was würden die anderen sagen, wenn du jetzt gehst und ihre Arbeit entwertest?“","„Gab es in den zehn Jahren nicht auch viele gute Momente, die den Aufwand rechtfertigen?“"],"correctIndex":0,"explanation":"Die zehn Jahre und das Geld sind ausgegeben und kommen nicht zurück, egal ob sie bleibt oder geht; solche versunkenen Kosten sollten die künftige Entscheidung nicht lenken. Zählen darf, was von nun an für oder gegen das Bleiben spricht, und dazu gehört auch, welche Freundschaften ein Austritt gefährden würde; über die Lehre selbst sagt aber auch das nichts. Die Frage nach dem Neueinstieg richtet den Blick genau darauf und zwingt, die Lehre so zu bewerten, wie sie heute dasteht. Die anderen Fragen halten die frühere Investition im Spiel: Sie bewerten den Verlust, den sozialen Druck oder die Vergangenheit, statt die Zukunft zu klären. Genau diese Bindung ans Investierte hält Menschen oft in Kulten und Glaubenssystemen fest, selbst wenn Zweifel aufkommen.","coreRule":"⚡ Bereits Verlorenes darf die Entscheidung nicht lenken: Frag, ob du heute noch einsteigen würdest.","beleg":"Werkstück B.6 (Anwendung & Relevanz: Bei irrationalen Glaubenssystemen; Kontext & Tiefe)","status":"entwurf","kurz":"Entscheidend ist, was künftig für oder gegen das Bleiben spricht, denn die zehn Jahre sind unabhängig von der Wahl verloren. Die Frage nach dem Neueinstieg stellt genau das heraus; wer am Investierten hängt, fragt dagegen nach Verlust und Vergangenheit.","prueffrage":"Was genau an den Aussagen der Gemeinschaft bezweifelt sie, und seit wann?","rueckmeldung":[{"option":1,"text":"Eine genaue Rechnung scheint Klarheit zu bringen. Sie beziffert aber nur, was ohnehin ausgegeben ist, und das bleibt es, egal ob sie bleibt oder geht. Für die Entscheidung zählt nur, was von nun an dafür oder dagegen spricht."},{"option":2,"text":"Die Reaktion der anderen anzusprechen wirkt rücksichtsvoll, denn sie gehören zu ihrem Leben. Damit geht es aber um sozialen Druck und nicht darum, ob die Lehre heute noch trägt. Genau dieser Druck hält Zweifelnde oft in der Gruppe."},{"option":3,"text":"Gute Momente mag es durchaus gegeben haben. Sie liegen aber in der Vergangenheit und sagen nichts darüber, ob Weitermachen künftig lohnt. Die Frage rechtfertigt das bisher Investierte im Nachhinein, statt die Zukunft zu klären."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b1-024","clusterId":"B","werkstueckRef":"B.7","stufe":1,"question":"Was ist an der Aussage der Kollegin das Hauptproblem?","scenario":"Am Tag nach einer Wahl, bei der Kandidat A überraschend deutlich gewonnen hat, hörst du in der Kantine drei Sätze: (a) „Das musste ja so kommen.“ (b) „Ich habe doch gesagt, dass er gewinnt“ – dabei hatte sich der Sprecher vor der Wahl auf keinen Sieger festgelegt. (c) Eine Kollegin: „Das hätte man doch sehen müssen!“ Du weißt, dass vor der Wahl selbst Fachleute uneins waren und die Umfragen knapp standen.","options":["Sie beurteilt die Vorhersehbarkeit nach dem Ergebnis und blendet aus, dass die Lage vor der Wahl offen war.","Sie traut den Wahlforschern zu viel zu und übersieht, dass deren Prognosen zu ungenau waren.","Sie erinnert sich falsch an den Wahlkampf und übersieht, dass sie die letzten Debatten nicht verfolgt hat.","Sie hält den Sieg für zu zufällig und übersieht, dass die Signale vor der Wahl eindeutig waren."],"correctIndex":0,"explanation":"Wer den Ausgang kennt, sortiert die damaligen Informationen neu: Was zum Ergebnis passt, wirkt im Rückblick wichtig, was auf andere Ausgänge hindeutete, verliert an Gewicht. Vor der Wahl waren selbst Fachleute uneins und die Umfragen knapp, die Lage war also offen; der Satz „Das hätte man doch sehen müssen!“ misst sie am Wissen von heute und urteilt dadurch unfair. Die drei Sätze aus der Kantine zeigen drei Spielarten des Rückschaufehlers: „Das musste ja so kommen“ ist das Gefühl der Unvermeidbarkeit, „Ich habe doch gesagt, dass er gewinnt“ die Gedächtnisverzerrung (die eigene frühere Einschätzung rutscht in Richtung des Ergebnisses), „Das hätte man doch sehen müssen!“ das Gefühl der Vorhersehbarkeit. Hilfreich ist die Frage: Welche Informationen, die ich jetzt habe, hatte damals noch niemand?","coreRule":"⚡ Rückblickend wirkt alles zwingend, vorhersehbar und längst gewusst – dabei war es damals offen. Prüfe, was man zum Zeitpunkt der Entscheidung wissen konnte.","beleg":"Werkstück B.7 (Kontext & Tiefe, drei Ebenen); Fn. gl-b-rueckschau-ebenen (Roese/Vohs 2012, Perspectives on Psychological Science 7(5), S. 412–413)","status":"entwurf","kurz":"Die Kollegin misst die damalige Lage am heutigen Wissen: Im Rückblick wirkt der Ausgang wie eine gerade Linie, obwohl vor der Wahl selbst Fachleute uneins waren und die Umfragen knapp standen.","prueffrage":"Welche Tipps gaben die Leute in der Kantine vor der Wahl ab, und wie sicher waren sie sich damals?","rueckmeldung":[{"option":1,"text":"Prognosen sind nie exakt, das stimmt. Die Kollegin verlässt sich aber gar nicht auf die Wahlforscher, im Gegenteil: Sie hält im Nachhinein für offensichtlich, was die knappen Umfragen damals offenließen."},{"option":2,"text":"Erinnerungslücken kommen vor, aber dass sie die Debatten verpasst hat, ist nirgends gesagt, und es träfe auch nicht den Kern. Entscheidend ist der Maßstab: Sie bewertet die damalige Lage mit dem Wissen von heute."},{"option":3,"text":"Hier ist die Lage vertauscht: Vor der Wahl waren Fachleute uneins und die Umfragen knapp, die Signale also gerade nicht eindeutig. Erst der Rückblick lässt sie eindeutig erscheinen."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis, Kap. 13: Hindsight Biases in Evaluation of Intelligence Reporting. CIA","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"161–162","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fischhoff, B. (1975): Hindsight ≠ Foresight. Journal of Experimental Psychology: Human Perception and Performance 1(3)","oeffentlich":false,"doi":"10.1037/0096-1523.1.3.288"}],"thema":"Zusammenleben"},{"id":"qx-b1-025","clusterId":"B","werkstueckRef":"B.7","stufe":2,"question":"Welches Vorgehen schützt am besten davor, dass das Wissen um den Ausgang die Erinnerung und das Urteil verfälscht?","scenario":"Anna wechselt den Job. Ein halbes Jahr später läuft es schlecht, und sie denkt: „Ich hab doch gleich gespürt, dass das nicht passt.“ Ihr Freund Ben erinnert sich anders: Damals war sie begeistert und hielt den Wechsel für eine große Chance. Beide wollen bei der nächsten wichtigen Entscheidung später ehrlich beurteilen können, was sie vorher wussten und wie gut sie entschieden haben.","options":["Nach dem Ergebnis in Ruhe überlegen, was man damals eigentlich geglaubt und gewusst hat.","Die Entscheidung so lange aufschieben, bis der Ausgang sicher genug absehbar ist.","Das Ergebnis konsequent als Maßstab nehmen, um die Entscheidung als gut oder schlecht zu bewerten.","Gründe und Unsicherheitsgrad vorab schriftlich festhalten, bevor das Ergebnis bekannt ist."],"correctIndex":3,"explanation":"Wer vor der Entscheidung schriftlich festhält, was er weiß und wie sicher er sich ist, hat später einen Beleg, der nicht mehr durch das Ergebnis verfälscht werden kann. Die Erinnerung nach dem Ausgang ist dagegen genau das, was der Rückschaufehler verzerrt: Wir sind dann überzeugt, es „schon immer gewusst“ zu haben. Auch das Ergebnis taugt nicht als Maßstab, denn eine gute Entscheidung kann schlecht ausgehen und umgekehrt. Beurteilen lässt sich eine Entscheidung nur danach, was zum Zeitpunkt der Entscheidung bekannt und absehbar war. Und abwarten, bis der Ausgang absehbar ist, würde die Entscheidung gerade unmöglich machen, denn Entscheidungen müssen unter Unsicherheit fallen.","coreRule":"⚡ Schreib auf, was du weißt und wie sicher du bist – bevor du das Ergebnis kennst.","beleg":"Werkstück B.7 (Verbindungen: Entscheidungs-Tagebuch; Red Flags)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer vorab schriftlich festhält, was er weiß und wie sicher er ist, hat später einen Beleg, den das Ergebnis nicht färben kann. Die Erinnerung danach neigt dazu, „das habe ich immer gewusst“ zu sagen.","prueffrage":"Wie sicher sind sich Anna und Ben jeweils ihrer Erinnerung, und wie ließe sich heute klären, wer recht hat?","rueckmeldung":[{"option":0,"text":"Nachträgliches Nachdenken klingt gründlich, stützt sich aber auf genau die Erinnerung, die der Ausgang färbt. Das zeigen Anna und Ben: Beide sind überzeugt, und ihre Erinnerungen widersprechen sich."},{"option":1,"text":"Wer wartet, bis der Ausgang absehbar ist, entscheidet nicht mehr unter Unsicherheit, sondern gar nicht. Das Problem der verfälschten Rückschau bleibt trotzdem für alle späteren Urteile bestehen."},{"option":2,"text":"Ein Ergebnis sagt zwar etwas, ist aber ein schlechter alleiniger Maßstab: Gute Entscheidungen können schlecht ausgehen und umgekehrt. Beurteilbar ist nur, was zum Zeitpunkt der Entscheidung bekannt und absehbar war."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis, Kap. 13: Hindsight Biases in Evaluation of Intelligence Reporting. CIA","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"162","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fischhoff, B. (1975): Hindsight ≠ Foresight. Journal of Experimental Psychology: Human Perception and Performance 1(3)","oeffentlich":false,"doi":"10.1037/0096-1523.1.3.288"}],"thema":"Psychologie"},{"id":"qx-b1-026","clusterId":"B","werkstueckRef":"B.7","stufe":4,"question":"Wie prüfst du am besten, ob diese Strophe das Ereignis wirklich vorhergesagt hat?","scenario":"Nach einer Katastrophe zeigt dir jemand eine mehrdeutige Strophe aus einer alten Prophezeiungssammlung. Er sagt, sie habe genau dieses Ereignis „vorhergesagt“, und verweist darauf, dass sich im Text Bilder finden, die zum Geschehen passen.","options":["Du fragst, ob die Strophe schon vor Jahrhunderten gedruckt wurde, denn ein hohes Alter schützt vor nachträglicher Anpassung.","Du fragst, ob die Deutung vor dem Ereignis festgehalten wurde und konkret genug war, um scheitern zu können.","Du fragst, ob viele Menschen die Deutung teilen, denn eine breite Zustimmung spricht für eine zutreffende Auslegung.","Du fragst, ob sich im Text Bilder finden, die zum Geschehen passen, denn passende Bilder zeigen, dass die Strophe das Ereignis vorhergesagt hat."],"correctIndex":1,"explanation":"Ob die Deutung schon vor der Katastrophe festgehalten wurde, ist offen; oft wird zu einer mehrdeutigen Strophe erst nachträglich ein passendes Ereignis gesucht. Wer den Ausgang kennt, findet in vagen Bildern fast immer Anknüpfungspunkte, deshalb beweisen passende Bilder nichts. Auch das Alter des Textes und die Zustimmung vieler Menschen sagen nichts darüber, ob etwas vorhergesagt wurde, denn das Problem ist die Mehrdeutigkeit und die fehlende Festlegung vorab. Echte Vorhersagekraft zeigt nur eine Aussage, die vor dem Ereignis festgehalten wurde und so konkret war, dass sie hätte scheitern können. Fehlt das, bleibt nur Deutungskraft im Rückblick.","coreRule":"⚡ Eine Vorhersage zählt nur, wenn sie vor dem Ereignis eindeutig festgehalten wurde.","beleg":"Werkstück B.7 (Anwendung & Relevanz: In der Esoterik)","status":"entwurf","kurz":"Eine echte Vorhersage muss vor dem Ereignis festgehalten und so konkret gewesen sein, dass sie hätte scheitern können. Passende Bilder findet man bei vagen Texten im Rückblick fast immer, denn der Ausgang lenkt den Blick auf das, was passt.","prueffrage":"Auf wie viele andere Katastrophen der letzten Jahrzehnte ließe sich dieselbe Strophe ebenso gut beziehen?","rueckmeldung":[{"option":0,"text":"Ein hohes Alter wirkt vertrauenswürdig und macht nachträgliche Textänderungen unwahrscheinlicher. Es sagt aber nichts darüber, wann die Deutung entstand und ob sich die Strophe überhaupt festlegt; das Problem ist die Mehrdeutigkeit."},{"option":2,"text":"Wenn viele eine Deutung teilen, wirkt sie gesichert. Doch viele können demselben Eindruck im Rückblick erliegen, und Verbreitung macht eine Auslegung nicht zutreffender. Entscheidend ist, was vorab festgelegt war."},{"option":3,"text":"Dass sich passende Bilder finden, ist genau das, was man bei einem mehrdeutigen Text im Rückblick erwartet: Wer den Ausgang kennt, findet fast immer Anknüpfungspunkte. Als Beleg für eine Vorhersage taugen sie deshalb nicht."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-027","clusterId":"B","werkstueckRef":"B.8","stufe":1,"question":"Was ist an dieser Überlegung fehlerhaft?","options":["Du erklärst sein Verhalten mit einer dauerhaften Eigenschaft und blendest die Umstände aus, die du nicht kennst.","Du urteilst über Jonas milder, als du über dich selbst urteilen würdest, weil du seine Gründe kennst.","Du hältst Jonas für einen typischen Vertreter seines Teams, statt ihn als einzigartige Person zu sehen.","Du erklärst sein Verhalten mit den Umständen und unterschätzt dabei seine Persönlichkeit."],"correctIndex":0,"explanation":"Aus einem einzelnen Verhalten wird hier auf eine stabile Eigenschaft geschlossen („Egoist“, „schon immer“), während die Situation, die du nicht kennst, gar nicht in die Erklärung eingeht. Das ist der typische Fehlschluss beim Beurteilen anderer: Die Person ist das Auffälligste, was wir sehen, ihre Umstände sind für uns unsichtbar. Der Fehler besteht in der Tendenz, die Situation zu unterschätzen, nicht darin, dass der Charakter nie eine Rolle spielt. Auch die anderen Aussagen treffen den Fehler nicht: Die Einschätzung ist nicht zu milde, sondern zu hart, und der Vergleich mit dem eigenen Verhalten ist eine eigene, nur schwach belegte Hypothese, nicht der Kern des Fehlers. Es geht auch nicht um die Gruppe, sondern um eine einzelne Person. Und die Umstände werden nicht überbetont, sondern ignoriert.","coreRule":"⚡ Wer ein Verhalten sofort mit dem Charakter erklärt, sieht die Umstände nicht, die er nicht kennt.","beleg":"Werkstück B.8 (Kernidee; Kontext & Tiefe, Fokus der Aufmerksamkeit; Hinweis zur Beleglage); Fn. gl-b-attribution (Ross/Anderson 1982, Kap. 9)","status":"entwurf","scenario":"Du erfährst, dass Jonas bei der Teamsitzung gestern zwei Kollegen mehrfach das Wort abgeschnitten hat. Dein Gedanke: „Der ist einfach ein rücksichtsloser Egoist, so war der schon immer.“ Über Jonas' Woche weißt du nichts. Was du nicht weißt: Er hatte kurz vorher einen Abgabetermin mit großem Zeitdruck.","kurz":"Aus einem einzelnen Verhalten wird auf eine stabile Eigenschaft geschlossen, während die Umstände unsichtbar bleiben. Wir neigen dazu, die Situation zu unterschätzen, auch wenn der Charakter durchaus eine Rolle spielen kann.","prueffrage":"Wie hat sich Jonas in früheren Sitzungen verhalten, und wer hat das selbst erlebt?","rueckmeldung":[{"option":1,"text":"Dass man bei sich selbst die Gründe kennt und bei anderen nicht, ist ein echter Unterschied. Hier ist dein Urteil aber nicht zu milde, sondern sehr hart, und der Selbstvergleich trifft nicht den Kern des Fehlers."},{"option":2,"text":"Von Jonas' Team ist im Gedanken keine Rede, es geht allein um ihn als einzelne Person. Es wird also gar nicht von einer Gruppe auf ihn geschlossen, sondern von einem Verhalten auf eine dauerhafte Eigenschaft."},{"option":3,"text":"Das wäre die Umkehrung des Fehlers: Die Umstände werden hier nicht betont, sondern ausgeblendet, und der Persönlichkeit wird zu viel Gewicht gegeben. Der Charakter kann durchaus eine Rolle spielen, nur die Situation kommt zu kurz."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1) (Kopie auf der Harvard-Seite von D. Gilbert)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"url","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6), Abstract bei PubMed","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17073526/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b1-028","clusterId":"B","werkstueckRef":"B.8","stufe":3,"question":"In einem Podcast heißt es: „Jeder weiß doch: Wir erklären unser eigenes Fehlverhalten mit den Umständen, das Fehlverhalten anderer aber mit deren Charakter. Das ist psychologisch erwiesen.“ Du erfährst, dass eine Auswertung von 173 Studien genau diese Behauptung geprüft hat. Welche Frage hilft dir jetzt am meisten, um die Aussage einzuordnen?","options":["Wie groß war der durchschnittliche Effekt über alle Studien hinweg, und unter welchen Bedingungen zeigte er sich überhaupt?","Wie bekannt ist die Behauptung in Lehrbüchern, und wie viele Fachleute vertreten sie seit Jahrzehnten?","Welche einzelne Studie hat den Effekt am deutlichsten gezeigt, und wie überzeugend wirkt ihr Ergebnis?","Wie plausibel passt die Behauptung zu meinen eigenen Alltagserfahrungen mit Kollegen und Freunden?"],"correctIndex":0,"explanation":"Wer eine Behauptung prüfen will, schaut auf die Gesamtlage der Belege statt auf Bekanntheit, Einzelfälle oder das eigene Gefühl. Tatsächlich fand die Auswertung von 173 Studien (Malle 2006) für diese Asymmetrie im Durchschnitt praktisch keinen Effekt. Sie zeigte sich nur unter bestimmten Bedingungen, vor allem bei negativem Verhalten, und auch dort nur klein; bei positivem Verhalten kehrte sie sich um. Eine Behauptung kann jahrzehntelang als gesichert gelten und der Überprüfung trotzdem nur teilweise standhalten. Weder Verbreitung noch ein beeindruckender Einzelfall noch das eigene Bauchgefühl ersetzen den Blick auf Größe und Bedingungen des Effekts über alle Studien hinweg.","coreRule":"⚡ Auch Lehrbuchwissen braucht einen Quellencheck: Frag nach der Gesamtlage der Belege (Größe und Bedingungen des Effekts), nicht nach Bekanntheit oder Einzelfällen.","beleg":"Werkstück B.8 (Hinweis zur Beleglage); Fn. gl-b-attribution (Malle 2006, Psychological Bulletin 132(6), S. 895, 902, 907)","status":"entwurf","scenario":"Du hörst den Podcast beim Kochen und möchtest die Aussage nicht einfach glauben oder abtun.","kurz":"Entscheidend ist die Gesamtlage: Über 173 Studien hinweg zeigt sich im Schnitt praktisch kein Effekt, nur unter bestimmten Bedingungen ein kleiner. Verbreitung, ein starker Einzelfall oder das Bauchgefühl können dagegen täuschen.","prueffrage":"Woher weiß der Podcast, dass „jeder“ das so macht, und welche Belege nennt er dafür?","rueckmeldung":[{"option":1,"text":"Dass eine Behauptung in Lehrbüchern steht und seit Jahrzehnten vertreten wird, zeigt ihre Verbreitung, aber nicht, wie gut sie belegt ist. Auch lange Geltung kann der Prüfung nur teilweise standhalten, wie hier."},{"option":2,"text":"Eine einzelne, besonders deutliche Studie kann den Effekt tatsächlich zeigen. Für die Einordnung zählt aber die Gesamtlage: im Schnitt praktisch kein Effekt, nur unter bestimmten Bedingungen ein kleiner, bei positivem Verhalten sogar umgekehrt."},{"option":3,"text":"Alltagserfahrungen können ein guter Anlass sein, genauer nachzufragen. Als Maßstab taugen sie wenig, denn Erinnerung ist selektiv: Auffällige Fälle bleiben haften, unauffällige verschwinden. Das Bauchgefühl ersetzt nicht den Blick auf alle Studien."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis, Abstract bei PubMed","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17073526/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6)","oeffentlich":false,"doi":"10.1037/0033-2909.132.6.895","seite":"895, 902"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-029","clusterId":"B","werkstueckRef":"B.8","stufe":4,"question":"Wie solltest du den Schluss einschätzen, der Attributionsfehler („wir erklären das Verhalten anderer vorschnell mit ihrem Charakter“) sei ein universelles Merkmal des Menschen?","options":["Die Verallgemeinerung ist zu weit gegangen: Vergleichsstudien deuten darauf hin, dass der Effekt außerhalb des Westens schwächer ausfällt, etwa weil Ostasiaten eher auf die Macht der Situation schließen.","Die Verallgemeinerung ist berechtigt: Wenn ein Effekt in vielen Experimenten auftritt, gilt er automatisch für alle Menschen gleichermaßen, unabhängig davon, wer getestet wurde.","Die Verallgemeinerung ist umgekehrt richtig: Der Effekt tritt eigentlich nur in Ostasien auf, weil westliche Versuchspersonen Charakter und Situation ausgewogen bewerten.","Die Verallgemeinerung ist widerlegt: Außerhalb des Westens verschwindet der Effekt vollständig, weil dort Verhalten nie mit dem Charakter einer Person erklärt wird."],"correctIndex":0,"explanation":"Eine Verallgemeinerung ist nur so gut wie die Gruppe, an der getestet wurde. Wurden die klassischen Versuche fast nur mit westlichen Versuchspersonen gemacht, sagt das wenig über „den Menschen“ insgesamt. Tatsächlich deuten Vergleichsstudien darauf hin, dass der „fundamentale“ Fehler anderswo weniger grundlegend wirkt: Ostasiaten schlossen eher als US-Amerikaner auf die Macht der Situation, besonders wenn die Umstände deutlich hervorgehoben waren; ähnliche Befunde gibt es für Russen und früher für Hindus in Indien. Charakterurteile gibt es auch dort, deshalb wäre ein „verschwindet vollständig“ ebenso übertrieben wie „überall gleich stark“. Die angemessene Haltung liegt dazwischen: Der Effekt ist real, aber in Stärke und Verbreitung kulturabhängig.","coreRule":"⚡ Von einer Stichprobe auf „alle Menschen“ zu schließen, ist nur erlaubt, wenn die Stichprobe die Vielfalt der Menschen abbildet.","beleg":"Werkstück B.8 (Kontext & Tiefe); Fn. gl-b-attribution-kultur (Henrich/Heine/Norenzayan 2010, RatSWD Working Paper 139, S. 25 f.)","status":"entwurf","scenario":"In einem Podcast heißt es: „Dass wir das Verhalten anderer vorschnell mit ihrem Charakter erklären und die Umstände unterschätzen, ist ein Grundzug der menschlichen Natur – das tun alle Menschen überall gleich stark, das haben Experimente gezeigt.“ Die klassischen Experimente, auf die sich die Aussage stützt, wurden ganz überwiegend mit westlichen Versuchspersonen durchgeführt.","quote":"","quoteLabel":"","kurz":"Wurde fast nur im Westen getestet, sagt der Befund wenig über „den Menschen“. Vergleichsstudien deuten darauf hin, dass der Effekt etwa in Ostasien schwächer ausfällt. Der Fehler liegt darin, von einer eng gewählten Gruppe auf alle zu schließen.","prueffrage":"An wem wurden die klassischen Experimente eigentlich durchgeführt?","rueckmeldung":[{"option":1,"text":"Dass ein Effekt in vielen Experimenten auftritt, spricht für ihn. Wie weit er reicht, hängt aber davon ab, wer getestet wurde: Viele Versuche mit ähnlichen Versuchspersonen belegen vor allem, dass der Effekt bei ihnen auftritt."},{"option":2,"text":"Die Befunde laufen eher in die Gegenrichtung: Der Effekt ist im Westen klassisch belegt und fällt in Ostasien meist schwächer aus. Dass er dort allein auftritt und der Westen ausgewogen urteilt, stützt sich auf nichts."},{"option":3,"text":"Die Kritik an der Verallgemeinerung ist berechtigt, die Folgerung schießt aber über das Ziel hinaus. Der Effekt fällt anderswo oft schwächer aus, Charakterurteile gibt es auch dort, ein vollständiges Verschwinden wäre genauso übertrieben."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Henrich, J.; Heine, S. J.; Norenzayan, A. (2010): The Weirdest People in the World? RatSWD Working Paper 139 (KonsortSWD)","oeffentlich":true,"url":"https://www.konsortswd.de/wp-content/uploads/RatSWD_WP_139.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Henrich, J.; Heine, S. J.; Norenzayan, A. (2010): The weirdest people in the world? Behavioral and Brain Sciences 33(2–3)","oeffentlich":false,"doi":"10.1017/S0140525X0999152X"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-030","clusterId":"B","werkstueckRef":"B.8","stufe":2,"question":"Welche Frage prüft ihre Erklärung am besten?","scenario":"Eine Kollegin sagt über Menschen, die auf Heilkristalle schwören: „Die sind halt naiv und ungebildet.“ Du willst ihre Erklärung prüfen, bevor du sie übernimmst.","options":["Welche Bildung und Intelligenz bräuchte jemand, um diesen Glauben als Unsinn zu durchschauen?","Welche Hersteller verdienen an solchen Produkten, und wie viel geben sie für Werbung aus?","Welche Umstände, etwa Kontrollbedürfnis oder enttäuschende Erfahrungen, machen den Glauben für sie attraktiv?","Wie lässt sich der Glaube am schnellsten widerlegen, damit diese Menschen keinen Schaden nehmen?"],"correctIndex":2,"explanation":"Die Kollegin führt das Verhalten anderer auf einen stabilen Charakterzug zurück: Sie seien „halt naiv und ungebildet“. Die Situation der Betroffenen blendet sie aus. Diese Verzerrung heißt fundamentaler Attributionsfehler: Wir unterschätzen bei anderen die Macht der Umstände und überschätzen ihre Eigenschaften. Bei Glaubensüberzeugungen können ganz verschiedene Umstände eine Rolle spielen, etwa ein Bedürfnis nach Kontrolle, schlechte Erfahrungen mit der Schulmedizin oder starker sozialer Einfluss im Umfeld. Wer nach ihnen fragt, prüft die Charaktererklärung an der Wirklichkeit. Das ist keine Rechtfertigung des Glaubens, sondern eine bessere Erklärung. Die anderen Fragen bleiben entweder bei der Eigenschaft (Bildung, Intelligenz) oder wechseln das Thema (Verdienst der Hersteller, schnelle Widerlegung), ohne zu klären, warum diese Menschen so handeln.","coreRule":"⚡ Frag nach den Umständen, bevor du über den Charakter urteilst.","beleg":"Werkstück B.8 (Anwendung & Relevanz: Bei Aberglaube & Esoterik; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wer bei anderen sofort einen Charakterzug sieht, übersieht leicht ihre Umstände. Die Frage nach Kontrollbedürfnis oder schlechten Erfahrungen prüft die Erklärung „naiv und ungebildet“ an der Wirklichkeit, ohne den Glauben zu rechtfertigen.","prueffrage":"Was weiß die Kollegin über diese Menschen, außer dass sie an Heilkristalle glauben?","rueckmeldung":[{"option":0,"text":"Die Frage klingt nach Prüfung, bleibt aber bei der Eigenschaft: Sie fragt weiter nach Bildung und Intelligenz und hält den Glauben schon für durchschaubaren Unsinn. Die Situation dieser Menschen kommt gar nicht in den Blick."},{"option":1,"text":"Wer an Heilkristallen verdient, ist eine nachvollziehbare Frage, erklärt aber das Angebot und nicht, warum Menschen daran glauben. Über die Gründe der Betroffenen sagt sie nichts, die Erklärung der Kollegin bleibt ungeprüft."},{"option":3,"text":"Der Wunsch, Schaden zu vermeiden, ist verständlich. Die Frage springt aber zur Widerlegung, bevor geklärt ist, warum diese Menschen so handeln. Die Erklärung der Kollegin bleibt dabei ungeprüft."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1) (Kopie auf der Harvard-Seite von D. Gilbert)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ross, L.; Anderson, C. A. (1982): Shortcomings in the attribution process. In: Kahneman, D.; Slovic, P.; Tversky, A. (Hg.): Judgment under Uncertainty. Cambridge University Press, Kap. 9","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-b1-031","clusterId":"B","werkstueckRef":"B.9","stufe":1,"question":"Drei Szenen: Jemand erkennt in einer Wolke ein Tiergesicht. Jemand setzt nach fünfmal Schwarz beim Roulette auf Rot, weil „jetzt Rot dran ist“. Jemand deutet eine zufällige Häufung von Krankheitsfällen in einer Stadt als Zeichen einer Ursache, obwohl die Verteilung statistisch normal ist. Was haben die drei Szenen gemeinsam?","options":["In allen dreien wird im Zufall eine Ordnung gesehen, die gar nicht existiert.","In allen dreien fehlt dem Betrachter das nötige Fachwissen, um Daten zu lesen.","In allen dreien wird eine Wahrnehmung für unwahr erklärt, die sich wiederholen lässt.","In allen dreien ist das erkannte Muster echt, wird aber von anderen übersehen."],"correctIndex":0,"explanation":"Wolke, Roulette-Serie und Krankheitshäufung haben eine gemeinsame Wurzel: Das Gehirn sucht Ordnung und findet sie auch im reinen Zufall. Im ersten Fall ist es ein vermeintliches Gesicht, im zweiten eine scheinbare Gesetzmäßigkeit, nach der die nächste Runde die Serie ausgleichen müsse, obwohl jede Drehung unabhängig von den vorigen ist, im dritten eine zufällige Ballung, der eine besondere Ursache zugeschrieben wird. Die Neigung, Muster zu sehen, wo nur Rauschen ist, heißt Apophenie; der Roulette-Fall wird meist eigens als Spielerfehlschluss bezeichnet und beruht vor allem auf einem falschen Bild von unabhängigen Zufallsereignissen. Die Muster sind dabei nicht echt, sondern entstehen im Kopf des Betrachters; Apophenie ist eine allgemein menschliche Tendenz, die auch in der Allgemeinbevölkerung regelmäßig vorkommt (Blain u. a. 2020).","coreRule":"⚡ Das Gehirn sieht Muster, auch wo keine sind: in Wolken, Serien und Ballungen.","beleg":"Werkstück B.9 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Alle drei Szenen verbindet, dass das Gehirn im bloßen Zufall Ordnung findet: Gesicht, „fällige“ Farbe, besondere Ursache. Die Muster entstehen im Kopf des Betrachters, nicht in der Sache. Diese Tendenz, Apophenie genannt, ist allgemein menschlich.","prueffrage":"Wie oft fällt beim Roulette fünfmal hintereinander dieselbe Farbe, wenn man über viele Abende hinweg zählt?","rueckmeldung":[{"option":1,"text":"Fehlendes Fachwissen kann Fehldeutungen begünstigen, vor allem bei Daten. Ein Tiergesicht in der Wolke oder die Roulette-Serie brauchen aber keine Daten und kein Fachwissen. Die Neigung, Ordnung zu sehen, betrifft alle Menschen, nicht nur Laien."},{"option":2,"text":"Hier wird keine Wahrnehmung für unwahr erklärt. Die Szenen zeigen im Gegenteil, dass Menschen im Zufall Muster sehen und ihnen Bedeutung zuschreiben. Dass sich ein Eindruck wiederholen lässt, macht ihn noch nicht zu einem echten Muster."},{"option":3,"text":"Wer etwas sieht, das andere übersehen, fühlt sich leicht wie ein Entdecker. In keiner der drei Szenen liegt aber ein echtes Muster vor: Gesicht, „fällige“ Farbe und Ursache der statistisch normalen Häufung entstehen erst im Kopf des Betrachters."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives. Journal of Abnormal Psychology 129(3) (PMC, Autorenmanuskript)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7112154/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives, Verlagsfassung","oeffentlich":false,"doi":"10.1037/abn0000504"}],"thema":"Psychologie"},{"id":"qx-b1-032","clusterId":"B","werkstueckRef":"B.9","stufe":3,"question":"Welche Schlussfolgerung ist aus diesem Studienergebnis am besten gerechtfertigt?","options":["Der Zusammenhang ist mäßig; ob das Mustersehen den Glauben verursacht, lässt sich aus diesem Ergebnis allein nicht ableiten.","Der Zusammenhang ist sehr stark, das Mustersehen erklärt den Verschwörungsglauben fast vollständig.","Der Zusammenhang ist so schwach, dass er in der Praxis keine Rolle spielt und ignoriert werden kann.","Der Zusammenhang gilt nur für sehr gebildete Menschen, bei allen anderen Gruppen wäre er garantiert nicht vorhanden."],"correctIndex":0,"explanation":"Ein Wert von r = 0,3 liegt weit unter 1: Das Mustersehen erklärt nur einen kleinen Teil der Unterschiede im Verschwörungsglauben, aber ganz ohne Zusammenhang ist es auch nicht. Außerdem sagt eine Korrelation nichts über die Richtung: Vielleicht macht Mustersehen anfällig für Verschwörungen, vielleicht prägt ein verschwörungsnahes Weltbild auch den Blick auf Zufallsdaten, oder ein dritter Faktor wirkt auf beides. Tatsächlich zeigte eine Reihe von Studien (van Prooijen u. a. 2018) Zusammenhänge meist um r = 0,2 bis 0,4. In Versuchen, in denen ein verschwörungsnaher Text das Mustersehen verstärkte, wirkten die Bedingungen teils nur über das Mustersehen auf den Glauben; die Autoren schließen daher starke Schlüsse über Ursache und Wirkung aus. Eine frühere Studie fand keinen solchen Zusammenhang; die Autoren erklären das unter anderem damit, dass er sich bei Hochgebildeten womöglich nicht zeigt. Eine Schlagzeile mit „macht anfällig“ behauptet mehr, als die Zahlen tragen.","coreRule":"⚡ Mäßige Korrelation heißt: ein Zusammenhang, aber weder vollständige Erklärung noch bewiesene Ursache.","beleg":"Werkstück B.9 (Anwendung & Relevanz: Bei Verschwörungsmythen); Fn. gl-b-prooijen (van Prooijen u. a. 2018, EJSP 48(3), S. 323–324 und 331–332)","status":"entwurf","scenario":"Eine Forschungsgruppe lässt Versuchspersonen Münzwurf-Folgen betrachten und fragt, ob sie darin Muster erkennen. Außerdem erfasst sie, wie sehr die Personen an Verschwörungstheorien glauben. Ergebnis: Wer in den zufälligen Folgen eher Muster sah, glaubte im Schnitt etwas häufiger an Verschwörungen. Der Zusammenhang liegt bei r = 0,3 (zur Orientierung: r = 0 bedeutet kein Zusammenhang, r = 1 ein perfekter). Eine Schlagzeile dazu lautet: „Mustersehen macht anfällig für Verschwörungsglauben!“","quote":"","quoteLabel":"","kurz":"Mit r = 0,3 besteht ein mäßiger, aber echter Zusammenhang, der allein jedoch nichts darüber verrät, was Ursache und was Wirkung ist. Der naheliegende Fehler ist, aus „tritt zusammen auf“ ein „macht anfällig“ zu lesen.","prueffrage":"Liegt r = 0,3 näher an 0 oder an 1, und hat die Forschungsgruppe das Mustersehen gezielt verändert oder nur gemessen?","rueckmeldung":[{"option":1,"text":"Ein Wert von 0,3 ist leicht für stark zu halten, weil er deutlich über null liegt. Er liegt aber weit unter 1: Das Mustersehen erklärt nur einen kleinen Teil der Unterschiede im Glauben, von „fast vollständig“ kann keine Rede sein."},{"option":2,"text":"Daran stimmt, dass 0,3 kein starker Zusammenhang ist. Bedeutungslos ist er aber nicht: Er ist mäßig und zeigt sich in mehreren Studien ähnlich, ihn zu ignorieren wäre die umgekehrte Übertreibung."},{"option":3,"text":"Dass ein Zusammenhang je nach Gruppe verschieden ausfallen kann, ist denkbar. Über die Bildung der Versuchspersonen ist hier aber nichts bekannt, und „garantiert nicht vorhanden“ ist viel zu absolut für eine bloße Vermutung."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"van Prooijen, J.-W.; Douglas, K. M.; De Inocencio, C. (2018): Connecting the dots: Illusory pattern perception predicts belief in conspiracies and the supernatural. European Journal of Social Psychology 48(3) (PMC, CC BY 4.0)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5900972","abruf":"2026-10-12"},{"typ":"doi","kurz":"van Prooijen, J.-W.; Douglas, K. M.; De Inocencio, C. (2018): Connecting the dots, Verlagsfassung","oeffentlich":true,"doi":"10.1002/ejsp.2331","seite":"331–332"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-033","clusterId":"B","werkstueckRef":"B.9","stufe":4,"question":"Was ist der erste sinnvolle Prüfschritt?","scenario":"In einem Viertel deiner Gemeinde sind innerhalb eines Jahres auffällig viele Fälle derselben Erkrankung gemeldet worden. Im Ort wird über eine gemeinsame Ursache spekuliert: Manche vermuten das Trinkwasser, andere den Mobilfunkmast am Ortsrand.","options":["Alle Betroffenen nach Gemeinsamkeiten befragen und jede gefundene Gemeinsamkeit als mögliche Ursache festhalten und weiterverfolgen.","Die Häufung als Zufall abtun, da Ballungen in Daten meist keine Bedeutung haben, und keine weitere Prüfung veranlassen.","Prüfen, ob die Häufung über das zufällig zu Erwartende hinausgeht, bevor nach einer Ursache gesucht wird.","Die Häufung zunächst als Warnsignal werten und vorsorglich Maßnahmen gegen die naheliegendste Vermutung fordern, bis die Ursache geklärt ist."],"correctIndex":2,"explanation":"Die Clustering-Illusion beschreibt die Tendenz, in zufälligen Verteilungen „Ballungen“ zu sehen und ihnen eine besondere Bedeutung beizumessen; vermeintliche „Krebscluster“ in einer Stadt erweisen sich bei genauer Prüfung oft als statistisch unauffällig. Der erste Schritt ist deshalb die Frage, ob ein solches Muster auch in rein zufälligen Daten ähnlich wahrscheinlich wäre; erst wenn die Häufung über das zufällig zu Erwartende hinausgeht, lohnt die Suche nach einer Ursache. Wer sofort Gemeinsamkeiten unter den Betroffenen sammelt, hat noch nichts getestet, sondern verbindet nur Punkte im Nachhinein zu einem Muster. Wer die Häufung ungeprüft als Zufall abtut, ersetzt bloß die eine Annahme durch die andere. Und Maßnahmen gegen die naheliegendste Vermutung zu fordern, wäre Handeln auf einer ungeprüften Annahme.","coreRule":"⚡ Bevor du ein Muster erklärst, prüfe, ob der Zufall es auch erzeugen könnte.","quote":"„Das kann doch kein Zufall sein!“","quoteLabel":"Typische Aussage:","beleg":"Werkstück B.9 (Kontext & Tiefe: Clustering-Illusion; Red Flags; Das Anti-Denkmuster)","status":"entwurf","kurz":"Eine Ballung, die man erst im Nachhinein bemerkt, kann ein normales Zufallsmuster sein. Deshalb kommt zuerst die Frage, ob sie über das zufällig zu Erwartende hinausgeht; erst danach lohnt die Suche nach einer Ursache.","prueffrage":"Wie viele andere Viertel, Jahre und Krankheiten hätte man ebenso betrachten können, und wie oft fiele dabei irgendwo eine Häufung auf?","rueckmeldung":[{"option":0,"text":"Gemeinsamkeiten zu sammeln wirkt gründlich, ist aber noch kein Test: Bei vielen Betroffenen findet sich fast immer etwas Verbindendes, das im Nachhinein wie ein Muster aussieht. Zuerst muss geklärt sein, ob die Häufung überhaupt mehr als Zufall ist."},{"option":1,"text":"Dass Ballungen auch zufällig entstehen, stimmt. Ob das hier der Fall ist, steht aber erst nach einer Prüfung fest. Wer sie ungeprüft als Zufall abtut, ersetzt nur eine Annahme durch die andere."},{"option":3,"text":"Eine Häufung ernst zu nehmen ist richtig. Maßnahmen gegen eine Vermutung zu verlangen, bevor feststeht, dass die Häufung mehr als Zufall ist, wäre aber Handeln auf einer ungeprüften Annahme, und dabei bliebe die Frage nach der echten Ursache offen."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"National Cancer Institute: Cancer Clusters Fact Sheet","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/substances/cancer-clusters-fact-sheet","abruf":"2026-10-12"},{"typ":"url","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives (PMC, Autorenmanuskript)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7112154/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-b1-034","clusterId":"B","werkstueckRef":"B.10","stufe":1,"question":"Du bekommst eine „persönliche Analyse“ und findest dich fast komplett darin wieder. Welche Frage prüft am besten, ob sie wirklich auf dich zugeschnitten ist?","options":["Würden sich auch viele andere Menschen in genau diesen Sätzen wiedererkennen?","Wie professionell und seriös sieht die App aus, die das Ergebnis liefert?","Wie viele meiner Bekannten haben denselben Test gemacht und waren beeindruckt?","Wie gut fühle ich mich, nachdem ich die Beschreibung gelesen habe?"],"correctIndex":0,"explanation":"Die Sätze sind so allgemein, dass sie auf fast jeden zutreffen: Fast jeder ist mal gesellig, mal zurückhaltend, fast jeder ist sich selbst gegenüber manchmal kritisch. Sie schmeicheln dem Selbstbild („ungenutzte Fähigkeiten“) und enthalten nur einen Hauch harmloser Kritik, das wirkt echt. Dazu kommt, dass unser Gedächtnis sofort passende Situationen abruft und die unpassenden übergeht. Dass die Aussage auf dich passt, ist deshalb kein Beweis, dass sie für dich gemacht wurde. Entscheidend ist, ob sie auch auf viele andere passen würde. Im Klassenexperiment von Forer (1948) bewerteten Studierende denselben, aus Horoskopen zusammengestellten Text im Schnitt mit 4,26 von 5 als treffend. Dass auch Bekannte beeindruckt waren, passt genau zum Effekt: Eine allgemeine Beschreibung trifft bei vielen zu. Ein seriöses Aussehen der Quelle und das gute Gefühl verstärken den Effekt zwar, belegen aber nicht, dass die Beschreibung für dich gemacht wurde.","coreRule":"⚡ Wenn eine „persönliche“ Beschreibung auf fast jeden passt, sagt sie nichts über dich.","beleg":"Werkstück B.10 (Kontext & Tiefe)","status":"entwurf","scenario":"Eine App wertet einen kurzen Fragebogen aus und schreibt dir: „Du hast ein großes Bedürfnis nach Anerkennung. Manchmal bist du gesellig, manchmal zurückhaltend. Du bist dir selbst gegenüber oft kritisch und hast Fähigkeiten, die du noch nicht voll nutzt.“ Du denkst: „Das bin genau ich!“","quote":"","quoteLabel":"","kurz":"Entscheidend ist, ob die Sätze auch auf viele andere passen würden. Das tun sie, denn sie sind so allgemein, dass fast jeder sich wiederfindet. Dass es bei dir passt, beweist also nicht, dass es für dich gemacht wurde.","prueffrage":"Steht in den Sätzen irgendetwas Konkretes, etwa ein Ereignis, ein Name oder eine Vorliebe, das nur in deinem Leben vorkommt?","rueckmeldung":[{"option":1,"text":"Ein professioneller Auftritt macht einen Text glaubwürdiger und verstärkt damit den Eindruck, gemeint zu sein. Ob die Beschreibung auf dich zugeschnitten ist, sagt das Design aber nicht, denn es verrät nichts über den Inhalt der Sätze."},{"option":2,"text":"Viele beeindruckte Bekannte wirken wie eine Bestätigung. Genau das wäre aber auch zu erwarten, wenn die Sätze so allgemein sind, dass sie bei fast jedem zutreffen; über einen Zuschnitt auf dich sagt das Staunen nichts."},{"option":3,"text":"Das gute Gefühl entsteht, weil der Text schmeichelt, etwa mit „ungenutzten Fähigkeiten“. Es verstärkt den Eindruck, gemeint zu sein, belegt aber nicht, dass die Beschreibung für dich gemacht wurde."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Technik und KI"},{"id":"qx-b1-035","clusterId":"B","werkstueckRef":"B.10","stufe":2,"question":"Was ist an der Schlussfolgerung deiner Freundin am ehesten fehlerhaft?","scenario":"Nach einer Sitzung bei einem Medium sagt eine Freundin begeistert: „Es hat mir gesagt, dass ich mir Sorgen um Geld mache und eine Kiste mit alten Fotos habe, die ich nicht wegwerfen kann. Beides stimmt! Das Medium muss echte Fähigkeiten haben.“ Auf Nachfrage räumt sie ein, dass es auch noch einiges andere gesagt hat, das nicht gepasst hat, daran erinnert sie sich aber kaum noch.","options":["Sie zählt die erinnerten Treffer und übergeht die Fehlschüsse, obwohl solche allgemeinen Aussagen auf fast jeden passen.","Sie lässt sich von einer einzelnen Aussage überzeugen, obwohl erst mehrere zutreffende Aussagen ein Gespür für Menschen belegen würden.","Sie hält die Treffer für Zufall, obwohl Medien in Wahrheit gezielt Informationen über ihre Kunden recherchieren.","Sie glaubt dem Medium zu schnell, weil Aussagen über Gefühle grundsätzlich nicht überprüfbar sind und deshalb nichts beweisen."],"correctIndex":0,"explanation":"Die Freundin zählt nur die Treffer und blendet die Fehlschüsse aus. „Du machst dir Sorgen um Geld“ und „Du hast eine Kiste mit alten Fotos, die du nicht wegwerfen kannst“ sind typische Barnum-Aussagen aus dem Cold Reading. Ein Cold Reader feuert viele solcher Aussagen ab und beobachtet die Reaktion seines Gegenübers. Die Treffer werden vom Klienten bestätigt und ausgebaut, die Fehlschüsse werden ignoriert. So entsteht der Eindruck großer Treffsicherheit, obwohl nur Allgemeines gesagt wurde.","coreRule":"⚡ Wer nur die Treffer zählt und die Fehlschüsse vergisst, hält Allgemeinplätze für Treffsicherheit.","beleg":"Werkstück B.10 (Anwendung & Relevanz: Bei Wahrsagern, Hellsehern & Cold Reading)","status":"entwurf","kurz":"Die Freundin zählt nur, was gepasst hat, und vergisst die Fehlschüsse. Solche allgemeinen Aussagen passen auf fast jeden, und wer viele davon abfeuert, landet fast sicher Treffer. Diese sagen deshalb nichts über besondere Fähigkeiten.","prueffrage":"Wie viele andere Aussagen hat das Medium gemacht, und wie viele davon haben tatsächlich gepasst?","rueckmeldung":[{"option":1,"text":"Die Freundin stützt sich auf zwei Treffer, nicht auf eine einzelne Aussage. Das Problem liegt woanders: Auch mehr Treffer würden wenig zeigen, solange die Aussagen so allgemein sind und die Fehlschüsse aus der Erinnerung verschwinden."},{"option":2,"text":"Die Freundin hält die Treffer gerade nicht für Zufall, sondern für den Beweis echter Fähigkeiten. Recherche bräuchte es hier auch nicht: Aussagen über Geldsorgen und eine Kiste mit alten Fotos passen ohnehin auf viele."},{"option":3,"text":"Aussagen über Gefühle lassen sich durchaus prüfen, etwa indem die Betroffene sie bestätigt oder verneint. Der Fehler liegt woanders: Gezählt werden nur die Treffer, die Fehlschüsse fallen unter den Tisch."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Selective Attention“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-b1-036","clusterId":"B","werkstueckRef":"B.10","stufe":3,"question":"Wie viel von dieser Namensgeschichte darfst du als gesichert ansehen?","options":["Dass Barnum auf ein breites Publikum zielte, gilt als gesichert, weil sein Geschäft gut dokumentiert ist; ob er den Satz sagte, bleibt ohne Quelle offen.","Dass Barnum den Satz sagte, gilt als gesichert, weil er überall zitiert wird; offen ist nur die Gelegenheit.","Dass der Effekt auf Barnum selbst zurückgeht, gilt als gesichert, weil er seinen Namen trägt; offen ist nur das Jahr.","Dass Barnum den Satz selbst öffentlich sagte, gilt als gesichert, weil Zirkusleute so redeten; ein Beleg ist überflüssig."],"correctIndex":0,"explanation":"Hier gilt es, zweierlei zu trennen: Barnums Ruf und den angeblichen Wortlaut. Real ist sein Ruf als Schausteller, der sein Programm bewusst auf ein möglichst breites Publikum zuschnitt. Der Satz „Wir haben für jeden etwas dabei“ ist ihm dagegen nur populär zugeschrieben, ohne Beleg. Ein Zitat wird nicht dadurch belegt, dass es oft wiederholt wird oder gut zur Person passt. Auch das noch bekanntere „Alle naslang wird ein Dummkopf geboren“ ist nicht verifiziert. Und der Name „Barnum-Effekt“ stammt nicht von Barnum selbst: Er wurde 1956 vom Psychologen Paul E. Meehl geprägt, der ihn nach Barnums Ruf benannte. Der Effekt geht also nicht auf Barnum zurück, nur sein Name wurde geliehen. Wer einem Zitat oder einer Namensgebung vertrauen will, fragt deshalb nach der Quelle, nicht nach der Bekanntheit.","coreRule":"⚡ Ein oft wiederholtes Zitat ist noch kein belegtes Zitat: Frag nach der Quelle.","beleg":"Werkstück B.10 (Kontext & Tiefe); Fn. gl-b-barnum","status":"entwurf","scenario":"In einem Artikel über Persönlichkeitstests steht: „Der Barnum-Effekt geht auf den Zirkusmann P. T. Barnum zurück, der einst sagte: ‚Wir haben für jeden etwas dabei.‘“ Ein Beleg für den Satz wird nicht genannt, der Artikel verweist nur auf Barnums Ruf als Schausteller.","kurz":"Gesichert ist Barnums Ruf, ein breites Publikum zu bedienen; der Satz ist ihm nur ohne Beleg zugeschrieben, und den Namen „Barnum-Effekt“ prägte erst 1956 der Psychologe Paul E. Meehl. Dass ein Zitat gut zur Person passt, ersetzt keine Quelle.","prueffrage":"Wann bekam der Effekt seinen Namen, und lebte Barnum da noch?","rueckmeldung":[{"option":1,"text":"Ein Zitat, das überall steht, wirkt belegt. Dass es oft wiederholt wird, zeigt aber nur seine Beliebtheit, nicht seinen Ursprung. Offen ist deshalb nicht bloß die Gelegenheit, sondern ob Barnum es überhaupt sagte."},{"option":2,"text":"Wessen Namen ein Effekt trägt, der wird leicht für den Urheber gehalten. Den Namen „Barnum-Effekt“ prägte aber 1956 der Psychologe Paul E. Meehl nach Barnums Ruf. Offen ist also nicht nur ein Jahr: Der Effekt selbst geht nicht auf Barnum zurück."},{"option":3,"text":"Dass der Satz zu einem Zirkusmann passt, macht ihn plausibel. Die Passung zum Milieu ist aber kein Beleg, und gerade der fehlt hier. Gesichert ist nur Barnums Ruf als Schausteller, nicht der Wortlaut."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Barnum effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/barnum.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Meehl, P. E. (1956): Wanted—a good cook-book. American Psychologist 11(6), 263–272","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-037","clusterId":"B","werkstueckRef":"B.10","stufe":4,"question":"Was folgt aus dem Treffer für die Frage, ob der Dienst dich persönlich „durchschaut“?","scenario":"Dein Streamingdienst schlägt dir einen Song vor, der genau zu deiner Stimmung passt, und du denkst: „Der kennt mich besser als meine Freunde.“ Du weißt, dass der Dienst seine Vorschläge aus den Hörgewohnheiten sehr vieler Nutzer ableitet.","options":["Gar nichts Sicheres: Ein auf breite Muster gestützter Vorschlag kann sich persönlich anfühlen, ohne dich persönlich zu erfassen.","Er zeigt, dass der Dienst dich gut kennt, denn ein so genau passender Song entsteht ohne persönliches Verständnis kaum.","Er zeigt, dass der Dienst nichts über dich weiß, denn ein so gut passender Treffer kann nur reiner Zufall sein.","Er zeigt, dass der Dienst fast immer danebenliegt, denn nur wenige Vorschläge passen und die Treffer merkst du dir."],"correctIndex":0,"explanation":"Das gute Gefühl allein sagt wenig darüber, wie der Vorschlag zustande kam. Algorithmen stützen sich oft auf breite statistische Muster, die auf Millionen von Menschen zutreffen, sich für den Einzelnen aber ganz persönlich anfühlen. Das ist ein digitaler Barnum-Effekt: Bereits 1948 gab der Psychologe Bertram Forer seinen Studenten allen denselben, aus Horoskopen zusammengestückelten Text. Sie bewerteten ihn im Mittel mit 4,26 auf einer Skala von 0 bis 5, obwohl er für niemanden maßgeschneidert war. Die gefühlte Treffsicherheit ist deshalb kein Beleg für tiefes Verstehen. Der Schluss „Treffer = der Dienst kennt mich gut“ geht vom Gefühl auf die Ursache. „Reiner Zufall“ und „fast immer daneben“ schießen ins Gegenteil über, ohne es zu belegen.","coreRule":"⚡ Gefühlte Treffsicherheit ist kein Beweis für echtes Verstehen.","beleg":"Werkstück B.10 (Anwendung & Relevanz: Bei algorithmischer Personalisierung)","status":"entwurf","kurz":"Ein Treffer sagt wenig darüber, wie der Vorschlag entstand: Muster aus den Hörgewohnheiten vieler Nutzer können sich ganz persönlich anfühlen. Vom Gefühl auf tiefes Verstehen zu schließen, ist daher ein Fehlschluss.","prueffrage":"Woraus leitet der Dienst seine Vorschläge ab, und was davon betrifft nur dich?","rueckmeldung":[{"option":1,"text":"Dass sich der Treffer sehr persönlich anfühlt, ist echt. Daraus folgt aber nicht, dass er persönlich entstand: Muster aus den Daten vieler Nutzer können genauso gut passen und denselben Eindruck erzeugen."},{"option":2,"text":"Daran stimmt, dass der Treffer kein tiefes Verstehen belegt. Die Vorschläge beruhen aber auf Daten, nicht auf Zufall, und ein Treffer zeigt auch nicht, dass der Dienst nichts über dich weiß."},{"option":3,"text":"Treffer merkt man sich tatsächlich stärker als Fehlgriffe. Ob der Dienst oft danebenliegt, lässt sich aus einem einzelnen Treffer aber nicht ablesen; das wäre nur ein weiterer Schluss ohne Beleg."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Technik und KI"},{"id":"qx-b1-038","clusterId":"B","werkstueckRef":"B.11","stufe":1,"question":"Welche Schlussfolgerung ist aus der Beobachtung gerechtfertigt?","scenario":"Du siehst nachts ein Licht, das schnell fliegt, plötzlich stehen bleibt und abrupt die Richtung ändert. Dein Freund sagt: „Ich kenne kein Flugzeug und keinen Satelliten, die das können – also muss es ein außerirdisches Raumschiff sein!“","options":["Es war ein außerirdisches Raumschiff, denn eine bessere Erklärung hat bisher niemand geliefert.","Es war sicher ein Flugzeug oder eine Drohne, denn etwas anderes kommt statistisch nie in Betracht.","Es war nichts Reales, denn wenn niemand es erklären kann, hat es vermutlich nicht stattgefunden.","Es war ein unidentifiziertes Flugobjekt im wörtlichen Sinn, denn ich weiß schlicht nicht, was es war."],"correctIndex":3,"explanation":"Die Beobachtung zeigt nur, dass dein Freund keine Erklärung kennt. Das ist eine Aussage über den Stand seines Wissens, nicht über die Ursache des Lichts. Aus „mir fällt keine natürliche Erklärung ein“ folgt nicht, dass die Lieblingserklärung stimmt, und ebenso wenig, dass das Phänomen nicht stattgefunden hat oder doch ein gewöhnliches Objekt war. Eine Wissenslücke ist kein Beweis für irgendeine bestimmte Erklärung. Gerechtfertigt ist nur die ehrliche Feststellung, dass das Licht unidentifiziert bleibt. Sinnvoll ist dann, die Lücke zu untersuchen, statt sie mit einer bevorzugten Erklärung zu füllen.","coreRule":"⚡ „Ich weiß es nicht“ ist eine vollständige und ehrliche Antwort: Eine Wissenslücke beweist keine bestimmte Erklärung.","beleg":"Werkstück B.11 (Das Licht am Nachthimmel; Kontext & Tiefe)","status":"entwurf","kurz":"Aus der Beobachtung folgt nur, dass das Licht unidentifiziert bleibt. Dass dein Freund keine Erklärung kennt, sagt etwas über sein Wissen aus, nicht über die Ursache, und stützt deshalb weder das Raumschiff noch ein gewöhnliches Objekt.","prueffrage":"Was lässt sich bei einem Licht am Nachthimmel mit bloßem Auge über seine Entfernung, Größe und Geschwindigkeit sicher sagen?","rueckmeldung":[{"option":0,"text":"Wenn keine bessere Erklärung da ist, wirkt die vorhandene schnell überzeugend. Dass niemand eine liefert, spricht aber nicht für das Raumschiff: Eine Wissenslücke belegt keine bestimmte Ursache."},{"option":1,"text":"Flugzeuge und Drohnen sind häufige Quellen nächtlicher Lichter, das stimmt. „Sicher“ und „nie“ gehen aber weit über jeden Beleg hinaus, und aus der Beobachtung allein folgt auch das nicht."},{"option":2,"text":"Etwas Unerklärtes wirkt leicht verdächtig, als sei da nichts gewesen. Das Licht wurde aber gesehen. Dass es sich nicht erklären lässt, ändert nichts daran, dass es stattgefunden hat."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-b1-039","clusterId":"B","werkstueckRef":"B.11","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Dein Onkel sagt: „Es gibt keinen einzigen Beweis, dass es Leben auf anderen Planeten gibt – also gibt es keins.“","options":["Er folgert aus dem fehlenden Beweis, dass die Behauptung falsch ist, obwohl ein fehlender Beweis für sich allein noch nicht zeigt, dass es etwas nicht gibt.","Er ist nicht fehlerhaft, weil bis zu einem Beleg das Gegenteil der Behauptung als richtig gelten darf.","Er ist nur dann fehlerhaft, wenn es tatsächlich Leben auf anderen Planeten gibt, weil die Aussage des Onkels dann falsch wäre.","Er ist fehlerhaft, weil ein fehlender Beweis immer bedeutet, dass die Behauptung wahr sein muss."],"correctIndex":0,"explanation":"Der Onkel schließt von „nicht bewiesen“ auf „falsch“. Das ist das Argument aus Unwissenheit: Ein fehlender Beweis allein zeigt nicht, dass etwas nicht existiert, sondern zunächst nur, dass wir es nicht wissen. Gewicht bekommt das Fehlen eines Belegs erst, wenn gründlich dort gesucht wurde, wo ein Beleg zu erwarten wäre; über die allermeisten Planeten wissen wir dafür noch viel zu wenig. Der Fehler liegt also im Übergang von der Wissenslücke zur festen Aussage. Zulässig wäre: „Ich kenne keinen Beleg und halte die Frage deshalb für offen.“","coreRule":"⚡ Kein Beweis dafür heißt nicht „falsch“, kein Beweis dagegen nicht „wahr“.","beleg":"Werkstück B.11 (Kontext & Tiefe: Negative Form)","status":"entwurf","kurz":"Aus „nicht bewiesen“ folgt nicht „falsch“: Ein fehlender Beleg zeigt für sich allein nur eine Wissenslücke, nicht, dass etwas nicht existiert. Der Fehler liegt darin, aus dem Nichtwissen eine feste Aussage zu machen. Offenlassen wäre zulässig.","prueffrage":"Was genau wurde bisher untersucht, und was würde man finden, wenn es dort doch etwas gäbe?","rueckmeldung":[{"option":1,"text":"Eine Regel, das Gegenteil bis zum Beleg als richtig zu behandeln, trägt hier nicht. Ein fehlender Beleg lässt die Frage offen, und der Onkel behauptet mehr: Er stellt „gibt keins“ als feste Aussage hin."},{"option":2,"text":"Ob die Aussage am Ende stimmt, entscheidet nicht über die Qualität des Schlusses. Selbst wenn es kein Leben gäbe, wäre der Weg dorthin fehlerhaft: Aus einer Wissenslücke wurde ohne Grund eine feste Behauptung."},{"option":3,"text":"Daran stimmt, dass der Schluss fehlerhaft ist. Die Begründung wiederholt den Fehler aber nur andersherum: Ein fehlender Beweis zeigt für sich allein weder, dass etwas wahr, noch dass es falsch ist, sondern zunächst nur, dass wir es nicht wissen."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-b1-040","clusterId":"B","werkstueckRef":"B.11","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"In einer Debatte heißt es: „Die Wissenschaft kann bisher nicht bis ins letzte Detail erklären, wie das erste Leben aus unbelebter Materie entstand. Also muss es erschaffen worden sein.“","options":["Der Schluss wäre gültig, falls die Wissenschaft die Lücke auch in hundert Jahren nicht schließen kann, denn dann bliebe keine andere Erklärung.","Der Schluss ist fehlerhaft, weil schon die Frage nach dem Ursprung des Lebens nicht sinnvoll gestellt werden kann, solange Daten fehlen.","Der Schluss ist fehlerhaft, weil aus einer Wissenslücke keine bestimmte Erklärung folgt; sie zeigt nur, dass etwas noch offen ist.","Der Schluss ist gültig, aber unvollständig, weil er neben der genannten Erklärung weitere mögliche Erklärungen nennen müsste."],"correctIndex":2,"explanation":"Eine Wissenslücke ist selbst kein Beleg für eine bestimmte Erklärung. Aus „Das wissen wir noch nicht“ folgt nicht „Also gilt meine bevorzugte Antwort“. Dieser Fehlschluss heißt Argument aus Unwissenheit, in religiösen Zusammenhängen auch „Gott der Lücken“: Eine aktuelle Lücke im wissenschaftlichen Verständnis wird als Beweis für die eigene Position ausgegeben. Dabei wird die Lücke willkürlich mit einer bevorzugten, unbewiesenen Erklärung gefüllt. Die ehrliche Antwort auf eine Lücke lautet: „Das wissen wir (noch) nicht.“","coreRule":"⚡ Eine Wissenslücke ist eine Frage, keine Antwort.","beleg":"Werkstück B.11 (Anwendung & Relevanz: Im Kreationismus & „Intelligent Design“; Der Kipppunkt)","status":"entwurf","kurz":"Eine Wissenslücke belegt keine bestimmte Erklärung: Aus „Das wissen wir noch nicht“ folgt nicht „Also gilt meine bevorzugte Antwort“. Der Fehler liegt darin, die Lücke mit der eigenen, unbewiesenen Erklärung zu füllen.","prueffrage":"Welche Beobachtung nennt die Aussage, die für sich genommen auf eine Erschaffung hindeutet?","rueckmeldung":[{"option":0,"text":"Eine Lücke kann tatsächlich lange bestehen bleiben. Auch eine dauerhafte Lücke wäre aber kein Beleg für eine bestimmte Erklärung: Dass keine andere Antwort bekannt ist, macht die bevorzugte nicht wahr."},{"option":1,"text":"Fehlende Daten begrenzen, wie sicher eine Antwort sein kann. Sinnlos wird die Frage dadurch nicht, sie bleibt offen und lässt sich weiter untersuchen. Das Problem liegt im Schluss, nicht in der Fragestellung."},{"option":3,"text":"Es gibt tatsächlich weitere mögliche Erklärungen, und der Schluss übergeht sie. Gültig würde er aber auch mit allen Alternativen nicht, denn die Lücke stützt keine einzelne davon. Das Problem liegt im Schluss selbst."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-b1-041","clusterId":"B","werkstueckRef":"B.12","stufe":1,"question":"Welcher Denkfehler steckt in der Schlussfolgerung der Zuschauerin, und woran liegt er?","scenario":"Ein Nachrichtenmagazin kündigt eine Sondersendung an: „Die Form der Erde: Gibt es eine Kontroverse?“ Eine Astrophysikerin und ein YouTuber, der die Erde für eine Scheibe hält, bekommen exakt gleich viel Redezeit. Der Moderator schließt: „Eine faszinierende Diskussion mit vielen offenen Fragen. Bilden Sie sich Ihre eigene Meinung.“ Eine Zuschauerin sagt danach: „Dann scheint sich die Wissenschaft ja nicht einig zu sein.“","options":["Sie schließt von der gleichen Redezeit zweier Gäste auf eine gleich starke Beweislage, obwohl die Sendung nichts über die tatsächliche Verteilung der Expertenmeinungen sagt.","Sie schließt von der sachlichen Höflichkeit beider Gäste auf deren Glaubwürdigkeit, obwohl Höflichkeit nichts über die fachliche Qualifikation aussagt.","Sie schließt von der Schlussbemerkung des Moderators auf dessen Parteilichkeit, obwohl ein Moderator nie ein Urteil über Sachfragen abgeben darf.","Sie schließt von der Prominenz des Magazins auf die Richtigkeit der Sendung, obwohl große Redaktionen sich ebenso irren können wie kleine."],"correctIndex":0,"explanation":"Wie viel Bühne und Redezeit jemand bekommt, sagt nichts darüber, wie viele Fachleute seine Position teilen oder wie gut sie belegt ist. Bei der Form der Erde stützen Satellitendaten, Flugrouten, Erdkrümmung und astronomische Beobachtungen eine Seite erdrückend, die andere hat dem nichts Vergleichbares entgegenzusetzen. Die Sendung formt trotzdem den Eindruck einer 50/50-Kontroverse unter Experten, und die Zuschauerin übernimmt ihn. Bei politischen Meinungsfragen ist es sinnvoll, beide Seiten anzuhören. Bei Fragen mit erdrückender Beweislage verzerrt dasselbe Prinzip die Realität. Die richtige Prüffrage lautet daher nicht „Wurden beide gehört?“, sondern „Wie verteilen sich Belege und Fachmeinungen tatsächlich?“. Dass der Moderator beide Positionen als gleichwertig behandelt und die Beweislage nicht einordnet, überlässt die Wahrheitsfindung dem Publikum und erzeugt den falschen Eindruck einer Kontroverse.","coreRule":"⚡ Gleiche Redezeit ist keine gleiche Beweislage.","beleg":"Werkstück B.12 (Die Debatte über die Form der Erde; Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Gleiche Redezeit zeigt nur, wie die Sendung aufgebaut ist, nicht wie viele Fachleute eine Position teilen oder wie gut sie belegt ist. Wer aus der Bühne auf eine 50/50-Lage schließt, übernimmt einen Eindruck, den die Beweislage nicht trägt.","prueffrage":"Was weißt du über die Form der Erde aus anderen Quellen, etwa von Satellitenbildern oder Flugrouten, und passt das zu einer offenen Streitfrage?","rueckmeldung":[{"option":1,"text":"Höfliches Auftreten sagt tatsächlich nichts über Fachkompetenz aus. Die Zuschauerin schließt aber nicht von Höflichkeit auf Glaubwürdigkeit, sondern von der Gesprächsanlage auf eine uneinige Wissenschaft. Der Fehler liegt in diesem Schluss."},{"option":2,"text":"Ein Moderator darf Sachfragen durchaus einordnen, und gerade das fehlt hier. Die Zuschauerin zweifelt auch nicht an seiner Neutralität, sondern folgert aus dem Sendungsbild eine Uneinigkeit der Wissenschaft, die es so nicht gibt."},{"option":3,"text":"Dass auch große Redaktionen irren können, stimmt. Die Zuschauerin schließt aber nicht auf die Richtigkeit der Sendung, sondern auf eine uneinige Wissenschaft, und dieser Eindruck stammt aus der gleichen Redezeit, nicht aus dem Ruf des Magazins."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016, Journal of Experimental Psychology: Applied)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-b1-042","clusterId":"B","werkstueckRef":"B.12","stufe":2,"question":"Welche Frage deckt am besten auf, dass diese Gleichbehandlung das Bild verzerren könnte?","scenario":"Du siehst eine Talkrunde zu einem Gesundheitsthema: links eine Epidemiologin, die den breiten Befund der Fachliteratur vertritt, rechts ein Gast mit eigener Theorie, die kaum ein Fachmensch teilt. Beide bekommen gleich viel Redezeit, und der Moderator schließt mit: „Eine spannende Kontroverse, bilden Sie sich Ihre eigene Meinung.“","options":["Haben beide Gäste ungefähr gleich viele Studien genannt, um ihre Position zu belegen?","Entspricht die Verteilung der Gäste der tatsächlichen Verteilung der Expertenmeinungen im Fachgebiet?","Wirkt der Moderator persönlich unvoreingenommen und stellt er beiden Gästen faire Fragen?","Läuft die Sendung bei einem Sender, der zu einer ausgewogenen Berichterstattung verpflichtet ist?"],"correctIndex":1,"explanation":"Ob eine Debatte das Bild der Wirklichkeit wiedergibt, hängt nicht davon ab, wie fair die Bühne gebaut ist, sondern davon, wie die Beweislage tatsächlich verteilt ist. Wenn nahezu alle Fachleute eine Position teilen und nur eine Handvoll die andere, erzeugen zwei gleich große Redeanteile beim Publikum den falschen Eindruck eines 50/50-Streits unter Experten. Wer das prüfen will, vergleicht die Verteilung der Gäste mit der Verteilung der Expertenmeinungen im Feld. Die Zahl der genannten Studien sagt wenig, denn eine Handvoll Studien kann gegen Tausende stehen und wird durch bloßes Nennen nicht gleichwertig. Auch ein unvoreingenommener Moderator oder ein Sendeauftrag zur Ausgewogenheit ändern nichts am Gewicht der Belege: Äußere Fairness kann eine innere Verzerrung sogar verdecken.","coreRule":"⚡ Frag nicht nach der Fairness der Bühne, sondern nach dem Gewicht der Belege.","beleg":"Werkstück B.12 (Das Anti-Denkmuster; Red Flags)","status":"entwurf","kurz":"Ob die Runde die Lage abbildet, zeigt der Vergleich mit dem Fach: Teilt fast die gesamte Fachwelt eine Position, erzeugen gleiche Redeanteile den falschen Eindruck eines 50/50-Streits. Der Denkfehler: Gleiche Bühne gilt als Ausgewogenheit der Belege.","prueffrage":"Woran hättest du als Zuschauer in der Sendung erkennen können, dass der zweite Gast mit seiner Theorie in der Fachwelt fast allein steht?","rueckmeldung":[{"option":0,"text":"Gleich viele genannte Studien wirken wie eine faire Belegprüfung. Gezählt wird aber nur, was in der Sendung fällt: Eine Handvoll Studien kann gegen Tausende stehen und wird durch bloßes Nennen nicht gleichwertig."},{"option":2,"text":"Ein fairer Moderator ist wünschenswert, sagt aber nichts über die Beweislage. Gerade saubere Moderation kann eine Schieflage verdecken, und der Schlusssatz „bilden Sie sich Ihre eigene Meinung“ legt einen offenen Expertenstreit nahe."},{"option":3,"text":"Eine Pflicht zur Ausgewogenheit garantiert nicht, dass eine einzelne Runde die Fachmeinung richtig abbildet. Auch eine Sendung, die alle Regeln einhält, kann durch gleich große Redeanteile ein verzerrtes Bild zeichnen."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-b1-043","clusterId":"B","werkstueckRef":"B.12","stufe":3,"question":"Ein Nachrichtenmagazin plant zwei Beiträge. Beitrag 1: Ist die Erde eine Kugel? Beitrag 2: Bei der Behandlung einer seltenen Krankheit gehen zwei Forschungsgruppen mit jeweils guter Datenlage von unterschiedlichen Wirkmechanismen aus, und die Fachwelt ist gespalten. Wie sollte die Redaktion die beiden Beiträge anlegen?","options":["In keinem der Beiträge sollten Gegenpositionen vorkommen, weil Journalismus sich grundsätzlich nicht zu Fachfragen äußern sollte.","In beiden Beiträgen sollten zwei Gäste gleich lange sprechen, weil gleiche Redezeit unabhängig vom Thema die Fairness sichert.","Nur im zweiten Beitrag sollten beide Seiten ausführlich zu Wort kommen, weil nur dort die Fachwelt wirklich gespalten ist.","In beiden Beiträgen sollte die Gegenseite gleichberechtigt auftreten, weil eine einzelne Person mit Fachtitel dem Konsens widerspricht."],"correctIndex":2,"explanation":"Zwei Seiten gleichwertig darzustellen ist nur sinnvoll, wenn die Frage wirklich offen ist. Bei der seltenen Krankheit stützen beide Positionen belastbare Daten, und die Fachwelt ist tatsächlich gespalten; hier bildet eine Debatte die Lage korrekt ab. Bei der Kugelgestalt der Erde gibt es keine legitime wissenschaftliche Kontroverse mehr; die Frage gilt als längst entschiedene Kernfrage der Wissenschaft. Eine Debatte mit gleicher Redezeit erzeugt beim Publikum den falschen Eindruck einer 50/50-Kontroverse unter Experten und verzerrt die Realität. Gleiche Redezeit ist kein Maß für Fairness: Entscheidend ist, ob die Verteilung der Positionen im Beitrag der tatsächlichen Verteilung der Expertenmeinungen und der Beweislage entspricht. Dass eine einzelne Person dem Konsens widerspricht, macht noch keine echte Kontroverse; entscheidend ist die tatsächliche Expertenverteilung.","coreRule":"⚡ Zwei Seiten gehören dorthin, wo die Frage wirklich offen ist. Gewichte Positionen nach Beweislage, nicht nach Redezeit.","beleg":"Werkstück B.12 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"Die Redaktion möchte „fair und ausgewogen“ berichten und überlegt, in beiden Beiträgen jeweils zwei Gäste mit gleicher Redezeit auftreten zu lassen.","kurz":"Eine Debatte mit zwei Seiten bildet die Lage nur ab, wenn die Fachfrage wirklich offen ist, wie bei der seltenen Krankheit. Bei der Kugelgestalt der Erde täuscht gleiche Redezeit eine Expertenkontroverse vor, die es nicht gibt.","prueffrage":"Was unterscheidet die Datenlage hinter den Positionen beim ersten Thema von der beim zweiten?","rueckmeldung":[{"option":0,"text":"Berichte über Fachfragen sind legitim, auch wenn Journalistinnen und Journalisten keine Fachleute sind. Gerade die echte Kontroverse mit guter Datenlage gehört in den Beitrag, nur bei längst entschiedenen Fragen braucht es keine Gegenposition."},{"option":1,"text":"Gleiche Redezeit sieht fair aus, weil sie sich leicht abmessen lässt. Fair ist aber, die tatsächliche Verteilung der Fachmeinungen und Belege abzubilden; bei der Kugelgestalt der Erde täuscht gleiche Redezeit eine Kontroverse vor, die es nicht gibt."},{"option":3,"text":"Ein Fachtitel verleiht einer Stimme Gewicht, doch eine einzelne Person, die dem Konsens widerspricht, macht noch keine echte Kontroverse. Entscheidend ist, wie sich die Expertenmeinungen und die Belege tatsächlich verteilen."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-b1-044","clusterId":"B","werkstueckRef":"B.12","stufe":4,"question":"Welche Wirkung hat dieses Format auf Zuschauer, die das Thema nicht aus eigener Sachkenntnis beurteilen können?","scenario":"Ein Fernsehsender plant eine Sondersendung zum Klimawandel. Im Studio sitzen zwei Gäste: eine Klimaforscherin, deren Aussagen dem Stand der Fachliteratur entsprechen, und ein Redner, der die menschengemachte Erwärmung bestreitet und mit seiner Haltung unter Fachleuten kaum Rückhalt hat. Der Moderator gibt beiden exakt gleich viel Redezeit und schließt mit den Worten: „Eine spannende Debatte mit offenem Ausgang. Bilden Sie sich Ihre eigene Meinung.“","options":["Sie gewinnen den Eindruck, unter Fachleuten sei die Frage noch offen, obwohl die Fachwelt weitgehend einer Meinung ist.","Sie erhalten ein zutreffendes Bild des Expertenstands, weil beide Seiten gleich viel Gelegenheit bekommen, ihre Argumente darzulegen.","Sie erkennen die schwächeren Argumente des Bestreiters sofort, weil dieser sich vor Publikum selbst widerlegt und blamiert.","Sie bleiben in ihrer Einschätzung unbeeinflusst, weil Zuschauer ohnehin nur Positionen übernehmen, die zu ihrer Haltung passen."],"correctIndex":0,"explanation":"Wer nicht selbst beurteilen kann, wie verbreitet eine Position unter Fachleuten ist, schließt aus der Bühne auf das Gewicht: Gleiche Redezeit und ein offenes Schlusswort legen nahe, dass sich zwei etwa gleich starke Lager gegenüberstehen. Tatsächlich bejahen über 99 % der einschlägigen Fachartikel eine menschengemachte Erwärmung; die Beweislage ist also keineswegs 50 zu 50. Gleiche Bühnenzeit bildet nicht die Beweislage ab, sondern verzerrt sie. Eine bloße Gegenüberstellung ersetzt außerdem keine Einordnung: Die Bewertung der Beweiskraft wird dem unvorbereiteten Zuschauer überlassen, und die Bühne suggeriert eine 50/50-Kontroverse. Auch die Annahme, das Format ändere nichts, trägt nicht, denn der Eindruck, was „umstritten“ ist, entsteht gerade durch die Darstellung.","coreRule":"⚡ Eine 50:50-Bühne kann eine 99:1-Fachwelt als Streit erscheinen lassen.","beleg":"Werkstück B.12 (Anwendung & Relevanz: Bei der Leugnung des Klimawandels; Verweis auf Band VI)","status":"entwurf","kurz":"Wer das Thema nicht selbst beurteilen kann, schließt von der Bühne auf die Beweislage: Gleiche Redezeit und ein offenes Ende wirken wie ein Streit unter ebenbürtigen Lagern, obwohl die Fachwelt weitgehend einig ist.","prueffrage":"Woran könnte jemand ohne Sachkenntnis in dieser Sendung erkennen, welche der beiden Positionen in der Fachwelt Rückhalt hat?","rueckmeldung":[{"option":1,"text":"Gleiche Chancen für beide Seiten klingen fair, und bei der Redezeit sind sie es auch. Ein zutreffendes Bild der Fachwelt entsteht so aber nicht: Die Beweislage ist weit von 50 zu 50 entfernt, die Bühne bildet sie also verzerrt ab."},{"option":2,"text":"Man hofft leicht, dass sich schwache Argumente vor Publikum von selbst entlarven. Wer das Thema nicht beurteilen kann, erkennt sie aber gerade nicht verlässlich; die Einordnung bleibt am unvorbereiteten Publikum hängen."},{"option":3,"text":"Vorannahmen spielen beim Zuschauen oft eine Rolle. Daraus folgt aber nicht, dass die Darstellung nichts bewirkt: Gerade durch Redezeit und Schlusswort entsteht der Eindruck, was „umstritten“ ist."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Cornell Chronicle (2021): More than 99.9% of studies agree: Humans caused climate change","oeffentlich":true,"url":"https://news.cornell.edu/stories/2021/10/more-999-studies-agree-humans-caused-climate-change","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lynas, M.; Houlton, B. Z.; Perry, S. (2021): Greater than 99% Consensus on Human Caused Climate Change in the Peer-Reviewed Scientific Literature. Environmental Research Letters 16(11), 114005","oeffentlich":true,"doi":"10.1088/1748-9326/ac2966"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-b1-045","clusterId":"B","werkstueckRef":"B.13","stufe":1,"question":"Welche Rückfrage trifft den Kern des Fehlers in diesem Gespräch?","scenario":"Im Chat schreibt eine Kollegin: „Wie soll ein winziger Anteil eines unsichtbaren Gases wie CO2 das ganze Klima der Erde verändern? Das kann ich mir beim besten Willen nicht vorstellen, also ist die Sache Unsinn.“ Du willst ihr antworten.","options":["Beweist dein fehlendes Vorstellungsvermögen etwas über die Sache, oder zeigt es nur, wo dein Wissen gerade endet?","Wer genau hat diese Behauptung aufgestellt, und warum sollte man dieser Person überhaupt glauben?","Gibt es Gegenbeweise, die deine Zweifel an der Sache endgültig ausräumen, oder fehlen sie bisher?","Würden die meisten anderen Menschen diese Sache ebenfalls unplausibel finden, oder wäre das eher selten?"],"correctIndex":0,"explanation":"Die Kollegin schließt von „Ich kann mir nicht vorstellen, wie X wahr sein könnte“ auf „X ist nicht wahr“. Das ist ein Fehlschluss, denn die Grenzen der eigenen Vorstellungskraft sind kein Beleg gegen eine Behauptung. Unsere Intuition ist für Alltagsdinge in mittlerer Größe und bei mittlerer Geschwindigkeit geeignet. Bei Rückkopplungen im Klimasystem, in der Quantenphysik oder bei der Entwicklung des Auges versagt sie regelmäßig, und die Wirklichkeit hat keine Pflicht, unserem Bauchgefühl zu entsprechen. Auch die Verwandlung einer Raupe in einen Schmetterling, bei der in der Puppe große Teile des Körpers abgebaut und neu aufgebaut werden, klingt unvorstellbar und ist trotzdem real. Die richtige Rückfrage trennt deshalb sauber zwischen dem eigenen Unglauben und der Frage, was für oder gegen die Behauptung spricht. Die anderen Rückfragen lenken ab: Sie zielen auf die Person, verlangen Gegenbeweise von der falschen Seite oder zählen Meinungen, statt den Schluss selbst zu prüfen.","coreRule":"⚡ Was ich mir nicht vorstellen kann, ist deshalb nicht unmöglich.","quote":"Ich kann es mir nicht vorstellen, also kann es nicht wahr sein.","quoteLabel":"Merksatz:","beleg":"Werkstück B.13 (Die unmögliche Raupe; Kernidee; Kontext & Tiefe; Anwendung & Relevanz)","status":"entwurf","kurz":"Dass sich die Kollegin etwas nicht vorstellen kann, zeigt nur, wo ihr Wissen endet, nicht, dass die Sache falsch ist. Intuition taugt für Alltägliches, versagt aber bei Klimarückkopplungen oder Quantenphysik regelmäßig.","prueffrage":"Welche Gründe nennt die Kollegin dafür, dass die Sache Unsinn ist?","rueckmeldung":[{"option":1,"text":"Nach der Quelle zu fragen, ist oft sinnvoll. Hier lenkt es aber ab: Die Kollegin setzt Unvorstellbarkeit mit Unwahrheit gleich, und daran ändert auch eine sehr glaubwürdige Quelle nichts. Zu prüfen ist der Schluss, nicht die Person."},{"option":2,"text":"Nach Belegen zu fragen, wirkt offen und fair. Die Kollegin hat aber selbst keinen Beleg gegen die Sache genannt, nur ihre fehlende Vorstellung davon. Gegenbeweise von anderen zu verlangen, lenkt vom Schluss ab, den es zu prüfen gilt."},{"option":3,"text":"Wenn viele etwas unplausibel finden, wirkt das wie ein Hinweis. Verbreiteter Unglaube sagt aber nur etwas über das Bauchgefühl der Leute, nicht über die Sache. Gerade bei Klimarückkopplungen versagt Intuition regelmäßig."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"},{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI „Organs of extreme perfection“ (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"},{"typ":"url","kurz":"Jabr, F. (2012): How Does a Caterpillar Turn into a Butterfly? Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/caterpillar-butterfly-metamorphosis-explainer/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-b1-046","clusterId":"B","werkstueckRef":"B.13","stufe":2,"question":"Warum ist die Intuition in diesem Fall ein schlechter Maßstab, obwohl dasselbe Bauchgefühl bei dubiosen Verkaufsangeboten gut schützt?","scenario":"Ein Kollege sagt über ein neues Medikament: „Wie soll ein winziger Wirkstoff den ganzen Körper beeinflussen? Das kann ich mir nicht vorstellen, also wirkt es nicht.“ Die Zulassungsstudien liegen offen vor, er hat sie nicht gelesen. Zu gut klingende Angebote kennst du selbst als Fall, in dem dich ein Bauchgefühl zu Recht zum genaueren Hinsehen bringt.","options":["Weil sie hier als letztes Wort dient und verhindert, dass er die vorliegenden Belege überhaupt prüft.","Weil Intuition grundsätzlich unzuverlässig ist und immer zuerst durch Fachleute ersetzt werden sollte.","Weil sein Bauchgefühl sich schon einmal geirrt hat und deshalb von nun an nichts mehr taugt.","Weil Bauchgefühle nur dann gelten, wenn möglichst viele andere Menschen dieselbe Einschätzung teilen."],"correctIndex":0,"explanation":"Ein Bauchgefühl ist ein brauchbarer erster Filter: Es lässt uns bei Angeboten, die zu gut klingen, genauer hinsehen und schützt so vor vielen Betrügereien. Zum Problem wird es, wenn es zur unanfechtbaren Endinstanz wird. „Ich kann mir das nicht vorstellen“ sagt etwas über die Grenzen der eigenen Vorstellungskraft und des eigenen Wissens, nicht über die Wirklichkeit. Die Intuition ist für Alltagssituationen mit mittleren Größen und Geschwindigkeiten geeicht, bei komplexen wissenschaftlichen Themen weit außerhalb der Alltagserfahrung führt sie in die Irre. Wer seine Intuition hier über die vorliegenden Studien stellt, schaltet die Prüfung der Belege ab, die sie herausfordern könnten. Die Intuition ist nicht grundsätzlich unzuverlässig, sondern nur als finale Urteilsinstanz problematisch.","coreRule":"⚡ Die Intuition darf den Anfang der Prüfung machen, aber nicht das letzte Wort haben.","beleg":"Werkstück B.13 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"„Das kann ich mir nicht vorstellen“ beschreibt die Grenzen der eigenen Vorstellungskraft, nicht die Wirklichkeit. Als erster Filter taugt das Gefühl, als letztes Wort verhindert es den Blick in die offen vorliegenden Studien.","prueffrage":"Wie oft konnte der Kollege sein Gefühl über Arzneiwirkungen schon an echten Ergebnissen überprüfen, verglichen mit deinem Gefühl bei Verkaufsangeboten?","rueckmeldung":[{"option":1,"text":"Dass Intuition bei komplexen Wissenschaftsthemen oft in die Irre führt, stimmt. Grundsätzlich unzuverlässig ist sie trotzdem nicht: Als erster Filter schützt sie vor vielen Betrügereien. Sie darf hier nur die Prüfung der Belege nicht ersetzen."},{"option":2,"text":"Von einem früheren Irrtum des Kollegen ist nichts bekannt, und selbst ein einzelner Irrtum würde ein Bauchgefühl nicht dauerhaft entwerten. Das Problem liegt darin, wie es hier verwendet wird: als Endurteil, ohne die Belege zu lesen."},{"option":3,"text":"Wie viele Menschen eine Einschätzung teilen, sagt noch nichts darüber, ob sie stimmt. Auch eine weit verbreitete Vorstellungsgrenze bleibt eine Grenze. Maßstab ist, ob sich das Gefühl an den vorliegenden Belegen bewährt."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"},{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-b1-047","clusterId":"B","werkstueckRef":"B.13","stufe":4,"question":"Was ist an dieser Aussage als Argument gegen die Evolution des Auges ihr eigentliches Problem?","scenario":"Jemand sagt: „Ich kann mir einfach nicht vorstellen, wie sich aus zufälligen Mutationen und natürlicher Selektion etwas so Komplexes wie ein menschliches Auge entwickeln konnte. Das ist doch unmöglich!“","options":["Sie hält die Komplexität des Auges für einen Hinweis auf Planung und verlangt, dass Gegenbeweise die unbekannten Zwischenschritte erst lückenlos belegen.","Sie macht die Grenze der eigenen Vorstellungskraft zum Maßstab für die Wirklichkeit, obwohl daraus nichts über die Entstehung des Auges folgt.","Sie verlangt zu Recht, dass ein Auge erst Schritt für Schritt im Labor entstehen muss, bevor man den Einwand entkräften kann.","Sie zeigt die Vorsicht, die jede Wissenschaft braucht, und kann deshalb in keinem Fall ein Denkfehler sein."],"correctIndex":1,"explanation":"Der Satz „Ich kann mir nicht vorstellen, wie …“ beschreibt nur, was in einem Kopf möglich ist, nicht was in der Natur möglich ist. Aus fehlender Vorstellungskraft folgt nichts über die Wirklichkeit: Vieles, was sich als wahr herausgestellt hat, widerspricht der Alltagsintuition, etwa dass Uhren in schneller Bewegung langsamer gehen oder dass riesige Kontinente langsam über den Globus driften. Der Einwand ist also kein Argument, sondern ein Bekenntnis zur eigenen Wissenslücke, etwa über die kleinen Zwischenschritte, in denen komplexe Strukturen entstehen können. Hilfreich ist die Frage, ob der Mangel an Vorstellungskraft ein Beweis gegen die Behauptung oder nur ein Beweis für die Grenzen des eigenen Wissens ist. Die anderen Antworten drehen die Beweislast um, verlangen ein unmögliches Experiment oder erklären jede Zurückhaltung für unangreifbar.","coreRule":"⚡ Wenn du es dir nicht vorstellen kannst, such eine Erklärung oder Analogie, statt es abzulehnen.","beleg":"Werkstück B.13 (Kontext & Tiefe; Anwendung & Relevanz: Bei der Evolutionstheorie; Das Anti-Denkmuster)","status":"entwurf","kurz":"Aus „Ich kann es mir nicht vorstellen“ folgt nichts über die Natur: Der Satz beschreibt nur die Grenze des eigenen Wissens, etwa über kleine Zwischenschritte. Der Fehler liegt darin, diese Grenze als Beweis zu behandeln, obwohl vieles Wahre der Intuition widerspricht.","prueffrage":"Welche einfacheren Augen gibt es heute bei anderen Tieren, und was zeigen sie über mögliche Zwischenstufen?","rueckmeldung":[{"option":0,"text":"Komplexität wirkt wie ein Hinweis auf Planung, doch komplexe Strukturen können auch aus vielen kleinen Schritten entstehen. Außerdem muss nicht die Gegenseite jede Lücke schließen: Wer „unmöglich“ behauptet, muss das selbst stützen."},{"option":2,"text":"Belege zu verlangen ist grundsätzlich berechtigt. Ein im Labor entstehendes Auge wäre aber ein unmögliches Experiment, weil solche Entwicklungen enorme Zeiträume brauchen. Dass man den Einwand so nicht widerlegen kann, macht ihn nicht zum Argument."},{"option":3,"text":"Vorsicht gehört zur Wissenschaft, und Zweifel sind oft nützlich. Hier wird aber aus „Ich kann es mir nicht vorstellen“ ein „Das ist unmöglich“. Das geht über Vorsicht hinaus, und auch Zurückhaltung schützt nicht vor einem fehlerhaften Schluss."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI „Organs of extreme perfection“ (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"},{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-b1-048","clusterId":"B","werkstueckRef":"B.14","stufe":1,"question":"Welcher Denkfehler steckt in dem Satz „Das ist rein natürlich, die Natur weiß am besten, was gut für uns ist“?","scenario":"In der Drogerie rät dir jemand zu einem pflanzlichen Erkältungsmittel: „Das ist rein natürlich, ohne all die aggressive Chemie. Die Natur weiß am besten, was gut für uns ist.“","options":["Er unterstellt, dass natürliche Stoffe grundsätzlich schwächer wirken als synthetische.","Er übersieht, dass die Mehrheit der Menschen synthetische Produkte bevorzugt.","Er wird behauptet, ohne dass die Person eine einschlägige Fachausbildung nachweist.","Er schließt von der Herkunft eines Stoffs auf dessen Sicherheit und Wirkung."],"correctIndex":3,"explanation":"Der Satz setzt „natürlich“ mit „gut, sicher, überlegen“ gleich. Das ist ein Fehlschluss, denn die Herkunft eines Stoffs sagt nichts über Sicherheit oder Wirkung. Die Natur ist gleichgültig gegenüber unserem Wohlbefinden: Sie bringt Heilendes hervor, aber auch Tödliches wie Botulinumtoxin, Schlangengift oder Knollenblätterpilze. Ob ein Mittel hilft oder schadet, zeigen Reinheit, Dosierbarkeit und getestete Wirkung. Der Fehler liegt also nicht in einer angeblichen Schwäche natürlicher Stoffe, sondern darin, dass von der Herkunft auf Sicherheit und Wirkung geschlossen wird. Auch Beliebtheit oder die Qualifikation der sprechenden Person ändern daran nichts: Der Satz bewertet einen Stoff nach seiner Herkunft statt nach geprüfter Evidenz.","coreRule":"⚡ „Natürlich“ ist ein Herkunftsetikett, kein Gütesiegel.","beleg":"Werkstück B.14 (Das Gespräch in der Drogerie; Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Aus „natürlich“ folgt weder Sicherheit noch Wirkung: Die Natur bringt Heilendes und Tödliches hervor. Der Denkfehler ist, die Herkunft eines Stoffs mit seiner Qualität gleichzusetzen, statt auf geprüfte Wirkung und Dosierung zu schauen.","prueffrage":"Was steht auf der Packung über die Menge der Inhaltsstoffe und über Studien zur Wirkung?","rueckmeldung":[{"option":0,"text":"Der Satz behauptet gerade eine Überlegenheit natürlicher Stoffe, keine Schwäche. Auch die Gegenrichtung wäre derselbe Fehler: Die Herkunft sagt nichts über die Stärke der Wirkung, weder nach oben noch nach unten."},{"option":1,"text":"Wie viele Menschen etwas bevorzugen, sagt nichts darüber, ob ein Stoff sicher ist oder wirkt. Im Satz kommt Beliebtheit auch gar nicht vor; er bewertet einen Stoff allein nach seiner Herkunft."},{"option":2,"text":"Dass keine Fachausbildung genannt wird, macht misstrauisch, widerlegt aber nichts: Auch mit Ausbildung bliebe der Schluss von „natürlich“ auf „gut“ unbegründet. Der Fehler steckt im Schluss selbst, nicht in der Person."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO: Botulism. Fact sheet","oeffentlich":true,"url":"https://www.who.int/news-room/fact-sheets/detail/botulism","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-b1-049","clusterId":"B","werkstueckRef":"B.14","stufe":2,"question":"Was spricht an dieser Argumentation am ehesten gegen den Schluss, der Rindenextrakt sei dem Laborprodukt überlegen?","options":["Die Rinde enthält viele weitere Substanzen, und ihr Wirkstoffgehalt schwankt je nach Baum und Jahreszeit. Die Herkunft sagt also nichts über Reinheit und Dosis aus.","Laborstoffe verlieren im Herstellungsprozess ihre natürliche Schwäche und wirken deshalb stärker. Das Künstliche ist also grundsätzlich im Vorteil.","Die Rinde enthält einen Wirkstoff, der mit dem der Tablette nichts zu tun hat, und beide Mittel lassen sich gar nicht vergleichen. Die Herkunft ist darum nebensächlich.","Alles Künstliche wird vor der Zulassung geprüft, alles Natürliche bleibt grundsätzlich ungeprüft. Die Herkunft entscheidet also über das Risiko."],"correctIndex":0,"explanation":"Die Freundin schließt von der Herkunft auf die Qualität. Das ist ein Fehlschluss, denn entscheidend sind Reinheit, Dosierbarkeit und geprüfte Wirkung. Weidenrinde enthält neben dem Vorläuferstoff Salicin hunderte andere Substanzen, von denen manche die Wirkung abschwächen oder Nebenwirkungen haben können. Außerdem schwankt der Wirkstoffgehalt je nach Baum, Jahreszeit und Standort, sodass sich kaum genau dosieren lässt. Eine Aspirin-Tablette enthält dagegen eine festgelegte Menge reiner Acetylsalicylsäure, deren Vorläufer in der Weidenrinde vorkommt. Das macht Synthetisches nicht automatisch besser, es zeigt nur, dass „natürlich“ kein Qualitätsmerkmal ist. Von den anderen Antworten ersetzt eine den Fehlschluss durch sein Spiegelbild („künstlich = besser“). Eine weitere bestreitet jede Verwandtschaft der Stoffe, dabei ist Aspirin eine Weiterentwicklung des Rindenstoffs. Die letzte macht erneut die Herkunft zum Maßstab für das Risiko.","coreRule":"⚡ Die Herkunft eines Stoffes sagt nichts über seine Qualität. Reinheit, Dosis und getestete Wirkung entscheiden.","beleg":"Werkstück B.14 (Kontext & Tiefe: Der entscheidende Vorteil des „Künstlichen“)","status":"entwurf","scenario":"Eine Freundin hat Kopfschmerzen und will keine Tabletten nehmen. Sie sagt: „Ich nehme lieber Weidenrinden-Extrakt statt Aspirin. Der Wirkstoff kommt ja ursprünglich aus der Rinde, also ist das Original natürlich besser als die Kopie aus dem Labor.“","kurz":"Aus der natürlichen Herkunft folgt nichts über die Qualität: Die Rinde enthält viele weitere Substanzen, und ihr Wirkstoffgehalt schwankt je nach Baum und Jahreszeit. Entscheidend sind Reinheit und Dosis, nicht, woher ein Stoff stammt.","prueffrage":"In welcher Beziehung steht der Wirkstoff der Weidenrinde zu dem der Aspirin-Tablette?","rueckmeldung":[{"option":1,"text":"Dass sich Wirkstoffe im Labor rein und genau dosiert herstellen lassen, ist ein echter Vorzug. Daraus folgt aber nicht, dass Künstliches grundsätzlich stärker wirkt; das ist nur die Umkehrung des Herkunftsschlusses mit einer unbelegten Begründung."},{"option":2,"text":"Unverwandt sind die Stoffe nicht: Die Rinde enthält Salicin, den Vorläufer, aus dem Aspirin weiterentwickelt wurde. Vergleichen lassen sich beide also durchaus; entscheidend sind Reinheit und Dosis, nicht die Herkunft."},{"option":3,"text":"Eine Zulassungsprüfung ist ein echtes Argument, die Pauschale aber nicht: Auch pflanzliche Arzneimittel brauchen eine Zulassung oder Registrierung, und nicht alles Künstliche wird geprüft. Zudem wird wieder die Herkunft zum Risikomaßstab."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Vlachojannis, J.; Magora, F.; Chrubasik, S. (2011): Willow species and aspirin: different mechanism of actions. Phytotherapy Research 25(7), 1102–1104 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/21226125/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vlachojannis u. a. (2011), Verlagsfassung","oeffentlich":false,"doi":"10.1002/ptr.3386"}],"thema":"Gesundheit"},{"id":"qx-b1-050","clusterId":"B","werkstueckRef":"B.14","stufe":3,"question":"Eine Bekannte erzählt dir, sie esse am liebsten unverarbeitete Lebensmittel, gehe oft in den Wald und setze bei leichten Erkältungen auf Kräutertee. Ihr Bruder lehnt dagegen die vom Arzt empfohlene Behandlung seiner Erkrankung ab und nimmt stattdessen nur noch „rein natürliche“ Präparate, weil „die Natur am besten weiß, was gut für uns ist“. Woran erkennst du, dass beim Bruder der Appell an die Natur zum gefährlichen Fehlschluss wird?","options":["Er ersetzt eine geprüft wirksame und sichere Behandlung durch Alternativen, deren Wirkung und Dosierung ungeprüft sind, und riskiert dadurch schwere Folgen.","Er achtet bei seiner Behandlung überhaupt auf die Herkunft der Mittel, und schon dieses Interesse an Natürlichem macht seine Entscheidung gefährlich.","Er verbringt viel Zeit mit Naturprodukten und hat dadurch weniger Zeit, sich mit Studien und Fachliteratur auseinanderzusetzen.","Er glaubt an die Heilkraft der Natur und steht damit im Widerspruch zu einer Wissenschaft, die ausschließlich auf Labor und Technik setzt."],"correctIndex":0,"explanation":"Eine Vorliebe für Natürliches ist für sich genommen harmlos und oft sogar gesund: Wer unverarbeitete Lebensmittel mag, im Wald spazieren geht oder bei einer leichten Erkältung Kräutertee trinkt, trifft keine riskante Entscheidung. Der Fehlschluss wird erst gefährlich, wenn er zu einer Entscheidung mit Folgen wird. Das ist der Fall, wenn eine nachweislich wirksame und sichere Behandlung durch Mittel ersetzt wird, deren Wirkung nie geprüft wurde und deren Dosis schwankt. Dann entscheidet die Herkunft über die Behandlung statt die belegte Wirkung. Ein Beispiel: Wer eine Chemotherapie zugunsten von Aprikosenkernen ablehnt, setzt sich einem Gift aus (sie enthalten Amygdalin, aus dem im Körper giftige Blausäure entstehen kann), statt die Krankheit zu behandeln. Die Herkunft sagt weder etwas über Sicherheit noch über Wirksamkeit. Die richtige Frage lautet immer: Was zeigen die besten Belege über Sicherheit, Reinheit, Dosierbarkeit und Wirksamkeit genau dieses Mittels?","coreRule":"⚡ Natürliche Vorlieben sind harmlos – gefährlich wird erst der Ersatz geprüfter Lösungen durch ungeprüfte.","beleg":"Werkstück B.14 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Gefährlich wird der Appell an die Natur erst, wenn eine geprüft wirksame, sichere Behandlung durch Mittel ersetzt wird, deren Wirkung und Dosis ungeprüft sind. Dann entscheidet die Herkunft statt der belegten Wirkung, und die Krankheit bleibt womöglich unbehandelt.","prueffrage":"Bei welchen Beschwerden setzt die Bekannte auf Natürliches, und bei welchen ihr Bruder?","rueckmeldung":[{"option":1,"text":"Dass er auf Natürlichkeit setzt, fällt tatsächlich auf. Doch auf die Herkunft zu achten ist für sich harmlos, wie der Kräutertee der Bekannten zeigt. Riskant wird es erst, wenn dadurch eine wirksame Behandlung wegfällt."},{"option":2,"text":"Wie viel Zeit jemand mit Naturprodukten verbringt, sagt nichts über die Qualität seiner Entscheidung, und von fehlender Lesezeit ist nirgends die Rede. Das Risiko entsteht, weil eine wirksame Behandlung durch ungeprüfte Mittel ersetzt wird."},{"option":3,"text":"Auch Naturstoffe können wirken, und Wissenschaft setzt nicht ausschließlich auf Labor und Technik. Nicht der Glaube an die Natur ist das Problem, sondern dass Mittel ohne belegte Wirkung eine geprüfte Behandlung ersetzen."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Milazzo, S.; Horneber, M. (2015): Laetrile treatment for cancer. Cochrane Database of Systematic Reviews, CD005476 (Volltext frei in PMC6513327)","oeffentlich":true,"doi":"10.1002/14651858.CD005476.pub4","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-b1-051","clusterId":"B","werkstueckRef":"B.14","stufe":4,"question":"Wie ist diese Behauptung am treffendsten zu beurteilen?","scenario":"Ein Verkäufer behauptet: „Dieser Stoff aus der Pflanze ist dem im Labor hergestellten überlegen, obwohl beide chemisch exakt identisch sind. Denn der natürliche trägt eine Lebenskraft in sich.“","options":["Sie ist nachvollziehbar, weil Stoffe aus Pflanzen immer Begleitstoffe und Wechselwirkungen mitbringen, die sie von künstlich hergestellten unterscheiden.","Sie ist eine berechtigte Vorsicht, weil im Labor hergestellte Moleküle im Körper grundsätzlich anders wirken als pflanzliche, selbst bei identischer Struktur.","Sie ist eine harmlose Marketing-Übertreibung, weil sie unproblematisch bleibt, solange das Produkt keine verbotenen Stoffe enthält.","Sie ist eine unbelegte Zusatzannahme, weil bei identischen Molekülen kein Unterschied gezeigt wird und Wirkung und Sicherheit durch Tests geprüft werden müssen."],"correctIndex":3,"explanation":"Die Behauptung gibt zu, dass beide Stoffe chemisch identisch sind, und setzt dann einen Vorteil des „natürlichen“ obendrauf, die „Lebenskraft“. Diese behauptete Überlegenheit ist unbewiesen, und sie lässt sich auch nicht an den Molekülen festmachen, die ja gleich sind. Die Herkunft sagt weder etwas über Wirksamkeit noch über Sicherheit: Der Knollenblätterpilz ist ebenso natürlich wie Arsen. Was zählt, sind Reinheit, Dosierbarkeit, Wirksamkeit und Sicherheit, und die muss man durch Tests belegen. Dass keine verbotenen Stoffe enthalten sind, belegt die Werbeaussage nicht, denn eine unbelegte Behauptung ist keine harmlose Übertreibung. Auch Begleitstoffe sind kein Pluspunkt an sich: Wie bei der Weidenrinde, die hunderte Substanzen enthält, können sie die Wirkung abschwächen oder unerwünschte Nebenwirkungen haben, und die Dosierung schwankt.","coreRule":"⚡ Bei identischen Molekülen bleibt „Lebenskraft“ eine Behauptung, kein Befund.","beleg":"Werkstück B.14 (Anwendung & Relevanz: In der Pseudomedizin & Wellness-Industrie; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wenn beide Stoffe chemisch identisch sind, bleibt für die „Lebenskraft“ nichts Messbares übrig. Der Fehler: „natürlich“ klingt nach „besser“, sagt aber weder etwas über Wirkung noch Sicherheit. Das zeigen erst Tests.","prueffrage":"Welcher messbare Unterschied zwischen den beiden Stoffen wird in der Aussage tatsächlich genannt?","rueckmeldung":[{"option":0,"text":"Pflanzenextrakte enthalten oft Begleitstoffe. Der Verkäufer spricht aber vom Stoff selbst, und der ist laut ihm identisch. Zudem sind Begleitstoffe kein Vorteil an sich: Sie können die Wirkung abschwächen oder Nebenwirkungen haben."},{"option":1,"text":"Dass die Herkunft einen Unterschied macht, klingt plausibel. Identische Moleküle wirken im Körper aber gleich, gleich woher sie stammen. Ein Unterschied wäre erst dann ein Argument, wenn er gezeigt würde, und das geschieht hier nicht."},{"option":2,"text":"Dass keine verbotenen Stoffe enthalten sind, beruhigt, belegt die Werbeaussage aber nicht: Eine unbelegte Behauptung über einen Vorteil ist keine harmlose Übertreibung, und Wirksamkeit und Sicherheit müssen geprüft werden."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO: Botulism. Fact sheet","oeffentlich":true,"url":"https://www.who.int/news-room/fact-sheets/detail/botulism","abruf":"2026-10-12"},{"typ":"url","kurz":"Vlachojannis, J.; Magora, F.; Chrubasik, S. (2011): Willow species and aspirin: different mechanism of actions. Phytotherapy Research 25(7), 1102–1104 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/21226125/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-b1-052","clusterId":"B","werkstueckRef":"B.15","stufe":1,"question":"Was ist an diesem Schluss fehlerhaft, und welche Information würde ihn am ehesten prüfen?","scenario":"In einem Ratgeber-Artikel steht: „Zwei bekannte Tech-Gründer haben ihr Studium abgebrochen und sind Milliardäre geworden. Also ist ein Studienabbruch ein guter Weg zum Erfolg.“","options":["Der Schluss stützt sich nur auf die Erfolgreichen; entscheidend wäre, wie es allen ergangen ist, die ihr Studium abgebrochen haben.","Der Schluss stützt sich auf zu wenige Beispiele; mit zehn weiteren erfolgreichen Abbrechern wäre er dann gesichert.","Der Schluss übersieht die Begabung der Gründer; entscheidend wären ihre Noten vor dem Abbruch.","Der Schluss übersieht andere Milliardäre; entscheidend wäre, ob die meisten von ihnen einen Abschluss haben."],"correctIndex":0,"explanation":"Hier werden nur diejenigen betrachtet, die einen Auswahlprozess erfolgreich durchlaufen haben. Die vielen Menschen, die ebenfalls abgebrochen haben und gescheitert sind, tauchen in keiner Erfolgsgeschichte auf, wären für den Schluss aber entscheidend. Erst der Vergleich zeigt, ob Abbrechen die Erfolgschance erhöht oder ob Glück, Timing und andere Faktoren die Hauptrolle spielen. Auch zehn weitere Erfolgsfälle würden die Verzerrung nicht beheben, denn sie stammen aus derselben gefilterten Gruppe. Ähnlich ist es bei Gewohnheiten wie „früh aufstehen“: Auch viele Gescheiterte können sie gehabt haben.","coreRule":"⚡ Wenn nur Gewinner gezeigt werden, frag nach denen, die dasselbe getan haben und trotzdem gescheitert sind.","beleg":"Werkstück B.15 (Kernidee; Anwendung & Relevanz: In der Business- & Self-Help-Industrie)","status":"entwurf","kurz":"Wer nur die Erfolgreichen betrachtet, sieht die vielen Gescheiterten nicht, die ebenfalls abgebrochen haben. Erst der Vergleich mit allen Abbrechern zeigt, ob der Abbruch die Chance erhöht oder ob Glück und Timing den Ausschlag geben.","prueffrage":"Woher kennt der Artikel gerade diese zwei Gründer, und warum wird über sie überhaupt geschrieben?","rueckmeldung":[{"option":1,"text":"Zwei Beispiele sind tatsächlich wenig. Mehr Fälle aus derselben Erfolgsgruppe würden den Schluss aber nicht sichern, denn die Auswahl bliebe verzerrt: Die Gescheiterten fehlen weiterhin."},{"option":2,"text":"Begabung kann mitspielen, ebenso Glück und Timing. Die Noten der beiden Gründer sagen aber nichts darüber, wie es den vielen anderen Abbrechern ging, und genau dieser Vergleich fehlt dem Schluss."},{"option":3,"text":"Ein Vergleich ist der richtige Impuls. Hier bleibt er aber bei den Erfolgreichen und sagt nichts über die Gescheiterten: Selbst wenn die meisten Milliardäre einen Abschluss haben, wäre unklar, wie hoch die Erfolgschance unter allen Abbrechern ist."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-053","clusterId":"B","werkstueckRef":"B.15","stufe":2,"question":"Welche Frage prüft die Schlussfolgerung des Lesers am besten?","scenario":"In einer Zeitung wird ein Medium gefeiert, weil es ein Ereignis angeblich korrekt vorhergesagt hat. Berichtet wird nur über diese eine Vorhersage. Ein Leser schreibt: „Das kann kein Zufall sein, das Medium hat offenbar echte Fähigkeiten.“","options":["Wie überzeugend und selbstsicher hat das Medium die Vorhersage damals vorgetragen?","Wie viele andere Vorhersagen dieses und anderer Medien lagen daneben und wurden nie erwähnt?","Wie viele Menschen haben von der Vorhersage erfahren und wie breit wurde darüber berichtet?","Wie lange vor dem Ereignis wurde die Vorhersage veröffentlicht und wer hat sie bestätigt?"],"correctIndex":1,"explanation":"Bei diesem Medium hörst Du nichts von den tausenden Vorhersagen desselben Mediums (und aller anderen), die komplett danebenlagen. Die Treffer überleben in der öffentlichen Erinnerung, die Fehlschüsse verschwinden. Der eine berichtete Treffer ist also eine nach Erfolg gefilterte Auswahl. Ob er etwas über echte Fähigkeiten aussagt, lässt sich erst beurteilen, wenn Du auch die verfehlten Vorhersagen kennst. Wie selbstsicher das Medium auftrat, wie weit die Meldung verbreitet wurde und wann sie erschien, sagt nichts darüber, welche Versuche sichtbar geworden sind und welche nicht. Diese Angaben lassen offen, wie viele Fehlschüsse im Verborgenen blieben.","coreRule":"⚡ Zeig mir nicht nur die Treffer, sondern alle Versuche.","quote":"Aber wo ist der Friedhof? Welche unsichtbaren Daten der Gescheiterten fehlen in diesem Bild?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.15 (Anwendung & Relevanz: In der Esoterik; Das Anti-Denkmuster)","status":"entwurf","kurz":"Ein einzelner berichteter Treffer sagt wenig, solange man die vielen verfehlten Vorhersagen nicht kennt. Sichtbar wird, was eintraf; das Danebenliegende verschwindet. Erst mit den Fehlschüssen lässt sich beurteilen, ob echte Fähigkeiten im Spiel sind.","prueffrage":"Warum berichtet die Zeitung gerade über diese Vorhersage, und worüber hätte sie geschrieben, wenn sie nicht eingetroffen wäre?","rueckmeldung":[{"option":0,"text":"Ein sicherer Auftritt hinterlässt Eindruck und wirkt wie Kompetenz. Er sagt aber nichts darüber, wie oft das Medium insgesamt richtiglag oder welche Versuche gar nicht erst bekannt wurden."},{"option":2,"text":"Wie weit die Meldung kam, zeigt, wie bekannt der Treffer wurde, nicht ob er typisch ist. Eine große Verbreitung kann sogar dazu beitragen, dass nur der Treffer in Erinnerung bleibt und die Fehlschüsse untergehen."},{"option":3,"text":"Wann die Vorhersage erschien und wer sie bestätigte, ist durchaus wichtig, wenn es um die Echtheit dieses Einzelfalls geht. Es klärt aber nicht, wie viele andere Vorhersagen danebenlagen und unbemerkt blieben."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Selective Attention“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-b1-054","clusterId":"B","werkstueckRef":"B.15","stufe":3,"question":"Du liest in einem Wirtschaftsmagazin, wie ein Mathematiker im Zweiten Weltkrieg den Generälen mit einem einzigen Satz widerspricht: „Meine Herren, Sie liegen komplett falsch.“ Wie gehst du mit der Szene um?","options":["Ich halte den Kerngedanken für prüfbar, die wörtliche Szene aber für ungesichert, weil anschauliche Details ohne Quelle leicht dazugedichtet sind.","Ich halte die Szene für unglaubwürdig, weil ein Artikel ohne Quellenangabe niemals etwas Verlässliches enthalten kann.","Ich halte die Szene für wahr, weil so viele Details genannt werden und eine erfundene Geschichte kaum so genau ausfallen würde.","Ich halte die Szene für belegt, weil sie in vielen Artikeln und Vorträgen in fast gleicher Form erzählt wird und viele Autoren sich kaum täuschen."],"correctIndex":0,"explanation":"Anschauliche Details wie wörtliche Dialoge sind kein Beleg, sondern oft das Ergebnis dramatisierenden Nacherzählens. Real ist Walds Arbeit für die Statistical Research Group der Columbia University, für die er 1943 Memoranden verfasste, die aus den Treffern zurückgekehrter Flugzeuge die Verwundbarkeit einzelner Flugzeugteile schätzen. Eine ausdrückliche Empfehlung, wo gepanzert werden soll, enthalten sie nicht, und der Dialog selbst ist nicht dokumentiert. Auch die Rahmung vom einsamen Außenseiter greift zu kurz, denn das US-Militär wertete Kampfschäden bereits systematisch aus. Die vernünftige Haltung trennt also zwischen dem prüfbaren Kern (der Idee der Auswahlverzerrung: Die Daten der Zurückgekehrten verzerren das Bild) und der ungesicherten Ausschmückung. Pauschale Ablehnung ist daher ebenso wenig begründet wie blindes Vertrauen. Dass eine Geschichte oft wiederholt wird, belegt nur ihre Verbreitung, nicht ihre Wahrheit.","coreRule":"⚡ Eine gute Lehrgeschichte ist noch keine Quelle – prüfe, was davon belegt ist.","beleg":"Werkstück B.15 (Die unsichtbaren Einschusslöcher); Fn. gl-b-wald (Mangel/Samaniego 1984, JASA 79(386), S. 259–267)","status":"entwurf","scenario":"Der Artikel erzählt eine mitreißende Geschichte über Abraham Wald und die Panzerung von Bombern. Wörtliche Dialoge, genaue Trefferverteilungen und ein einsamer Held, der die ahnungslosen Militärs belehrt, machen die Erzählung sehr anschaulich. Eine Quelle für diese Details nennt der Artikel nicht.","kurz":"Der Kern, dass die Daten zurückgekehrter Flugzeuge das Bild verzerren, lässt sich an Walds dokumentierter Arbeit prüfen. Der wörtliche Dialog ist nicht belegt, und anschauliche Details sind oft Ausschmückung, kein Beweis.","prueffrage":"Woher könnte ein Magazin heute den genauen Wortlaut eines Satzes kennen, der vor über 80 Jahren in einer Besprechung gefallen sein soll?","rueckmeldung":[{"option":1,"text":"Eine fehlende Quelle ist für die wörtliche Szene tatsächlich ein Warnzeichen. „Niemals etwas Verlässliches“ geht aber zu weit: Walds reale Arbeit und der Gedanke der Auswahlverzerrung bleiben prüfbar, auch wenn der Artikel sie schlecht belegt."},{"option":2,"text":"Viele genaue Einzelheiten wirken wie Zeugenschaft, kosten beim Erzählen aber nichts. Wörtliche Dialoge und exakte Trefferverteilungen ohne Quelle sind typisch für dramatisierendes Nacherzählen und belegen nicht, dass die Szene so stattfand."},{"option":3,"text":"Die weite Verbreitung wirkt wie eine Bestätigung durch viele Stimmen. Wiederholung zeigt aber nur, dass die Geschichte gut erzählbar ist: Viele Autoren können voneinander übernehmen, und der Dialog bleibt dokumentarisch ungesichert."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"doi","kurz":"Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. Journal of the American Statistical Association 79(386), 259–267","oeffentlich":false,"doi":"10.1080/01621459.1984.10478038"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-055","clusterId":"B","werkstueckRef":"B.15","stufe":4,"question":"Welche Frage prüft die Behauptung des Architekten am besten?","scenario":"Ein Architekt behauptet: „Früher hat man besser gebaut. Sieh dir die alten Häuser an, die noch heute stehen!“","options":["Wie viele der damals gebauten Häuser sind inzwischen abgerissen oder eingestürzt?","Wie viele der heute noch stehenden Häuser sind besonders schön und gepflegt?","Wie viele Architekten vertreten heute dieselbe Ansicht über alte Gebäude?","Wie viele der früher üblichen Baustoffe werden heute noch verwendet?"],"correctIndex":0,"explanation":"Die Behauptung stützt sich nur auf Gebäude, die einen langen Auswahlprozess überstanden haben: Was baufällig war, wurde abgerissen, umgebaut oder ist eingestürzt. Dass die übrig gebliebenen Häuser solide sind, folgt daraus fast zwangsläufig und sagt wenig über die Bauweise einer ganzen Epoche. Erst der Blick auf die verschwundenen Häuser zeigt, ob früher tatsächlich besser gebaut wurde. Fragen nach Schönheit, nach der Zahl der Zustimmenden oder nach den verwendeten Baustoffen lassen dieses Selektionsproblem unberührt und könnten die Behauptung weder stützen noch widerlegen.","coreRule":"⚡ Was heute noch steht, ist eine Auswahl – nicht die Gesamtheit dessen, was einmal gebaut wurde.","beleg":"Werkstück B.15 (Red Flags; Anwendung & Relevanz)","status":"entwurf","kurz":"Aussagekräftig wäre, wie viele der damals gebauten Häuser inzwischen verschwunden sind. Wer nur die Überlebenden betrachtet, sieht fast zwangsläufig solide Bauten, denn Baufälliges wurde längst abgerissen oder ist eingestürzt.","prueffrage":"Wer hat im Lauf der Zeit entschieden, welche Häuser stehen bleiben, und nach welchen Gesichtspunkten?","rueckmeldung":[{"option":1,"text":"Schöne, gepflegte Häuser bleiben eher erhalten und fallen sofort ins Auge. Doch auch hier zählen nur die Überlebenden. Ob früher besser gebaut wurde, sagt das nicht, und die verschwundenen Häuser bleiben außen vor."},{"option":2,"text":"Eine verbreitete Ansicht unter Fachleuten wirkt wie ein Hinweis. Wie viele ihr zustimmen, sagt aber nichts über die Bauqualität damals. Ein Stimmungsbild ersetzt keinen Blick auf die Häuser selbst."},{"option":3,"text":"Baustoffe berühren die Sache durchaus, denn Material beeinflusst die Haltbarkeit. Ob ein Stoff heute noch verwendet wird, hängt aber auch von Kosten, Normen und Mode ab. Vor allem erfährst du nicht, wie viele Häuser damit gescheitert sind."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-056","clusterId":"B","werkstueckRef":"B.16","stufe":1,"question":"Was passiert sprachlich, wenn Menschen im Netz als „Bots“ oder „NPCs“ abgetan werden, und was ist daran problematisch?","options":["Die Menschen werden mit ekelerregenden Tieren verglichen und damit auf Instinkte reduziert, sodass Ausgrenzung leichter fällt.","Die Menschen werden als gefühllose Automaten ohne eigenes Denken dargestellt, sodass ihre Gründe nicht mehr geprüft werden müssen.","Die Menschen werden als Vertreter einer verhassten Ideologie angesehen, sodass sie nur noch als Teil einer Gruppe gelten.","Die Menschen werden als besonders gefährlich und mächtig dargestellt, sodass Misstrauen gegen sie gerechtfertigt erscheint."],"correctIndex":1,"explanation":"Wer Menschen als „NPCs“ oder „Bots“ bezeichnet, stellt sie als kalte, gefühllose Automaten dar und beraubt sie damit ihrer Wärme, Individualität und Empathie. Das ist die mechanistische Form der Entmenschlichung: Sie werden wie seelenlose Instrumente behandelt, die nur Skripte abspielen. Die Folge: Wer ein Gegenüber so einordnet, hat keinen Anlass mehr, dessen Gründe ernst zu nehmen, denn bei einem Automaten gibt es keine eigenen Gründe. Ein Tiervergleich wäre dagegen die animalische Form, die Menschen auf primitive, instinktgetriebene Kreaturen reduziert und Ekel, Angst oder Verachtung hervorruft. Die Gruppenabwertung durch Etiketten macht Menschen zu bloßen Repräsentanten einer verhassten Ideologie, nimmt ihnen aber nicht die Eigenschaft, denkende Wesen zu sein. Der Gefährlichkeitsvorwurf setzt sogar voraus, dass sie handlungsfähig sind. Entscheidend ist also, ob dem Gegenüber das eigene Denken und Fühlen abgesprochen wird oder ob nur seine Position kritisiert wird. Die Kritik an einer Position ist legitim, die Aberkennung des Menschseins ist es nicht.","coreRule":"⚡ Wer anderen das eigene Denken und Fühlen abspricht, muss ihre Gründe nicht mehr prüfen.","beleg":"Werkstück B.16 (Kontext & Tiefe: Zwei Mechanismen; Anwendung & Relevanz: In der politischen Propaganda)","status":"entwurf","scenario":"In einem Kommentarbereich schreibt jemand unter eine Diskussion: „Mit denen brauchst du gar nicht zu reden. Das sind doch alles NPCs, die immer dieselben Sätze runterbeten.“ Die Angesprochenen sind echte Menschen mit eigenen Gründen für ihre Meinung.","kurz":"Wer Menschen „NPCs“ nennt, stellt sie als Automaten dar, die nur Skripte abspielen. Dann gibt es scheinbar keine eigenen Gründe mehr, die man prüfen müsste. Der Fehler: Statt die Position zu kritisieren, wird dem Gegenüber das Denken abgesprochen.","prueffrage":"Worauf bezieht sich die Aussage: auf das, was die Leute vorbringen, oder auf die Leute selbst?","rueckmeldung":[{"option":0,"text":"Entmenschlichung erleichtert Ausgrenzung tatsächlich, und Tiervergleiche sind eine bekannte Form davon. Hier fällt aber kein Tiervergleich: Die Menschen gelten als seelenlose Skriptabspieler, nicht als instinktgetriebene Kreaturen."},{"option":2,"text":"Gruppenetiketten reduzieren Menschen oft auf Vertreter einer Ideologie. Im Satz wird aber keine Ideologie genannt, und die Leute gelten nicht als Überzeugte, sondern als gar nicht denkend. Genau darin liegt der Unterschied."},{"option":3,"text":"Misstrauen lässt sich leicht mit einer Bedrohung begründen. Der Satz stellt die Menschen aber gerade nicht als handlungsfähig dar, sondern als Leute, „die immer dieselben Sätze runterbeten“. Gefährlichkeit würde ihnen eigenes Handeln zugestehen."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Haslam, N. (2006): Dehumanization: An Integrative Review. Personality and Social Psychology Review 10(3), 252–264 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/16859440/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Haslam (2006), Verlagsfassung","oeffentlich":false,"doi":"10.1207/s15327957pspr1003_4"}],"thema":"Netz und Medien"},{"id":"qx-b1-057","clusterId":"B","werkstueckRef":"B.16","stufe":2,"question":"Ein Kommentator behauptet: „Der Völkermord in Ruanda 1994 ist allein den Hetzsendungen eines Radiosenders zuzuschreiben. Ohne dieses Radio wäre nichts passiert.“ Wie beurteilst du diese Behauptung am besten?","options":["Die Behauptung überschätzt das Radio: Hetzsprache kann Hemmungen senken und das Töten erleichtern, aber andere Faktoren wirkten daneben mit.","Die Behauptung stimmt, weil Menschen ohne Propaganda keinerlei Gewalt gegen ihre Nachbarn ausüben würden.","Die Behauptung ist falsch, weil Sprache grundsätzlich keinen Einfluss darauf hat, ob Menschen Gewalt anwenden.","Die Behauptung ist unerheblich, weil es bei Gewalt nur auf die Befehle von Behörden ankommt und nicht auf die Wortwahl."],"correctIndex":0,"explanation":"Die Behauptung macht aus einem Faktor die einzige Ursache. Wer Nachbarn monatelang als „Ungeziefer“ bezeichnet, löst moralische Hemmungen und macht das Töten sprachlich leichter. Zugleich gab es weitere Treiber: die Angst vor dem Krieg, Hetzblätter und die Mobilisierung durch Behörden und Bürgermeister. Ein Ereignis mit mehreren zusammenwirkenden Ursachen auf eine einzige zu verkürzen, ist ein typischer Denkfehler. Ebenso falsch wäre der Umkehrschluss, Sprache habe gar keine Wirkung: Beide Extreme ignorieren, dass Ursachen sich verstärken können.","coreRule":"⚡ Sprache kann Hemmungen lösen, erklärt aber nie allein die Tat.","beleg":"Werkstück B.16 (Die Kakerlaken im Radio); Fn. gl-b-rtlm (Human Rights Watch 1999, „Leave None to Tell the Story“)","status":"entwurf","scenario":"Der Sender sprach über die Tutsi nicht als Nachbarn, sondern über Monate hinweg als „Kakerlaken“ und „Ungeziefer“. Zur gleichen Zeit herrschten Angst vor dem Krieg, es kursierten Hetzblätter, und Behörden und Bürgermeister mobilisierten die Bevölkerung.","quote":"","quoteLabel":"","kurz":"Mehrere Faktoren wirkten zusammen: Die monatelange Entmenschlichung senkte Hemmungen, daneben standen Kriegsangst, Hetzblätter und die Mobilisierung durch Behörden. Der Fehler liegt darin, aus einem Faktor die Alleinursache zu machen.","prueffrage":"Welche anderen Umstände gab es zur gleichen Zeit, und was hätten sie allein bewirken können?","rueckmeldung":[{"option":1,"text":"Dass Propaganda Gewalt erleichtern kann, ist richtig. Wer aber behauptet, ohne sie gäbe es keinerlei Gewalt, macht sie wieder zur einzigen Ursache und ignoriert Kriegsangst, Hetzblätter und die Mobilisierung durch Behörden."},{"option":2,"text":"Dass ein einzelnes Radio nicht allein verantwortlich ist, stimmt. Daraus folgt aber nicht, dass Sprache gar nichts bewirkt: Wer Nachbarn monatelang als „Ungeziefer“ bezeichnet, kann Hemmungen senken und das Töten erleichtern."},{"option":3,"text":"Die Mobilisierung durch Behörden und Bürgermeister war tatsächlich ein wichtiger Faktor. Sie zur einzigen Ursache zu erklären, wiederholt aber den Fehler der Behauptung mit einer anderen Ursache und blendet die monatelange Entmenschlichung aus."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Human Rights Watch (1999): Leave None to Tell the Story: Genocide in Rwanda, Kap. „Propaganda and Practice“","oeffentlich":true,"url":"https://www.hrw.org/reports/1999/rwanda/Geno1-3-10.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b1-058","clusterId":"B","werkstueckRef":"B.16","stufe":3,"question":"Eine Politikerin sagt in einer Talkshow: „Menschen, die ihre Gegner als ‚Ungeziefer‘ bezeichnen, tun das, weil sie sie töten wollen, denn Entmenschlichung ist die Ursache jeder Gewalt.“ Was folgt aus diesen Befunden für ihre Behauptung?","options":["Sie wird bestätigt, denn bei Gewalt aus Nutzen ging Entmenschlichung tatsächlich mit mehr Gewaltbereitschaft einher.","Sie geht zu weit, denn bei Gewalt, die als gerecht empfunden wird, fehlte der Zusammenhang, und das widerlegt „jede Gewalt“.","Sie ist ganz widerlegt, denn Entmenschlichung spielt nach diesen Befunden bei Gewalt überhaupt keine Rolle.","Sie geht zu weit, denn Entmenschlichung hing in den Studien nur mit Gewalt gegen Tiere zusammen, nicht gegen Menschen."],"correctIndex":1,"explanation":"Die Behauptung verallgemeinert: Aus „Entmenschlichung kommt bei manchen Gewalttaten vor“ wird „sie erklärt jede Gewalt“. Gegen eine solche Allaussage genügt eine Gewaltart ohne den Zusammenhang, und die zeigte sich hier: Bei Gewalt, die als gerecht empfunden wird, ging Entmenschlichung nicht mit mehr Bereitschaft einher, bei Gewalt aus Nutzen dagegen schon. Daraus folgt aber weder, dass die Behauptung bestätigt ist, noch, dass Entmenschlichung gar keine Rolle spielt; Tiere kamen in den Studien nicht vor. Zwei Grenzen gehören dazu: Gemessen wurden Einstellungen und gedachte Szenarien, keine Taten, und Entmenschlichung nur als abgesprochenes Denken und Fühlen, nicht als Tiervergleich wie „Ungeziefer“. „Jede Gewalt“ ist also zu stark, „keine Gewalt“ wäre es ebenfalls.","coreRule":"⚡ Wer „jede“ oder „immer“ behauptet, braucht nur einen gut belegten Gegenfall zu fürchten: Entmenschlichung erklärt nicht jede Gewalt, denn wer „gerecht“ bestrafen will, braucht einen vollen Menschen als Ziel.","beleg":"Werkstück B.16 (Hinweis zur Beleglage); Fn. gl-b-rai (Rai/Valdesolo/Graham 2017, PNAS 114(32), S. 8511–8516); Fn. gl-b-kteily-folter (Kteily u. a. 2015, JPSP 109(5), S. 901–931)","status":"entwurf","scenario":"In Experimenten und Befragungen mit Online-Teilnehmern (Einstellungsfragen und gedachte Szenarien, keine echten Täter) wurde die Bereitschaft zu zwei Arten von Gewalt erhoben: Gewalt aus Nutzen (etwa einem Fremden für Geld schaden) und Gewalt, die als gerecht empfunden wird (etwa Strafe für ein Fehlverhalten). Entmenschlichung wurde dabei als abgesprochene Fähigkeit zu denken und zu fühlen gemessen. Ergebnis: Wer ein Opfer stärker entmenschlichte, war eher zu Gewalt aus Nutzen bereit. Bei Gewalt, die als gerecht empfunden wird, zeigte sich dieser Zusammenhang nicht; wer sich vorstellte, einen Fremden für sein Fehlverhalten zu bestrafen, hielt ihn sogar für menschlicher.","kurz":"Die Behauptung verallgemeinert: Entmenschlichung ging mit mehr Bereitschaft zu Gewalt aus Nutzen einher, nicht aber zu Gewalt, die als gerecht empfunden wird. Eine Gewaltart ohne diesen Zusammenhang widerlegt „jede Gewalt“, bestreitet aber nicht jeden Einfluss.","prueffrage":"Wie wurden Gewaltbereitschaft und Entmenschlichung in den Studien gemessen, und wie nah ist das an dem, wovon die Politikerin spricht?","rueckmeldung":[{"option":0,"text":"Dass sich der Zusammenhang bei Gewalt aus Nutzen zeigte, stützt die Behauptung nur für diese Gewaltart. „Jede Gewalt“ ist damit nicht bestätigt, zumal er bei Gewalt, die als gerecht empfunden wird, fehlte."},{"option":2,"text":"Dass die Behauptung zu weit geht, stimmt. Daraus folgt aber nicht, dass Entmenschlichung gar keine Rolle spielt: Bei Gewalt aus Nutzen ging sie mit mehr Bereitschaft einher. „Keine Gewalt“ wäre ebenso überzogen wie „jede Gewalt“."},{"option":3,"text":"Tiere kamen in diesen Studien gar nicht vor, untersucht wurde Gewalt gegen Menschen. Diese Begründung erfindet einen Befund, statt den tatsächlichen Unterschied zwischen den beiden Gewaltarten zu nutzen."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Rai, T. S.; Valdesolo, P.; Graham, J. (2017): Dehumanization increases instrumental violence, but not moral violence. PNAS 114(32), 8511–8516 (frei in PMC5559031)","oeffentlich":true,"doi":"10.1073/pnas.1705238114","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-b1-059","clusterId":"B","werkstueckRef":"B.16","stufe":4,"question":"Welche Beurteilung wird dieser Sprache am besten gerecht?","scenario":"In einem Forum lest ihr Kommentare, die eine Gruppe von Menschen durchgehend „Ungeziefer“ und „Seuche“ nennen und von der „Säuberung“ der Gesellschaft sprechen. Zu Gewalt wird nirgends ausdrücklich aufgerufen. Eine Mitleserin meint: „Das ist doch nur Wut, das darf man nicht so ernst nehmen.“","options":["Es ist bloße Zuspitzung, denn ohne ausdrücklichen Aufruf zu Gewalt drückt die Wortwahl nur Ärger aus und bleibt folgenlos.","Es ist normale Wut im Netz, denn solche Ausbrüche verpuffen meist von selbst und brauchen keine weitere Beachtung.","Es ist ein Warnsignal, denn die Gleichsetzung einer ganzen Gruppe mit Ungeziefer senkt die Hemmung vor Gewalt, auch ohne offenen Aufruf.","Es ist übliche politische Kritik, denn scharfe Bilder gehören zur Debatte und werden erst bei Minderheiten als Problem gesehen."],"correctIndex":2,"explanation":"Entscheidend ist, was die Sprache bewirkt, nicht ob sie einen ausdrücklichen Aufruf enthält. Ein einzelner Spruch wie „fauler Hund“ ist nur die mildeste Form der Entmenschlichung. Wird dagegen eine ganze Gruppe durchgehend mit Ungeziefer gleichgesetzt, als Seuche beschrieben und ihre Beseitigung als „Säuberung“ gerahmt, ist das etwas anderes: Sie wird aus dem Kreis derer herausgenommen, denen man moralische Rücksicht schuldet. Das kann Gewalt erleichtern, weil die Hemmung, Menschen zu schaden, bei „Ungeziefer“ weniger greift; nicht jede Gewalt erklärt sich allerdings so. In Ruanda 1994 gingen Monate der Hetze gegen „Kakerlaken“ dem Völkermord voraus. Die Sprache allein erklärt solche Taten nicht, denn Angst, Krieg und organisierte Mobilisierung kamen hinzu, aber sie lieferte die Wörter, die das Töten leichter machten. Die Einordnung als Warnsignal beurteilt die Sprache, nicht die Person, die sie benutzt. Der Gedanke, nur ein ausdrücklicher Aufruf sei gefährlich, ist ein Fehlschluss, denn die Vorbereitung geschieht meist unterhalb des Aufrufs. Auch „Das ist nur Wut“ prüft nicht, was die Wortwahl bewirkt. Und ob eine Minderheit betroffen ist, ändert nichts daran, dass systematische Entmenschlichung einer ganzen Gruppe, die darauf zielt, sie aus der moralischen Gemeinschaft auszuschließen, ein Alarmsignal der höchsten Stufe ist.","coreRule":"⚡ Wird eine ganze Gruppe durchgehend mit Ungeziefer gleichgesetzt und ihre Beseitigung als „Säuberung“ gerahmt, ist das ein Warnsignal, auch wenn kein offener Gewaltaufruf fällt.","beleg":"Werkstück B.16 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Entscheidend ist, was die Sprache bewirkt, nicht ob sie ausdrücklich zu Gewalt aufruft. Wer eine ganze Gruppe durchgehend zu Ungeziefer erklärt und von „Säuberung“ spricht, nimmt sie aus dem Kreis derer heraus, denen man Rücksicht schuldet. Das kann Gewalt erleichtern.","prueffrage":"Gegen wen richten sich die scharfen Wörter: gegen Meinungen und Handlungen oder gegen Menschen allein wegen ihrer Zugehörigkeit?","rueckmeldung":[{"option":0,"text":"Dass ein ausdrücklicher Aufruf fehlt, stimmt. Daraus folgt aber nicht, dass die Wortwahl harmlos bleibt: Die Vorbereitung von Gewalt läuft meist unterhalb des Aufrufs, über Bilder, die eine Gruppe aus der moralischen Rücksicht herausnehmen."},{"option":1,"text":"Vieles an Wut im Netz verpufft tatsächlich. Hier wird aber eine ganze Gruppe durchgehend als Seuche beschrieben, und es ist von einer „Säuberung“ der Gesellschaft die Rede. Wer das als bloße Wut abtut, prüft nicht, was diese Wortwahl bewirkt."},{"option":3,"text":"Scharfe Kritik gehört zur Debatte, trifft aber Positionen oder Handlungen. Hier wird eine ganze Gruppe zu Ungeziefer erklärt und von „Säuberung“ gesprochen. Das ist Entmenschlichung und ein Alarmsignal, ob eine Minderheit betroffen ist oder nicht."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Human Rights Watch (1999): Leave None to Tell the Story: Genocide in Rwanda, Kap. „Propaganda and Practice“","oeffentlich":true,"url":"https://www.hrw.org/reports/1999/rwanda/Geno1-3-10.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Haslam, N. (2006): Dehumanization: An Integrative Review. Personality and Social Psychology Review 10(3), 252–264 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/16859440/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Over, H. (2021): Seven Challenges for the Dehumanization Hypothesis. Perspectives on Psychological Science 16(1), 3–13 (frei in PMC7809340)","oeffentlich":true,"doi":"10.1177/1745691620902133","abruf":"2026-10-12"}],"thema":"Netz und Medien"}]`);export{t as n,n as t};